app=Flask(__name__)
app.secret_key=os.getenv("SATI_SECRET") or os.getenv("SECRET_KEY") or secrets.token_hex(32)
app.config.update(
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    SESSION_COOKIE_SECURE=os.getenv("SATI_COOKIE_SECURE","1") == "1",
)
DB=os.getenv("SATI_DB_PATH", os.path.join(os.path.dirname(__file__),"sati_v106.db"))
os.makedirs(os.path.dirname(os.path.abspath(DB)), exist_ok=True)

def con():
    c=sqlite3.connect(DB)
    c.row_factory=sqlite3.Row
    c.execute("PRAGMA foreign_keys=ON")
    return c

def ph(x): return hashlib.sha256(x.encode()).hexdigest()
def now(): return datetime.now().strftime("%Y-%m-%d %H:%M:%S")
def number(prefix): return prefix+"-"+datetime.now().strftime("%Y%m%d%H%M%S%f")

