def migrate_v17():
    c=con()
    for table,col,definition in [
        ("products","barcode","TEXT"),("products","min_stock","REAL DEFAULT 0"),
        ("partners","phone","TEXT"),("partners","email","TEXT"),("partners","tax_no","TEXT")]:
        try: c.execute(f"ALTER TABLE {table} ADD COLUMN {col} {definition}")
        except sqlite3.OperationalError: pass
    c.commit(); c.close()
migrate_v17()
