def seq(c,doc_type):
    r=c.execute("SELECT prefix,next_no FROM document_sequences WHERE doc_type=?",(doc_type,)).fetchone()
    if not r:
        c.execute("INSERT INTO document_sequences(doc_type,prefix,next_no) VALUES(?,?,2)",(doc_type,doc_type,)); return doc_type+"-000001"
    no=f"{r['prefix']}-{r['next_no']:06d}"
    c.execute("UPDATE document_sequences SET next_no=next_no+1 WHERE doc_type=?",(doc_type,))
    return no

def acc(c,code): return c.execute("SELECT id FROM accounts WHERE code=?",(code,)).fetchone()["id"]

def log(module,action,details=""):
    c=con(); c.execute("INSERT INTO audit(user_id,module,action,details,created_at) VALUES(?,?,?,?,?)",(session.get("uid"),module,action,details,now())); c.commit(); c.close()

def journal(c,desc,source,lines):
    debit=sum(x[1] for x in lines); credit=sum(x[2] for x in lines)
    if abs(debit-credit)>.005: raise ValueError("القيد المحاسبي غير متوازن")
    cur=c.execute("INSERT INTO journals(no,date,description,source) VALUES(?,?,?,?)",(number("JV"),now(),desc,source))
    jid=cur.lastrowid
    for aid,d,cr in lines: c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,aid,d,cr))

