@app.route("/invoice/<kind>",methods=["GET","POST"])
def invoice(kind):
    if not session.get("uid"): return redirect("/login")
    sale=kind=="sale"; c=con()
    if request.method=="POST":
        try:
            c.execute("BEGIN IMMEDIATE")
            partner=int(request.form["partner"]); wid=int(request.form["warehouse"]); payment=request.form["payment"]; cash=int(request.form["cash"]); discount=float(request.form.get("discount") or 0); payment_method=request.form.get("payment_method","cash")
            parsed=[]; subtotal=vat_total=cost_total=0
            for pid,q,pr in zip(request.form.getlist("product_id"),request.form.getlist("qty"),request.form.getlist("price")):
                if not pid or not q: continue
                p=c.execute("SELECT * FROM products WHERE id=?",(int(pid),)).fetchone(); qty=float(q); price=float(pr or (p["price"] if sale else p["cost"]))
                if qty<=0: continue
                st=c.execute("SELECT qty FROM stock WHERE warehouse_id=? AND product_id=?",(wid,p["id"])).fetchone()
                if sale and (not st or st["qty"]<qty): raise ValueError("الرصيد غير كاف: "+p["name"])
                sub=qty*price; vat=sub*p["vat"]/100; cost=qty*p["cost"]; parsed.append((p,qty,price,sub,vat,cost)); subtotal+=sub; vat_total+=vat; cost_total+=cost
            if not parsed: raise ValueError("أضف صنفًا")
            if discount<0 or discount>subtotal: raise ValueError("الخصم غير صحيح")
            # VAT is recalculated proportionally after invoice-level discount.
            ratio=(subtotal-discount)/subtotal if subtotal else 1
            vat_total=vat_total*ratio
            total=(subtotal-discount)+vat_total
            ino=seq(c,"SALE" if sale else "PURCHASE")
            cur=c.execute("INSERT INTO invoices(no,type,partner_id,warehouse_id,payment_type,cash_account_id,subtotal,vat,total,cost_total,date,status,discount,payment_method) VALUES(?,?,?,?,?,?,?,?,?,?,?,'POSTED',?,?)",(ino,"SALE" if sale else "PURCHASE",partner,wid,payment,cash,subtotal,vat_total,total,cost_total,now(),discount,payment_method))
            iid=cur.lastrowid
            for p,qty,price,sub,vat,cost in parsed:
                c.execute("INSERT INTO invoice_lines(invoice_id,product_id,qty,price,cost,vat_rate,subtotal,vat,total) VALUES(?,?,?,?,?,?,?,?,?)",(iid,p["id"],qty,price,p["cost"],p["vat"],sub,vat,sub+vat))
                c.execute("INSERT OR IGNORE INTO stock VALUES(?,?,0)",(wid,p["id"]))
                c.execute("UPDATE stock SET qty=qty+? WHERE warehouse_id=? AND product_id=?",(-qty if sale else qty,wid,p["id"]))
                c.execute("INSERT INTO stock_moves(no,type,warehouse_id,product_id,qty,reference,created_at,user_id) VALUES(?,?,?,?,?,?,?,?)",(ino,"OUT" if sale else "IN",wid,p["id"],qty,ino,now(),session["uid"]))
            if payment=="credit": c.execute("UPDATE partners SET balance=balance+? WHERE id=?",(total,partner))
            else:
                bal=c.execute("SELECT balance FROM accounts WHERE id=?",(cash,)).fetchone()["balance"]
                if not sale and bal<total: raise ValueError("رصيد الصندوق أو البنك غير كاف")
                c.execute("UPDATE accounts SET balance=balance+? WHERE id=?",(total if sale else -total,cash))
            if sale:
                lines=[(acc(c,"1100") if payment=="credit" else cash,total,0),(acc(c,"4100"),0,subtotal-discount),(acc(c,"2200"),0,vat_total),(acc(c,"5100"),cost_total,0),(acc(c,"1200"),0,cost_total)]
            else:
                lines=[(acc(c,"1200"),subtotal-discount,0),(acc(c,"1300"),vat_total,0),(acc(c,"2100") if payment=="credit" else cash,0,total)]
            journal(c,("بيع " if sale else "شراء ")+ino,ino,lines)
            c.commit(); log("sales" if sale else "purchases","post",ino); flash("تم اعتماد الفاتورة وترحيلها بالكامل"); return redirect("/")
        except Exception as e:
            c.rollback(); flash("أُلغي الحفظ بالكامل: "+str(e)); return redirect(request.url)
        finally: c.close()
    partners=c.execute("SELECT * FROM partners WHERE type=?",("customer" if sale else "supplier",)).fetchall(); wh=c.execute("SELECT * FROM warehouses WHERE active=1").fetchall(); products=c.execute("SELECT * FROM products").fetchall(); cashs=c.execute("SELECT * FROM accounts WHERE code IN('1010','1020')").fetchall(); c.close()
    po="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in partners); wo="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in wh); ao="".join(f"<option value='{x['id']}'>{x['name']} ({x['balance']:.2f})</option>" for x in cashs); pro="".join(f"<option value='{x['id']}'>{x['code']} — {x['name']}</option>" for x in products)
    title="فاتورة بيع" if sale else "فاتورة شراء"
    body=f"""<h1>{title} متعددة الأصناف</h1><form method=post><div class=panel><select name=partner>{po}</select> <select name=warehouse>{wo}</select> <select name=payment><option value=cash>فوري</option><option value=credit>آجل</option></select>
<select name=payment_method><option value=cash>نقدي</option><option value=card>بطاقة</option><option value=bank>تحويل بنكي</option><option value=mixed>متعدد</option></select>
<input name=discount type=number step=.01 min=0 value=0 placeholder="خصم الفاتورة"> <select name=cash>{ao}</select></div><div id=lines></div><button type=button onclick='add()'>+ صنف</button> <button>اعتماد وترحيل</button></form><template id=tpl><div class='panel line'><select name=product_id required><option value=''>اختر الصنف</option>{pro}</select><input name=qty type=number step=.01 min=.01 placeholder=الكمية required><input name=price type=number step=.01 placeholder='السعر اختياري'><button type=button onclick='this.parentElement.remove()'>حذف</button></div></template><script>function add(){{lines.append(tpl.content.cloneNode(true))}}add();add();</script>"""
    return page(body)

@app.route("/stock")
def stock():
    if not session.get("uid"): return redirect("/login")
    c=con(); rows=c.execute("SELECT w.name warehouse,p.code,p.name,s.qty FROM stock s JOIN warehouses w ON w.id=s.warehouse_id JOIN products p ON p.id=s.product_id ORDER BY w.id,p.name").fetchall(); c.close()
    r="".join(f"<tr><td>{x['warehouse']}</td><td>{x['code']}</td><td>{x['name']}</td><td>{x['qty']}</td></tr>" for x in rows)
    return page("<h1>المخزون</h1><table><tr><th>المستودع</th><th>الكود</th><th>الصنف</th><th>الرصيد</th></tr>"+r+"</table>")

