@app.route("/payments",methods=["GET","POST"])
def payments():
    if not session.get("uid"): return redirect("/login")
    c=con()
    if request.method=="POST":
        try:
            c.execute("BEGIN IMMEDIATE")
            typ=request.form["type"]; pid=int(request.form["partner"]); aid=int(request.form["account"]); amount=float(request.form["amount"]); desc=request.form.get("description","")
            if amount<=0: raise ValueError("المبلغ يجب أن يكون أكبر من صفر")
            p=c.execute("SELECT * FROM partners WHERE id=?",(pid,)).fetchone()
            if not p: raise ValueError("العميل أو المورد غير موجود")
            if typ=="RECEIPT" and p["type"]!="customer": raise ValueError("سند القبض مخصص للعملاء")
            if typ=="PAYMENT" and p["type"]!="supplier": raise ValueError("سند الصرف مخصص للموردين")
            if amount>p["balance"]: raise ValueError("المبلغ أكبر من الرصيد المستحق")
            if typ=="PAYMENT":
                bal=c.execute("SELECT balance FROM accounts WHERE id=?",(aid,)).fetchone()["balance"]
                if bal<amount: raise ValueError("رصيد الصندوق أو البنك غير كاف")
            no=number("RCV" if typ=="RECEIPT" else "PAY")
            c.execute("INSERT INTO payments(no,type,partner_id,account_id,amount,date,description) VALUES(?,?,?,?,?,?,?)",(no,typ,pid,aid,amount,now(),desc))
            c.execute("UPDATE partners SET balance=balance-? WHERE id=?",(amount,pid))
            c.execute("UPDATE accounts SET balance=balance+? WHERE id=?",(amount if typ=="RECEIPT" else -amount,aid))
            if typ=="RECEIPT": lines=[(aid,amount,0),(acc(c,"1100"),0,amount)]
            else: lines=[(acc(c,"2100"),amount,0),(aid,0,amount)]
            journal(c,("سند قبض " if typ=="RECEIPT" else "سند صرف ")+no,no,lines)
            c.commit(); log("finance","payment",no); flash("تم حفظ السند وترحيل القيد"); return redirect("/payments")
        except Exception as e:
            c.rollback(); flash("أُلغي الحفظ: "+str(e)); return redirect("/payments")
        finally: c.close()
    ps=c.execute("SELECT * FROM partners WHERE balance>0 ORDER BY type,name").fetchall()
    ac=c.execute("SELECT * FROM accounts WHERE code IN('1010','1020')").fetchall(); c.close()
    po="".join(f"<option value='{x['id']}'>{'عميل' if x['type']=='customer' else 'مورد'} — {x['name']} — {x['balance']:.2f}</option>" for x in ps)
    ao="".join(f"<option value='{x['id']}'>{x['name']} — {x['balance']:.2f}</option>" for x in ac)
    return page(f"<h1>سندات القبض والصرف</h1><form method=post class=panel><select name=type><option value=RECEIPT>قبض من عميل</option><option value=PAYMENT>صرف لمورد</option></select> <select name=partner>{po}</select> <select name=account>{ao}</select> <input name=amount type=number step=.01 min=.01 required placeholder=المبلغ> <input name=description placeholder=البيان> <button>حفظ وترحيل</button></form>")

@app.route("/returns",methods=["GET","POST"])
def returns():
    if not session.get("uid"): return redirect("/login")
    c=con()
    if request.method=="POST":
        try:
            c.execute("BEGIN IMMEDIATE")
            iid=int(request.form["invoice"]); ilid=int(request.form["line"]); qty=float(request.form["qty"])
            inv=c.execute("SELECT * FROM invoices WHERE id=?",(iid,)).fetchone()
            line=c.execute("SELECT l.*,p.name FROM invoice_lines l JOIN products p ON p.id=l.product_id WHERE l.id=? AND l.invoice_id=?",(ilid,iid)).fetchone()
            if not inv or not line or qty<=0: raise ValueError("بيانات المرتجع غير صحيحة")
            returned=c.execute("SELECT coalesce(sum(qty),0) q FROM return_lines WHERE invoice_line_id=?",(ilid,)).fetchone()["q"]
            if returned+qty>line["qty"]: raise ValueError("كمية المرتجع تتجاوز الكمية المباعة/المشتراة")
            sub=qty*line["price"]; vat=sub*line["vat_rate"]/100; total=sub+vat; cost=qty*line["cost"]; rno=number("SR" if inv["type"]=="SALE" else "PR")
            cur=c.execute("INSERT INTO returns(no,type,invoice_id,partner_id,warehouse_id,subtotal,vat,total,cost_total,date) VALUES(?,?,?,?,?,?,?,?,?,?)",(rno,inv["type"],iid,inv["partner_id"],inv["warehouse_id"],sub,vat,total,cost,now()))
            rid=cur.lastrowid
            c.execute("INSERT INTO return_lines(return_id,invoice_line_id,product_id,qty,price,cost,vat,total) VALUES(?,?,?,?,?,?,?,?)",(rid,ilid,line["product_id"],qty,line["price"],line["cost"],vat,total))
            delta=qty if inv["type"]=="SALE" else -qty
            st=c.execute("SELECT qty FROM stock WHERE warehouse_id=? AND product_id=?",(inv["warehouse_id"],line["product_id"])).fetchone()
            if inv["type"]=="PURCHASE" and (not st or st["qty"]<qty): raise ValueError("المخزون غير كاف لمرتجع الشراء")
            c.execute("UPDATE stock SET qty=qty+? WHERE warehouse_id=? AND product_id=?",(delta,inv["warehouse_id"],line["product_id"]))
            c.execute("INSERT INTO stock_moves(no,type,warehouse_id,product_id,qty,reference,created_at,user_id) VALUES(?,?,?,?,?,?,?,?)",(rno,"RETURN-IN" if inv["type"]=="SALE" else "RETURN-OUT",inv["warehouse_id"],line["product_id"],qty,rno,now(),session["uid"]))
            if inv["payment_type"]=="credit":
                c.execute("UPDATE partners SET balance=max(balance-?,0) WHERE id=?",(total,inv["partner_id"]))
            else:
                c.execute("UPDATE accounts SET balance=balance+? WHERE id=?",(-total if inv["type"]=="SALE" else total,inv["cash_account_id"]))
            if inv["type"]=="SALE":
                lines=[(acc(c,"4100"),sub,0),(acc(c,"2200"),vat,0),(acc(c,"1100") if inv["payment_type"]=="credit" else inv["cash_account_id"],0,total),(acc(c,"1200"),cost,0),(acc(c,"5100"),0,cost)]
            else:
                lines=[(acc(c,"2100") if inv["payment_type"]=="credit" else inv["cash_account_id"],total,0),(acc(c,"1200"),0,sub),(acc(c,"1300"),0,vat)]
            journal(c,"مرتجع "+rno,rno,lines); c.commit(); log("returns","post",rno); flash("تم اعتماد المرتجع الجزئي وترحيله"); return redirect("/returns")
        except Exception as e:
            c.rollback(); flash("أُلغي المرتجع: "+str(e)); return redirect("/returns")
        finally: c.close()
    invs=c.execute("SELECT i.id,i.no,i.type,p.name partner FROM invoices i JOIN partners p ON p.id=i.partner_id ORDER BY i.id DESC").fetchall()
    lines=c.execute("SELECT l.id,l.invoice_id,p.name,l.qty FROM invoice_lines l JOIN products p ON p.id=l.product_id ORDER BY l.id DESC").fetchall(); c.close()
    io="".join(f"<option value='{x['id']}'>{x['no']} — {x['partner']}</option>" for x in invs)
    lo="".join(f"<option value='{x['id']}'>{x['name']} — كمية الأصل {x['qty']} — فاتورة #{x['invoice_id']}</option>" for x in lines)
    return page(f"<h1>المرتجعات الجزئية</h1><div class=panel><p>اختر الفاتورة ثم سطر الصنف التابع لها.</p><form method=post><select name=invoice>{io}</select> <select name=line>{lo}</select> <input name=qty type=number step=.01 min=.01 required placeholder='كمية المرتجع'> <button>اعتماد المرتجع</button></form></div>")

