@app.route("/quotation-convert/<int:qid>",methods=["POST"])
def quotation_convert(qid):
    if not session.get("uid"):return redirect("/login")
    c=con()
    try:
        c.execute("BEGIN IMMEDIATE")
        q=c.execute("SELECT * FROM quotations WHERE id=?",(qid,)).fetchone()
        if not q or q["converted_invoice_id"]:raise ValueError("عرض السعر غير متاح للتحويل")
        ls=c.execute("SELECT * FROM quotation_lines WHERE quotation_id=?",(qid,)).fetchall()
        if not ls:raise ValueError("عرض السعر فارغ")
        wid=int(request.form.get("warehouse",1));cash=acc(c,"1010");subtotal=sum(x["qty"]*x["price"] for x in ls);vat=sum(x["vat"] for x in ls);total=subtotal+vat;cost_total=0
        ino=seq(c,"SALE")
        cur=c.execute("INSERT INTO invoices(no,type,partner_id,warehouse_id,payment_type,cash_account_id,subtotal,vat,total,cost_total,date,status,discount,payment_method) VALUES(?,?,?,?,?,?,?,?,?,?,?,'POSTED',0,'cash')",(ino,"SALE",q["partner_id"],wid,"cash",cash,subtotal,vat,total,0,now()));iid=cur.lastrowid
        for x in ls:
            p=c.execute("SELECT * FROM products WHERE id=?",(x["product_id"],)).fetchone();st=c.execute("SELECT qty FROM stock WHERE warehouse_id=? AND product_id=?",(wid,p["id"])).fetchone()
            if not st or st["qty"]<x["qty"]:raise ValueError("المخزون غير كاف: "+p["name"])
            cost=x["qty"]*p["cost"];cost_total+=cost
            c.execute("INSERT INTO invoice_lines(invoice_id,product_id,qty,price,cost,vat_rate,subtotal,vat,total) VALUES(?,?,?,?,?,?,?,?,?)",(iid,p["id"],x["qty"],x["price"],p["cost"],p["vat"],x["qty"]*x["price"],x["vat"],x["total"]))
            c.execute("UPDATE stock SET qty=qty-? WHERE warehouse_id=? AND product_id=?",(x["qty"],wid,p["id"]))
        c.execute("UPDATE invoices SET cost_total=? WHERE id=?",(cost_total,iid));c.execute("UPDATE accounts SET balance=balance+? WHERE id=?",(total,cash))
        journal(c,"تحويل عرض سعر "+q["no"],ino,[(cash,total,0),(acc(c,"4100"),0,subtotal),(acc(c,"2200"),0,vat),(acc(c,"5100"),cost_total,0),(acc(c,"1200"),0,cost_total)])
        c.execute("UPDATE quotations SET status='CONVERTED',converted_invoice_id=? WHERE id=?",(iid,qid));c.commit();log("sales","quotation_convert",q["no"]+" -> "+ino);flash("تم تحويل عرض السعر إلى فاتورة "+ino)
    except Exception as e:c.rollback();flash("فشل التحويل: "+str(e))
    finally:c.close()
    return redirect("/quotations")

@app.route("/po-convert/<int:oid>",methods=["POST"])
def po_convert(oid):
    if not session.get("uid"):return redirect("/login")
    c=con()
    try:
        c.execute("BEGIN IMMEDIATE")
        q=c.execute("SELECT * FROM purchase_orders WHERE id=?",(oid,)).fetchone()
        if not q or q["converted_invoice_id"]:raise ValueError("أمر الشراء غير متاح")
        ls=c.execute("SELECT * FROM purchase_order_lines WHERE po_id=?",(oid,)).fetchall();wid=int(request.form.get("warehouse",1));subtotal=sum(x["qty"]*x["price"] for x in ls);vat=sum(x["vat"] for x in ls);total=subtotal+vat;ino=seq(c,"PURCHASE")
        cur=c.execute("INSERT INTO invoices(no,type,partner_id,warehouse_id,payment_type,cash_account_id,subtotal,vat,total,cost_total,date,status,discount,payment_method) VALUES(?,?,?,?,?,?,?,?,?,?,?,'POSTED',0,'credit')",(ino,"PURCHASE",q["partner_id"],wid,"credit",acc(c,"1010"),subtotal,vat,total,subtotal,now()));iid=cur.lastrowid
        for x in ls:
            p=c.execute("SELECT * FROM products WHERE id=?",(x["product_id"],)).fetchone();c.execute("INSERT INTO invoice_lines(invoice_id,product_id,qty,price,cost,vat_rate,subtotal,vat,total) VALUES(?,?,?,?,?,?,?,?,?)",(iid,p["id"],x["qty"],x["price"],p["cost"],p["vat"],x["qty"]*x["price"],x["vat"],x["total"]));c.execute("INSERT OR IGNORE INTO stock VALUES(?,?,0)",(wid,p["id"]));c.execute("UPDATE stock SET qty=qty+? WHERE warehouse_id=? AND product_id=?",(x["qty"],wid,p["id"]))
        c.execute("UPDATE partners SET balance=balance+? WHERE id=?",(total,q["partner_id"]));journal(c,"تحويل أمر شراء "+q["no"],ino,[(acc(c,"1200"),subtotal,0),(acc(c,"1300"),vat,0),(acc(c,"2100"),0,total)]);c.execute("UPDATE purchase_orders SET status='CONVERTED',converted_invoice_id=? WHERE id=?",(iid,oid));c.commit();log("purchases","po_convert",q["no"]+" -> "+ino);flash("تم تحويل أمر الشراء إلى فاتورة "+ino)
    except Exception as e:c.rollback();flash("فشل التحويل: "+str(e))
    finally:c.close()
    return redirect("/purchase-orders")


@app.route("/dashboard")
def dashboard():
    if not session.get("uid"):return redirect("/login")
    c=con()
    today=datetime.now().strftime("%Y-%m-%d")
    month=datetime.now().strftime("%Y-%m")
    day_sales=c.execute("SELECT coalesce(sum(total),0) x FROM invoices WHERE type='SALE' AND substr(date,1,10)=?",(today,)).fetchone()["x"]
    month_sales=c.execute("SELECT coalesce(sum(total),0) x FROM invoices WHERE type='SALE' AND substr(date,1,7)=?",(month,)).fetchone()["x"]
    receivables=c.execute("SELECT coalesce(sum(balance),0) x FROM partners WHERE type='customer'").fetchone()["x"]
    low=c.execute("""SELECT count(*) x FROM stock s JOIN products p ON p.id=s.product_id WHERE p.min_stock>0 AND s.qty<=p.min_stock""").fetchone()["x"]
    recent=c.execute("""SELECT i.id,i.no,i.date,p.name partner,i.total FROM invoices i JOIN partners p ON p.id=i.partner_id WHERE i.type='SALE' ORDER BY i.id DESC LIMIT 10""").fetchall()
    c.close()
    rows="".join(f"<tr><td>{x['no']}</td><td>{x['date']}</td><td>{x['partner']}</td><td>{x['total']:.2f}</td><td><a href='/invoice-print/{x['id']}'>طباعة</a></td></tr>" for x in recent)
    return page(f"""<h1>لوحة المؤشرات</h1><div class=cards><div class=card>مبيعات اليوم<strong>{day_sales:.2f}</strong></div><div class=card>مبيعات الشهر<strong>{month_sales:.2f}</strong></div><div class=card>ذمم العملاء<strong>{receivables:.2f}</strong></div><div class=card>تنبيهات المخزون<strong>{low}</strong></div></div><h2>آخر المبيعات</h2><table><tr><th>الفاتورة</th><th>التاريخ</th><th>العميل</th><th>الإجمالي</th><th></th></tr>{rows}</table>""")

@app.route("/pos",methods=["GET","POST"])
def pos():
    if not session.get("uid"):return redirect("/login")
    c=con()
    if request.method=="POST":
        try:
            c.execute("BEGIN IMMEDIATE")
            barcode=request.form["barcode"].strip(); qty=float(request.form.get("qty") or 1); wid=int(request.form.get("warehouse") or 1); partner=int(request.form.get("partner") or 1); method=request.form.get("method","cash")
            p=c.execute("SELECT * FROM products WHERE barcode=? OR code=?",(barcode,barcode)).fetchone()
            if not p:raise ValueError("الباركود أو كود الصنف غير موجود")
            st=c.execute("SELECT qty FROM stock WHERE warehouse_id=? AND product_id=?",(wid,p["id"])).fetchone()
            if qty<=0 or not st or st["qty"]<qty:raise ValueError("الرصيد غير كاف")
            sub=qty*p["price"];vat=sub*p["vat"]/100;total=sub+vat;cost=qty*p["cost"];cash=acc(c,"1010");ino=seq(c,"SALE")
            cur=c.execute("INSERT INTO invoices(no,type,partner_id,warehouse_id,payment_type,cash_account_id,subtotal,vat,total,cost_total,date,status,discount,payment_method) VALUES(?,?,?,?,?,?,?,?,?,?,?,'POSTED',0,?)",(ino,"SALE",partner,wid,"cash",cash,sub,vat,total,cost,now(),method));iid=cur.lastrowid
            c.execute("INSERT INTO invoice_lines(invoice_id,product_id,qty,price,cost,vat_rate,subtotal,vat,total) VALUES(?,?,?,?,?,?,?,?,?)",(iid,p["id"],qty,p["price"],p["cost"],p["vat"],sub,vat,total))
            c.execute("UPDATE stock SET qty=qty-? WHERE warehouse_id=? AND product_id=?",(qty,wid,p["id"]))
            c.execute("INSERT INTO stock_moves(no,type,warehouse_id,product_id,qty,reference,created_at,user_id) VALUES(?,?,?,?,?,?,?,?)",(ino,"POS-OUT",wid,p["id"],qty,ino,now(),session["uid"]))
            c.execute("UPDATE accounts SET balance=balance+? WHERE id=?",(total,cash))
            journal(c,"بيع نقطة بيع "+ino,ino,[(cash,total,0),(acc(c,"4100"),0,sub),(acc(c,"2200"),0,vat),(acc(c,"5100"),cost,0),(acc(c,"1200"),0,cost)])
            c.commit();log("pos","sale",ino);flash("تم البيع — "+ino);return redirect("/invoice-print/"+str(iid))
        except Exception as e:c.rollback();flash("تعذر البيع: "+str(e));return redirect("/pos")
        finally:c.close()
    wh=c.execute("SELECT * FROM warehouses WHERE active=1").fetchall();customers=c.execute("SELECT * FROM partners WHERE type='customer'").fetchall();c.close()
    wo="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in wh);co="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in customers)
    return page(f"""<h1>نقطة البيع POS</h1><div class=panel><p>امسح الباركود أو اكتب كود الصنف ثم اضغط بيع.</p><form method=post><input autofocus name=barcode placeholder="باركود / كود الصنف" required style="font-size:20px"> <input name=qty type=number step=.01 min=.01 value=1> <select name=warehouse>{wo}</select> <select name=partner>{co}</select> <select name=method><option value=cash>نقدي</option><option value=card>بطاقة</option><option value=bank>تحويل</option></select> <button style="font-size:18px">بيع وطباعة</button></form></div>""")

@app.route("/sales-analytics")
def sales_analytics():
    if not session.get("uid"):return redirect("/login")
    c=con()
    daily=c.execute("""SELECT substr(date,1,10) d,count(*) n,sum(total) total FROM invoices WHERE type='SALE' GROUP BY substr(date,1,10) ORDER BY d DESC LIMIT 31""").fetchall()
    monthly=c.execute("""SELECT substr(date,1,7) m,count(*) n,sum(total) total FROM invoices WHERE type='SALE' GROUP BY substr(date,1,7) ORDER BY m DESC LIMIT 12""").fetchall()
    products=c.execute("""SELECT p.code,p.name,sum(l.qty) qty,sum(l.total) total FROM invoice_lines l JOIN invoices i ON i.id=l.invoice_id JOIN products p ON p.id=l.product_id WHERE i.type='SALE' GROUP BY p.id ORDER BY total DESC LIMIT 10""").fetchall()
    customers=c.execute("""SELECT p.name,count(i.id) n,sum(i.total) total FROM invoices i JOIN partners p ON p.id=i.partner_id WHERE i.type='SALE' GROUP BY p.id ORDER BY total DESC LIMIT 10""").fetchall();c.close()
    dr="".join(f"<tr><td>{x['d']}</td><td>{x['n']}</td><td>{x['total']:.2f}</td></tr>" for x in daily);mr="".join(f"<tr><td>{x['m']}</td><td>{x['n']}</td><td>{x['total']:.2f}</td></tr>" for x in monthly);pr="".join(f"<tr><td>{x['code']}</td><td>{x['name']}</td><td>{x['qty']:.2f}</td><td>{x['total']:.2f}</td></tr>" for x in products);cr="".join(f"<tr><td>{x['name']}</td><td>{x['n']}</td><td>{x['total']:.2f}</td></tr>" for x in customers)
    return page(f"""<h1>تحليل المبيعات</h1><h2>يومي</h2><table><tr><th>اليوم</th><th>الفواتير</th><th>المبيعات</th></tr>{dr}</table><h2>شهري</h2><table><tr><th>الشهر</th><th>الفواتير</th><th>المبيعات</th></tr>{mr}</table><h2>أفضل الأصناف</h2><table><tr><th>الكود</th><th>الصنف</th><th>الكمية</th><th>القيمة</th></tr>{pr}</table><h2>أفضل العملاء</h2><table><tr><th>العميل</th><th>الفواتير</th><th>القيمة</th></tr>{cr}</table>""")

