def current_shift(c):
    return c.execute("SELECT * FROM pos_shifts WHERE user_id=? AND status='OPEN' ORDER BY id DESC LIMIT 1",(session["uid"],)).fetchone()

@app.route("/shifts",methods=["GET","POST"])
def shifts():
    if not session.get("uid"):return redirect("/login")
    c=con()
    if request.method=="POST":
        action=request.form["action"]
        try:
            c.execute("BEGIN IMMEDIATE")
            sh=current_shift(c)
            if action=="open":
                if sh:raise ValueError("لديك وردية مفتوحة بالفعل")
                aid=int(request.form["account"]);opening=float(request.form.get("opening") or 0)
                branch_id=int(request.form.get("branch") or 1)
                c.execute("INSERT INTO pos_shifts(user_id,account_id,opened_at,opening_cash,status,branch_id) VALUES(?,?,?,?,\'OPEN\',?)",(session["uid"],aid,now(),opening,branch_id))
                msg="تم فتح الوردية"
            else:
                if not sh:raise ValueError("لا توجد وردية مفتوحة")
                closing=float(request.form.get("closing") or 0)
                c.execute("UPDATE pos_shifts SET closed_at=?,closing_cash=?,status='CLOSED' WHERE id=?",(now(),closing,sh["id"]))
                msg="تم إغلاق الوردية"
            c.commit();log("pos","shift_"+action,msg);flash(msg)
        except Exception as e:c.rollback();flash(str(e))
        finally:c.close()
        return redirect("/shifts")
    sh=current_shift(c);acs=c.execute("SELECT * FROM accounts WHERE code IN('1010','1020')").fetchall();branches=c.execute("SELECT * FROM branches WHERE active=1").fetchall();c.close()
    ao="".join(f"<option value='{x['id']}'>{x['name']} — {x['balance']:.2f}</option>" for x in acs);bo="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in branches)
    status="<div class=card>لا توجد وردية مفتوحة</div>" if not sh else f"<div class=card>وردية مفتوحة منذ<strong>{sh['opened_at']}</strong>رصيد افتتاحي: {sh['opening_cash']:.2f}</div>"
    return page(f"""<h1>إدارة الورديات</h1>{status}<div class=panel><form method=post><input type=hidden name=action value=open><select name=branch>{bo}</select> <select name=account>{ao}</select> <input name=opening type=number step=.01 value=0 placeholder="رصيد الافتتاح"> <button>فتح وردية</button></form></div><div class=panel><form method=post><input type=hidden name=action value=close><input name=closing type=number step=.01 min=0 placeholder="النقد الفعلي عند الإغلاق" required> <button>إغلاق الوردية</button></form></div>""")

@app.route("/pos-v20",methods=["GET","POST"])
def pos_v20():
    if not session.get("uid"):return redirect("/login")
    c=con();sh=current_shift(c)
    if not sh:
        c.close();flash("افتح وردية أولًا");return redirect("/shifts")
    if request.method=="POST":
        action=request.form.get("action","sale")
        try:
            c.execute("BEGIN IMMEDIATE")
            pids=request.form.getlist("product_id");qtys=request.form.getlist("qty");parsed=[]
            for pid,q in zip(pids,qtys):
                if not pid or not q:continue
                p=c.execute("SELECT * FROM products WHERE id=?",(int(pid),)).fetchone();qty=float(q)
                if qty>0:parsed.append((p,qty))
            if not parsed:raise ValueError("السلة فارغة")
            partner=int(request.form["partner"]);wid=int(request.form["warehouse"]);method=request.form["method"]
            if action=="hold":
                hno=number("HOLD");cur=c.execute("INSERT INTO pos_holds(no,user_id,partner_id,warehouse_id,payment_method,created_at) VALUES(?,?,?,?,?,?)",(hno,session["uid"],partner,wid,method,now()));hid=cur.lastrowid
                for p,q in parsed:c.execute("INSERT INTO pos_hold_lines(hold_id,product_id,qty,price) VALUES(?,?,?,?)",(hid,p["id"],q,p["price"]))
                c.commit();log("pos","hold",hno);flash("تم تعليق السلة "+hno);return redirect("/pos-v22")
            subtotal=vat=cost=0
            for p,q in parsed:
                st=c.execute("SELECT qty FROM stock WHERE warehouse_id=? AND product_id=?",(wid,p["id"])).fetchone()
                if not st or st["qty"]<q:raise ValueError("الرصيد غير كاف: "+p["name"])
                subtotal+=q*p["price"];vat+=q*p["price"]*p["vat"]/100;cost+=q*p["cost"]
            total=subtotal+vat;ino=seq(c,"SALE");cash=sh["account_id"]
            cur=c.execute("INSERT INTO invoices(no,type,partner_id,warehouse_id,payment_type,cash_account_id,subtotal,vat,total,cost_total,date,status,discount,payment_method) VALUES(?,?,?,?,?,?,?,?,?,?,?,'POSTED',0,?)",(ino,"SALE",partner,wid,"cash",cash,subtotal,vat,total,cost,now(),method));iid=cur.lastrowid
            for p,q in parsed:
                sub=q*p["price"];v=sub*p["vat"]/100
                c.execute("INSERT INTO invoice_lines(invoice_id,product_id,qty,price,cost,vat_rate,subtotal,vat,total) VALUES(?,?,?,?,?,?,?,?,?)",(iid,p["id"],q,p["price"],p["cost"],p["vat"],sub,v,sub+v))
                c.execute("UPDATE stock SET qty=qty-? WHERE warehouse_id=? AND product_id=?",(q,wid,p["id"]))
                c.execute("INSERT INTO stock_moves(no,type,warehouse_id,product_id,qty,reference,created_at,user_id) VALUES(?,?,?,?,?,?,?,?)",(ino,"POS-OUT",wid,p["id"],q,ino,now(),session["uid"]))
            c.execute("UPDATE accounts SET balance=balance+? WHERE id=?",(total,cash))
            journal(c,"بيع POS "+ino,ino,[(cash,total,0),(acc(c,"4100"),0,subtotal),(acc(c,"2200"),0,vat),(acc(c,"5100"),cost,0),(acc(c,"1200"),0,cost)])
            c.commit();log("pos","multi_sale",ino);flash("تمت عملية البيع "+ino);return redirect("/invoice-thermal/"+str(iid))
        except Exception as e:c.rollback();flash("أُلغي البيع بالكامل: "+str(e));return redirect("/pos-v22")
        finally:c.close()
    products=c.execute("SELECT * FROM products ORDER BY name").fetchall();wh=c.execute("SELECT * FROM warehouses WHERE active=1").fetchall();customers=c.execute("SELECT * FROM partners WHERE type='customer'").fetchall();c.close()
    pro="".join(f"<option value='{x['id']}'>{x['code']} — {x['name']} — {x['price']:.2f}</option>" for x in products);wo="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in wh);co="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in customers)
    return page(f"""<h1>POS v20 — سلة متعددة الأصناف</h1><form method=post><div class=panel><select name=partner>{co}</select> <select name=warehouse>{wo}</select> <select name=method><option value=cash>نقدي</option><option value=card>بطاقة</option><option value=bank>تحويل</option></select></div><div id=cart></div><button type=button onclick=add()>+ إضافة صنف</button> <button name=action value=hold>تعليق السلة</button> <button name=action value=sale>إتمام البيع والطباعة</button></form><template id=ct><div class='panel line'><select name=product_id><option value=''>اختر الصنف</option>{pro}</select><input name=qty type=number step=.01 min=.01 value=1><span></span><button type=button onclick='this.parentElement.remove()'>حذف</button></div></template><script>function add(){{cart.append(ct.content.cloneNode(true))}}add();add();</script>""")

