@app.route("/expenses",methods=["GET","POST"])
def expenses():
    if not session.get("uid"):return redirect("/login")
    c=con();sh=current_shift(c)
    if request.method=="POST":
        try:
            if not sh:raise ValueError("افتح وردية أولًا")
            amount=float(request.form["amount"]);desc=request.form["description"]
            if amount<=0:raise ValueError("المبلغ غير صحيح")
            bal=c.execute("SELECT balance FROM accounts WHERE id=?",(sh["account_id"],)).fetchone()["balance"]
            if bal<amount:raise ValueError("رصيد الصندوق غير كاف")
            no=number("EXP");c.execute("INSERT INTO expenses(no,shift_id,account_id,amount,description,date,user_id) VALUES(?,?,?,?,?,?,?)",(no,sh["id"],sh["account_id"],amount,desc,now(),session["uid"]));c.execute("UPDATE accounts SET balance=balance-? WHERE id=?",(amount,sh["account_id"]))
            journal(c,"مصروف يومي "+desc,no,[(acc(c,"5100"),amount,0),(sh["account_id"],0,amount)])
            c.commit();log("finance","expense",no);flash("تم تسجيل المصروف")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/expenses")
    rows=c.execute("SELECT * FROM expenses ORDER BY id DESC LIMIT 100").fetchall();c.close()
    r="".join(f"<tr><td>{x['date']}</td><td>{x['no']}</td><td>{x['description']}</td><td>{x['amount']:.2f}</td></tr>" for x in rows)
    return page("<h1>المصروفات اليومية</h1><form method=post class=panel><input name=description placeholder='بيان المصروف' required> <input name=amount type=number step=.01 min=.01 placeholder=المبلغ required> <button>صرف وترحيل</button></form><table><tr><th>التاريخ</th><th>المستند</th><th>البيان</th><th>المبلغ</th></tr>"+r+"</table>")

@app.route("/shift-report")
def shift_report():
    if not session.get("uid"):return redirect("/login")
    c=con();sh=current_shift(c)
    if not sh:
        sh=c.execute("SELECT * FROM pos_shifts WHERE user_id=? ORDER BY id DESC LIMIT 1",(session["uid"],)).fetchone()
    if not sh:c.close();return page("<h1>تقرير الوردية</h1><div class=msg>لا توجد ورديات</div>")
    end=sh["closed_at"] or now()
    sales=c.execute("SELECT coalesce(sum(total),0) x,count(*) n FROM invoices WHERE type='SALE' AND cash_account_id=? AND date>=? AND date<=?",(sh["account_id"],sh["opened_at"],end)).fetchone()
    exp=c.execute("SELECT coalesce(sum(amount),0) x FROM expenses WHERE shift_id=?",(sh["id"],)).fetchone()["x"]
    expected=sh["opening_cash"]+sales["x"]-exp
    variance=None if sh["closing_cash"] is None else sh["closing_cash"]-expected
    c.close()
    v="—" if variance is None else f"{variance:.2f}"
    return page(f"""<h1>تقرير الوردية #{sh['id']}</h1><div class=cards><div class=card>رصيد افتتاحي<strong>{sh['opening_cash']:.2f}</strong></div><div class=card>المبيعات<strong>{sales['x']:.2f}</strong><small>{sales['n']} فاتورة</small></div><div class=card>المصروفات<strong>{exp:.2f}</strong></div><div class=card>المتوقع بالصندوق<strong>{expected:.2f}</strong></div></div><div class=panel>الحالة: {sh['status']}<br>الافتتاح: {sh['opened_at']}<br>الإغلاق: {sh['closed_at'] or 'مفتوحة'}<br>النقد الفعلي: {sh['closing_cash'] if sh['closing_cash'] is not None else '—'}<br><b>فرق الصندوق: {v}</b></div>""")


