@app.route("/cash-count",methods=["GET","POST"])
def cash_count():
    if not session.get("uid"):return redirect("/login")
    c=con();sh=current_shift(c)
    if not sh:c.close();return page("<h1>جرد الصندوق</h1><div class=msg>لا توجد وردية مفتوحة</div>")
    sales=c.execute("SELECT coalesce(sum(total),0) x FROM invoices WHERE type='SALE' AND cash_account_id=? AND date>=?",(sh["account_id"],sh["opened_at"])).fetchone()["x"]
    exp=c.execute("SELECT coalesce(sum(amount),0) x FROM expenses WHERE shift_id=?",(sh["id"],)).fetchone()["x"];expected=sh["opening_cash"]+sales-exp
    if request.method=="POST":
        counted=float(request.form["counted"]);variance=counted-expected;c.execute("INSERT INTO cash_counts(shift_id,user_id,counted,expected,variance,created_at) VALUES(?,?,?,?,?,?)",(sh["id"],session["uid"],counted,expected,variance,now()));c.commit();c.close();log("pos","cash_count",f"{variance:.2f}");flash("تم حفظ الجرد. الفرق: %.2f"%variance);return redirect("/cash-count")
    rows=c.execute("SELECT * FROM cash_counts WHERE shift_id=? ORDER BY id DESC",(sh["id"],)).fetchall();c.close();r="".join(f"<tr><td>{x['created_at']}</td><td>{x['expected']:.2f}</td><td>{x['counted']:.2f}</td><td>{x['variance']:.2f}</td></tr>" for x in rows)
    return page(f"<h1>جرد الصندوق</h1><div class=card>المتوقع<strong>{expected:.2f}</strong></div><form method=post class=panel><input name=counted type=number step=.01 min=0 placeholder='المبلغ المعدود فعليًا' required> <button>حفظ الجرد</button></form><table><tr><th>التاريخ</th><th>المتوقع</th><th>الفعلي</th><th>الفرق</th></tr>{r}</table>")

@app.route("/fund-transfer",methods=["GET","POST"])
def fund_transfer():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            c.execute("BEGIN IMMEDIATE");fa=int(request.form["from"]);ta=int(request.form["to"]);amount=float(request.form["amount"]);desc=request.form.get("description","")
            if fa==ta or amount<=0:raise ValueError("بيانات التحويل غير صحيحة")
            bal=c.execute("SELECT balance FROM accounts WHERE id=?",(fa,)).fetchone()["balance"]
            if bal<amount:raise ValueError("الرصيد غير كاف")
            no=number("TRF");c.execute("INSERT INTO fund_transfers(no,from_account,to_account,amount,date,user_id,description) VALUES(?,?,?,?,?,?,?)",(no,fa,ta,amount,now(),session["uid"],desc));c.execute("UPDATE accounts SET balance=balance-? WHERE id=?",(amount,fa));c.execute("UPDATE accounts SET balance=balance+? WHERE id=?",(amount,ta));journal(c,"تحويل أموال "+no,no,[(ta,amount,0),(fa,0,amount)]);c.commit();log("finance","transfer",no);flash("تم التحويل والترحيل")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/fund-transfer")
    ac=c.execute("SELECT * FROM accounts WHERE code IN('1010','1020')").fetchall();rows=c.execute("""SELECT t.*,a.name fa,b.name ta FROM fund_transfers t JOIN accounts a ON a.id=t.from_account JOIN accounts b ON b.id=t.to_account ORDER BY t.id DESC LIMIT 100""").fetchall();c.close()
    ao="".join(f"<option value='{x['id']}'>{x['name']} — {x['balance']:.2f}</option>" for x in ac);r="".join(f"<tr><td>{x['date']}</td><td>{x['no']}</td><td>{x['fa']}</td><td>{x['ta']}</td><td>{x['amount']:.2f}</td></tr>" for x in rows)
    return page(f"<h1>تحويل بين الصندوق والبنك</h1><form method=post class=panel><select name=from>{ao}</select> <select name=to>{ao}</select> <input name=amount type=number step=.01 min=.01 required placeholder=المبلغ> <input name=description placeholder=البيان> <button>تحويل</button></form><table><tr><th>التاريخ</th><th>الرقم</th><th>من</th><th>إلى</th><th>المبلغ</th></tr>{r}</table>")

@app.route("/day-close",methods=["GET","POST"])
def day_close():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con();d=request.values.get("date") or datetime.now().strftime("%Y-%m-%d")
    sales=c.execute("SELECT coalesce(sum(total),0) x FROM invoices WHERE type='SALE' AND substr(date,1,10)=?",(d,)).fetchone()["x"];exp=c.execute("SELECT coalesce(sum(amount),0) x FROM expenses WHERE substr(date,1,10)=?",(d,)).fetchone()["x"];rec=c.execute("SELECT coalesce(sum(amount),0) x FROM payments WHERE type='RECEIPT' AND substr(date,1,10)=?",(d,)).fetchone()["x"];pay=c.execute("SELECT coalesce(sum(amount),0) x FROM payments WHERE type='PAYMENT' AND substr(date,1,10)=?",(d,)).fetchone()["x"]
    if request.method=="POST":
        try:c.execute("INSERT INTO day_closings(closing_date,user_id,closed_at,sales,expenses,receipts,payments,status) VALUES(?,?,?,?,?,?,?,'CLOSED')",(d,session["uid"],now(),sales,exp,rec,pay));c.commit();log("finance","day_close",d);flash("تم إقفال اليوم "+d)
        except sqlite3.IntegrityError:flash("هذا اليوم مقفل مسبقًا")
        c.close();return redirect("/day-close?date="+d)
    old=c.execute("SELECT * FROM day_closings ORDER BY closing_date DESC LIMIT 30").fetchall();c.close();r="".join(f"<tr><td>{x['closing_date']}</td><td>{x['sales']:.2f}</td><td>{x['expenses']:.2f}</td><td>{x['receipts']:.2f}</td><td>{x['payments']:.2f}</td></tr>" for x in old)
    return page(f"<h1>الإقفال اليومي</h1><form method=get class=panel><input type=date name=date value='{d}'> <button>عرض</button></form><div class=cards><div class=card>المبيعات<strong>{sales:.2f}</strong></div><div class=card>المصروفات<strong>{exp:.2f}</strong></div><div class=card>المقبوضات<strong>{rec:.2f}</strong></div><div class=card>المدفوعات<strong>{pay:.2f}</strong></div></div><form method=post><input type=hidden name=date value='{d}'><button>إقفال اليوم</button></form><h2>آخر الإقفالات</h2><table><tr><th>اليوم</th><th>المبيعات</th><th>المصروفات</th><th>المقبوضات</th><th>المدفوعات</th></tr>{r}</table>")


