@app.route("/pos-v22",methods=["GET","POST"])
def pos_v22():
    if not session.get("uid"):return redirect("/login")
    c=con();sh=current_shift(c)
    if not sh:c.close();flash("افتح وردية أولًا");return redirect("/shifts")
    if not branch_allowed(c,sh["branch_id"]):c.close();return ("غير مصرح بهذا الفرع",403)
    if request.method=="POST":
        try:
            c.execute("BEGIN IMMEDIATE");wid=int(request.form["warehouse"]);partner=int(request.form["partner"]);pids=request.form.getlist("product_id");qtys=request.form.getlist("qty");parsed=[]
            for pid,q in zip(pids,qtys):
                if pid and q:
                    p=c.execute("SELECT * FROM products WHERE id=?",(int(pid),)).fetchone();qty=float(q)
                    if qty>0:parsed.append((p,qty))
            if not parsed:raise ValueError("السلة فارغة")
            subtotal=vat=cost=0
            for p,q in parsed:
                st=c.execute("SELECT qty FROM stock WHERE warehouse_id=? AND product_id=?",(wid,p["id"])).fetchone()
                if not st or st["qty"]<q:raise ValueError("الرصيد غير كاف: "+p["name"])
                subtotal+=q*p["price"];vat+=q*p["price"]*p["vat"]/100;cost+=q*p["cost"]
            total=subtotal+vat
            cash_amt=float(request.form.get("cash_amount") or 0);card_amt=float(request.form.get("card_amount") or 0);bank_amt=float(request.form.get("bank_amount") or 0)
            if abs((cash_amt+card_amt+bank_amt)-total)>.01:raise ValueError("مجموع طرق الدفع يجب أن يساوي إجمالي الفاتورة %.2f"%total)
            ino=seq(c,"SALE");cash_acc=sh["account_id"];bank_acc=acc(c,"1020")
            cur=c.execute("INSERT INTO invoices(no,type,partner_id,warehouse_id,payment_type,cash_account_id,subtotal,vat,total,cost_total,date,status,discount,payment_method) VALUES(?,?,?,?,?,?,?,?,?,?,?,'POSTED',0,'mixed')",(ino,"SALE",partner,wid,"cash",cash_acc,subtotal,vat,total,cost,now()));iid=cur.lastrowid
            for p,q in parsed:
                sub=q*p["price"];v=sub*p["vat"]/100;c.execute("INSERT INTO invoice_lines(invoice_id,product_id,qty,price,cost,vat_rate,subtotal,vat,total) VALUES(?,?,?,?,?,?,?,?,?)",(iid,p["id"],q,p["price"],p["cost"],p["vat"],sub,v,sub+v));c.execute("UPDATE stock SET qty=qty-? WHERE warehouse_id=? AND product_id=?",(q,wid,p["id"]));c.execute("INSERT INTO stock_moves(no,type,warehouse_id,product_id,qty,reference,created_at,user_id) VALUES(?,?,?,?,?,?,?,?)",(ino,"POS-OUT",wid,p["id"],q,ino,now(),session["uid"]))
            lines=[]
            if cash_amt: c.execute("INSERT INTO invoice_payments(invoice_id,method,account_id,amount) VALUES(?,?,?,?)",(iid,"cash",cash_acc,cash_amt));c.execute("UPDATE accounts SET balance=balance+? WHERE id=?",(cash_amt,cash_acc));lines.append((cash_acc,cash_amt,0))
            if card_amt: c.execute("INSERT INTO invoice_payments(invoice_id,method,account_id,amount) VALUES(?,?,?,?)",(iid,"card",bank_acc,card_amt));c.execute("UPDATE accounts SET balance=balance+? WHERE id=?",(card_amt,bank_acc));lines.append((bank_acc,card_amt,0))
            if bank_amt: c.execute("INSERT INTO invoice_payments(invoice_id,method,account_id,amount) VALUES(?,?,?,?)",(iid,"bank",bank_acc,bank_amt));c.execute("UPDATE accounts SET balance=balance+? WHERE id=?",(bank_amt,bank_acc));lines.append((bank_acc,bank_amt,0))
            lines += [(acc(c,"4100"),0,subtotal),(acc(c,"2200"),0,vat),(acc(c,"5100"),cost,0),(acc(c,"1200"),0,cost)]
            journal(c,"بيع POS متعدد الدفع "+ino,ino,lines);c.commit()
            hid=session.pop("resume_hold",None)
            if hid:
                cc=con();cc.execute("DELETE FROM pos_hold_lines WHERE hold_id=?",(hid,));cc.execute("DELETE FROM pos_holds WHERE id=?",(hid,));cc.commit();cc.close()
            log("pos","mixed_sale",ino);flash("تم البيع "+ino);return redirect("/invoice-thermal/"+str(iid))
        except Exception as e:c.rollback();flash("أُلغي البيع: "+str(e));return redirect("/pos-v22")
        finally:c.close()
    products=c.execute("SELECT * FROM products ORDER BY name").fetchall();wh=c.execute("SELECT w.* FROM warehouses w WHERE active=1 AND coalesce(branch_id,1)=?",(sh["branch_id"],)).fetchall();customers=c.execute("SELECT * FROM partners WHERE type='customer'").fetchall()
    resume=session.get("resume_hold");resume_lines=[];resume_h=None
    if resume:
        resume_h=c.execute("SELECT * FROM pos_holds WHERE id=? AND user_id=?",(resume,session["uid"])).fetchone()
        if resume_h:resume_lines=c.execute("SELECT * FROM pos_hold_lines WHERE hold_id=?",(resume,)).fetchall()
    c.close()
    pro="".join(f"<option value='{x['id']}'>{x['code']} — {x['name']} — {x['price']:.2f}</option>" for x in products);wo="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in wh);co="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in customers)
    existing=""
    for x in resume_lines:
        existing+=f"<div class='panel line'><select name=product_id><option value='{x['product_id']}' selected>صنف #{x['product_id']} — مسترجع</option>{pro}</select><input name=qty type=number step=.01 min=.01 value='{x['qty']}'><span></span><button type=button onclick='this.parentElement.remove()'>حذف</button></div>"
    note=f"<div class=msg>تم تحميل السلة المعلقة {resume_h['no']} تلقائيًا.</div>" if resume_h else ""
    return page(f"""<h1>POS v22</h1>{note}<form method=post><div class=panel><select name=partner>{co}</select> <select name=warehouse>{wo}</select></div><div id=cart>{existing}</div><button type=button onclick=add()>+ صنف</button><div class=panel><h3>تقسيم الدفع</h3><input name=cash_amount type=number step=.01 min=0 value=0 placeholder="نقدي"> <input name=card_amount type=number step=.01 min=0 value=0 placeholder="بطاقة"> <input name=bank_amount type=number step=.01 min=0 value=0 placeholder="تحويل بنكي"> <button>إتمام البيع</button></div></form><template id=ct><div class='panel line'><select name=product_id><option value=''>اختر الصنف</option>{pro}</select><input name=qty type=number step=.01 min=.01 value=1><span></span><button type=button onclick='this.parentElement.remove()'>حذف</button></div></template><script>function add(){{cart.append(ct.content.cloneNode(true))}}if(cart.children.length==0)add();</script>""")

@app.route("/pos-returns",methods=["GET","POST"])
def pos_returns():
    if not session.get("uid"):return redirect("/login")
    c=con()
    if request.method=="POST":
        try:
            c.execute("BEGIN IMMEDIATE");ino=request.form["invoice"];iid=int(request.form["line"]);qty=float(request.form["qty"]);inv=c.execute("SELECT * FROM invoices WHERE no=? AND type='SALE'",(ino,)).fetchone()
            if not inv:raise ValueError("فاتورة البيع غير موجودة")
            ln=c.execute("SELECT * FROM invoice_lines WHERE id=? AND invoice_id=?",(iid,inv["id"])).fetchone()
            if not ln:raise ValueError("السطر غير موجود")
            prev=c.execute("""SELECT coalesce(sum(rl.qty),0) q FROM return_lines rl JOIN returns r ON r.id=rl.return_id WHERE rl.invoice_line_id=?""",(iid,)).fetchone()["q"]
            if qty<=0 or prev+qty>ln["qty"]:raise ValueError("كمية المرتجع غير صحيحة")
            sub=qty*ln["price"];v=sub*ln["vat_rate"]/100;total=sub+v;cost=qty*ln["cost"];rno=number("POSR")
            cur=c.execute("INSERT INTO returns(no,type,invoice_id,partner_id,warehouse_id,subtotal,vat,total,cost_total,date) VALUES(?,?,?,?,?,?,?,?,?,?)",(rno,"SALE",inv["id"],inv["partner_id"],inv["warehouse_id"],sub,v,total,cost,now()));rid=cur.lastrowid
            c.execute("INSERT INTO return_lines(return_id,invoice_line_id,product_id,qty,price,cost,vat,total) VALUES(?,?,?,?,?,?,?,?)",(rid,iid,ln["product_id"],qty,ln["price"],ln["cost"],v,total));c.execute("UPDATE stock SET qty=qty+? WHERE warehouse_id=? AND product_id=?",(qty,inv["warehouse_id"],ln["product_id"]));c.execute("INSERT INTO stock_moves(no,type,warehouse_id,product_id,qty,reference,created_at,user_id) VALUES(?,?,?,?,?,?,?,?)",(rno,"POS-RETURN",inv["warehouse_id"],ln["product_id"],qty,rno,now(),session["uid"]))
            aid=inv["cash_account_id"];c.execute("UPDATE accounts SET balance=balance-? WHERE id=?",(total,aid));journal(c,"مرتجع POS "+rno,rno,[(acc(c,"4100"),sub,0),(acc(c,"2200"),v,0),(aid,0,total),(acc(c,"1200"),cost,0),(acc(c,"5100"),0,cost)]);c.commit();log("pos","return",rno);flash("تم المرتجع "+rno)
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/pos-returns")
    invs=c.execute("SELECT no,date,total FROM invoices WHERE type='SALE' ORDER BY id DESC LIMIT 100").fetchall();lines=c.execute("""SELECT l.id,i.no,p.name,l.qty FROM invoice_lines l JOIN invoices i ON i.id=l.invoice_id JOIN products p ON p.id=l.product_id WHERE i.type='SALE' ORDER BY l.id DESC LIMIT 300""").fetchall();c.close()
    io="".join(f"<option value='{x['no']}'>{x['no']} — {x['date']} — {x['total']:.2f}</option>" for x in invs);lo="".join(f"<option value='{x['id']}'>{x['no']} — {x['name']} — {x['qty']}</option>" for x in lines)
    return page(f"<h1>مرتجعات POS</h1><form method=post class=panel><select name=invoice>{io}</select> <select name=line>{lo}</select> <input name=qty type=number step=.01 min=.01 placeholder='كمية المرتجع' required> <button>اعتماد المرتجع</button></form>")

@app.route("/branch-profit")
def branch_profit():
    if not session.get("uid"):return redirect("/login")
    c=con()
    branches=c.execute("""SELECT b.name,coalesce(sum(i.subtotal-i.discount),0) sales,coalesce(sum(i.cost_total),0) cost FROM branches b LEFT JOIN warehouses w ON w.branch_id=b.id LEFT JOIN invoices i ON i.warehouse_id=w.id AND i.type='SALE' GROUP BY b.id ORDER BY sales DESC""").fetchall()
    cashiers=c.execute("""SELECT u.name,count(i.id) invoices,coalesce(sum(i.subtotal-i.discount),0) sales,coalesce(sum(i.cost_total),0) cost FROM users u LEFT JOIN stock_moves m ON m.user_id=u.id AND m.type='POS-OUT' LEFT JOIN invoices i ON i.no=m.reference GROUP BY u.id ORDER BY sales DESC""").fetchall();c.close()
    br="".join(f"<tr><td>{x['name']}</td><td>{x['sales']:.2f}</td><td>{x['cost']:.2f}</td><td>{x['sales']-x['cost']:.2f}</td></tr>" for x in branches);cr="".join(f"<tr><td>{x['name']}</td><td>{x['invoices']}</td><td>{x['sales']:.2f}</td><td>{x['sales']-x['cost']:.2f}</td></tr>" for x in cashiers)
    return page(f"<h1>أرباح الفروع والكاشير</h1><h2>حسب الفرع</h2><table><tr><th>الفرع</th><th>صافي المبيعات قبل VAT</th><th>التكلفة</th><th>الربح الإجمالي</th></tr>{br}</table><h2>حسب المستخدم</h2><table><tr><th>المستخدم</th><th>الحركات</th><th>المبيعات</th><th>الربح الإجمالي</th></tr>{cr}</table>")


