@app.route("/payroll",methods=["GET","POST"])
def payroll():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            c.execute("BEGIN IMMEDIATE");eid=int(request.form["employee"]);period=request.form["period"];basic=float(request.form["basic"]);allow=float(request.form.get("allowances") or 0);ded=float(request.form.get("deductions") or 0);adv=float(request.form.get("advance_deduction") or 0);net=basic+allow-ded-adv
            if net<0:raise ValueError("صافي الراتب غير صحيح")
            exists=c.execute("SELECT 1 FROM payroll WHERE employee_id=? AND period=?",(eid,period)).fetchone()
            if exists:raise ValueError("تم إعداد راتب هذا الموظف لهذه الفترة")
            no=number("PAYR");c.execute("INSERT INTO payroll(no,employee_id,period,basic,allowances,deductions,advance_deduction,net,date,status) VALUES(?,?,?,?,?,?,?,?,?,'POSTED')",(no,eid,period,basic,allow,ded,adv,net,now()))
            if adv>0:
                row=c.execute("SELECT * FROM employee_advances WHERE employee_id=? AND status='OPEN' ORDER BY id LIMIT 1",(eid,)).fetchone()
                if row and adv>=row["amount"]:c.execute("UPDATE employee_advances SET status='CLOSED' WHERE id=?",(row["id"],))
            journal(c,"استحقاق راتب "+period+" "+no,no,[(acc(c,"5100"),basic+allow-ded,0),(acc(c,"2100"),0,net),(acc(c,"1100"),0,adv)] if adv>0 else [(acc(c,"5100"),basic+allow-ded,0),(acc(c,"2100"),0,net)])
            c.commit();log("hr","payroll",no);flash("تم ترحيل الراتب")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/payroll")
    es=c.execute("SELECT * FROM employees WHERE active=1 ORDER BY name").fetchall();rows=c.execute("""SELECT p.*,e.name FROM payroll p JOIN employees e ON e.id=p.employee_id ORDER BY p.id DESC LIMIT 200""").fetchall();c.close()
    eo="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in es);r="".join(f"<tr><td>{x['period']}</td><td>{x['name']}</td><td>{x['basic']:.2f}</td><td>{x['allowances']:.2f}</td><td>{x['deductions']:.2f}</td><td>{x['advance_deduction']:.2f}</td><td>{x['net']:.2f}</td></tr>" for x in rows)
    return page(f"""<h1>الرواتب</h1><form method=post class=panel><select name=employee>{eo}</select> <input name=period type=month required> <input name=basic type=number step=.01 min=0 placeholder="الراتب الأساسي" required> <input name=allowances type=number step=.01 min=0 value=0 placeholder="البدلات"> <input name=deductions type=number step=.01 min=0 value=0 placeholder="الخصومات"> <input name=advance_deduction type=number step=.01 min=0 value=0 placeholder="خصم السلفة"> <button>احتساب وترحيل</button></form><table><tr><th>الفترة</th><th>الموظف</th><th>الأساسي</th><th>البدلات</th><th>الخصومات</th><th>السلفة</th><th>الصافي</th></tr>{r}</table>""")

@app.route("/financial-statements")
def financial_statements():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    rows=c.execute("""SELECT a.code,a.name,a.type,coalesce(sum(l.debit),0) debit,coalesce(sum(l.credit),0) credit FROM accounts a LEFT JOIN journal_lines l ON l.account_id=a.id GROUP BY a.id ORDER BY a.code""").fetchall();c.close()
    assets=[x for x in rows if x["type"]=="asset"];liabs=[x for x in rows if x["type"]=="liability"];income=[x for x in rows if x["type"]=="income"];expense=[x for x in rows if x["type"]=="expense"]
    at=sum(x["debit"]-x["credit"] for x in assets);lt=sum(x["credit"]-x["debit"] for x in liabs);rev=sum(x["credit"]-x["debit"] for x in income);ex=sum(x["debit"]-x["credit"] for x in expense);profit=rev-ex
    def tr(data,normal):
        return "".join(f"<tr><td>{x['code']}</td><td>{x['name']}</td><td>{((x['debit']-x['credit']) if normal=='d' else (x['credit']-x['debit'])):.2f}</td></tr>" for x in data)
    return page(f"""<h1>القوائم المالية</h1><div class=cards><div class=card>الأصول<strong>{at:.2f}</strong></div><div class=card>الالتزامات<strong>{lt:.2f}</strong></div><div class=card>الإيرادات<strong>{rev:.2f}</strong></div><div class=card>صافي الربح<strong>{profit:.2f}</strong></div></div><h2>قائمة الدخل</h2><table><tr><th>الكود</th><th>الحساب</th><th>القيمة</th></tr>{tr(income,'c')}{tr(expense,'d')}<tr><th colspan=2>صافي الربح</th><th>{profit:.2f}</th></tr></table><h2>المركز المالي</h2><table><tr><th>الكود</th><th>الحساب</th><th>الرصيد</th></tr>{tr(assets,'d')}{tr(liabs,'c')}<tr><th colspan=2>حقوق الملكية/الأرباح المتراكمة المحسوبة</th><th>{at-lt:.2f}</th></tr></table>""")


def date_is_closed(c,date_text):
    d=(date_text or "")[:10]
    return c.execute("SELECT 1 FROM fiscal_periods WHERE status='CLOSED' AND ? BETWEEN start_date AND end_date",(d,)).fetchone() is not None

