@app.route("/asset-depreciate/<int:aid>",methods=["POST"])
def asset_depreciate(aid):
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    try:
        c.execute("BEGIN IMMEDIATE");a=c.execute("SELECT * FROM fixed_assets WHERE id=?",(aid,)).fetchone();period=request.form["period"]
        if not a:raise ValueError("الأصل غير موجود")
        if c.execute("SELECT 1 FROM asset_depreciation WHERE asset_id=? AND period=?",(aid,period)).fetchone():raise ValueError("تم احتساب إهلاك هذه الفترة")
        amount=(a["cost"]-a["salvage_value"])/a["useful_months"]
        remaining=(a["cost"]-a["salvage_value"])-a["accum_depr"];amount=min(amount,max(remaining,0))
        if amount<=0:raise ValueError("الأصل مستهلك بالكامل")
        no=number("DEP");jid=journal(c,"إهلاك "+a["name"]+" "+period,no,[(a["depr_account_id"],amount,0),(a["accum_account_id"],0,amount)])
        c.execute("INSERT INTO asset_depreciation(asset_id,period,amount,journal_id,posted_at) VALUES(?,?,?,?,?)",(aid,period,amount,jid,now()));c.execute("UPDATE fixed_assets SET accum_depr=accum_depr+? WHERE id=?",(amount,aid));c.commit();log("assets","depreciation",no);flash("تم ترحيل الإهلاك %.2f"%amount)
    except Exception as e:c.rollback();flash(str(e))
    finally:c.close()
    return redirect("/assets")


def ensure_open_period(c,date_text):
    if date_is_closed(c,date_text):
        raise ValueError("الفترة المالية مقفلة ولا يمكن ترحيل العملية")

