@app.route("/inventory-transfer",methods=["GET","POST"])
def inventory_transfer():
    if session.get("role") not in ("admin","warehouse"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            c.execute("BEGIN IMMEDIATE");fw=int(request.form["from"]);tw=int(request.form["to"]);pid=int(request.form["product"]);qty=float(request.form["qty"]);d=request.form["date"]
            ensure_open_period(c,d)
            if fw==tw or qty<=0:raise ValueError("بيانات التحويل غير صحيحة")
            st=c.execute("SELECT qty FROM stock WHERE warehouse_id=? AND product_id=?",(fw,pid)).fetchone()
            if not st or st["qty"]<qty:raise ValueError("الرصيد غير كاف")
            no=number("TRN");cur=c.execute("INSERT INTO inventory_transfers(no,from_warehouse,to_warehouse,date,user_id,notes) VALUES(?,?,?,?,?,?)",(no,fw,tw,d,session["uid"],request.form.get("notes","")));tid=cur.lastrowid
            c.execute("INSERT INTO inventory_transfer_lines(transfer_id,product_id,qty) VALUES(?,?,?)",(tid,pid,qty))
            c.execute("UPDATE stock SET qty=qty-? WHERE warehouse_id=? AND product_id=?",(qty,fw,pid))
            if c.execute("SELECT 1 FROM stock WHERE warehouse_id=? AND product_id=?",(tw,pid)).fetchone():c.execute("UPDATE stock SET qty=qty+? WHERE warehouse_id=? AND product_id=?",(qty,tw,pid))
            else:c.execute("INSERT INTO stock(warehouse_id,product_id,qty) VALUES(?,?,?)",(tw,pid,qty))
            for wid,t in [(fw,"TRANSFER-OUT"),(tw,"TRANSFER-IN")]:c.execute("INSERT INTO stock_moves(no,type,warehouse_id,product_id,qty,reference,created_at,user_id) VALUES(?,?,?,?,?,?,?,?)",(no,t,wid,pid,qty,no,now(),session["uid"]))
            c.commit();log("stock","transfer",no);flash("تم تحويل المخزون "+no)
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/inventory-transfer")
    wh=c.execute("SELECT * FROM warehouses WHERE active=1").fetchall();pr=c.execute("SELECT * FROM products ORDER BY name").fetchall();rows=c.execute("""SELECT t.*,a.name fw,b.name tw FROM inventory_transfers t JOIN warehouses a ON a.id=t.from_warehouse JOIN warehouses b ON b.id=t.to_warehouse ORDER BY t.id DESC LIMIT 100""").fetchall();c.close()
    wo="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in wh);po="".join(f"<option value='{x['id']}'>{x['code']} — {x['name']}</option>" for x in pr);r="".join(f"<tr><td>{x['date']}</td><td>{x['no']}</td><td>{x['fw']}</td><td>{x['tw']}</td><td>{x['status']}</td></tr>" for x in rows)
    return page(f"""<h1>تحويل المخزون</h1><form method=post class=panel><input type=date name=date required> من <select name=from>{wo}</select> إلى <select name=to>{wo}</select> <select name=product>{po}</select> <input name=qty type=number step=.01 min=.01 required placeholder=الكمية> <input name=notes placeholder=ملاحظات> <button>ترحيل التحويل</button></form><table><tr><th>التاريخ</th><th>الرقم</th><th>من</th><th>إلى</th><th>الحالة</th></tr>{r}</table>""")

@app.route("/stock-count",methods=["GET","POST"])
def stock_count():
    if session.get("role") not in ("admin","warehouse"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            c.execute("BEGIN IMMEDIATE");wid=int(request.form["warehouse"]);pid=int(request.form["product"]);counted=float(request.form["counted"]);d=request.form["date"];ensure_open_period(c,d)
            row=c.execute("SELECT qty FROM stock WHERE warehouse_id=? AND product_id=?",(wid,pid)).fetchone();system=row["qty"] if row else 0
            p=c.execute("SELECT * FROM products WHERE id=?",(pid,)).fetchone();diff=counted-system;no=number("ADJ")
            cur=c.execute("INSERT INTO stock_adjustments(no,warehouse_id,date,user_id,notes) VALUES(?,?,?,?,?)",(no,wid,d,session["uid"],request.form.get("notes","")));aid=cur.lastrowid
            c.execute("INSERT INTO stock_adjustment_lines(adjustment_id,product_id,system_qty,counted_qty,difference,cost) VALUES(?,?,?,?,?,?)",(aid,pid,system,counted,diff,p["cost"]))
            if row:c.execute("UPDATE stock SET qty=? WHERE warehouse_id=? AND product_id=?",(counted,wid,pid))
            else:c.execute("INSERT INTO stock(warehouse_id,product_id,qty) VALUES(?,?,?)",(wid,pid,counted))
            c.execute("INSERT INTO stock_moves(no,type,warehouse_id,product_id,qty,reference,created_at,user_id) VALUES(?,?,?,?,?,?,?,?)",(no,"ADJUSTMENT",wid,pid,diff,no,now(),session["uid"]))
            value=abs(diff*p["cost"])
            if value>0:
                if diff>0:journal(c,"زيادة جرد "+no,no,[(acc(c,"1200"),value,0),(acc(c,"5100"),0,value)])
                else:journal(c,"عجز جرد "+no,no,[(acc(c,"5100"),value,0),(acc(c,"1200"),0,value)])
            c.commit();log("stock","adjustment",no);flash("تمت تسوية الجرد "+no)
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/stock-count")
    wh=c.execute("SELECT * FROM warehouses WHERE active=1").fetchall();pr=c.execute("SELECT * FROM products ORDER BY name").fetchall();c.close()
    wo="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in wh);po="".join(f"<option value='{x['id']}'>{x['code']} — {x['name']}</option>" for x in pr)
    return page(f"""<h1>الجرد والتسويات</h1><form method=post class=panel><input type=date name=date required> <select name=warehouse>{wo}</select> <select name=product>{po}</select> <input name=counted type=number step=.01 min=0 required placeholder="الكمية الفعلية"> <input name=notes placeholder=ملاحظات> <button>اعتماد التسوية</button></form>""")

