@app.route("/eos",methods=["GET","POST"])
def eos():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            from datetime import datetime as DT
            eid=int(request.form["employee"]);term=request.form["termination_date"];contract=c.execute("SELECT * FROM employee_contracts WHERE employee_id=? ORDER BY id DESC LIMIT 1",(eid,)).fetchone()
            if not contract:raise ValueError("لا يوجد عقد للموظف")
            days=(DT.strptime(term,"%Y-%m-%d")-DT.strptime(contract["start_date"],"%Y-%m-%d")).days
            if days<0:raise ValueError("تاريخ نهاية الخدمة غير صحيح")
            monthly=contract["basic"]+contract["allowances"];years=days/365.0
            # تقدير إداري فقط: نصف راتب لأول 5 سنوات ثم راتب كامل لما بعدها.
            amount=monthly*0.5*min(years,5)+monthly*max(years-5,0)
            no=number("EOS");c.execute("INSERT INTO eos_settlements(no,employee_id,termination_date,service_days,base_salary,amount,status,notes) VALUES(?,?,?,?,?,?,'DRAFT',?)",(no,eid,term,days,monthly,amount,request.form.get("notes","")));c.commit();log("hr","eos_draft",no);flash("تم إنشاء تقدير نهاية الخدمة للمراجعة")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/eos")
    es=c.execute("SELECT * FROM employees WHERE active=1").fetchall();rows=c.execute("""SELECT x.*,e.name FROM eos_settlements x JOIN employees e ON e.id=x.employee_id ORDER BY x.id DESC""").fetchall();c.close()
    eo="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in es);r="".join(f"<tr><td>{x['no']}</td><td>{x['name']}</td><td>{x['termination_date']}</td><td>{x['service_days']}</td><td>{x['amount']:.2f}</td><td>{x['status']}</td></tr>" for x in rows)
    return page(f"""<h1>تقدير نهاية الخدمة</h1><div class=msg>القيمة هنا تقديرية للمراجعة وليست احتسابًا نظاميًا نهائيًا.</div><form method=post class=panel><select name=employee>{eo}</select> <input type=date name=termination_date required> <input name=notes placeholder=ملاحظات> <button>إنشاء تقدير</button></form><table><tr><th>الرقم</th><th>الموظف</th><th>النهاية</th><th>أيام الخدمة</th><th>التقدير</th><th>الحالة</th></tr>{r}</table>""")


