@app.route("/customer-aging-v29")
def customer_aging_v29():
    if session.get("role") not in ("admin","accountant","sales"):return ("غير مصرح",403)
    c=con();rows=c.execute("""SELECT i.*,p.name customer,CAST(julianday(date('now'))-julianday(i.due_date) AS INTEGER) overdue FROM customer_invoices_v29 i JOIN partners p ON p.id=i.customer_id WHERE i.total>i.paid ORDER BY i.due_date""").fetchall();c.close()
    b={"غير مستحق":0,"1-30":0,"31-60":0,"61-90":0,"أكثر من 90":0};rr=""
    for x in rows:
        bal=x["total"]-x["paid"];od=x["overdue"] or 0;k="غير مستحق" if od<=0 else "1-30" if od<=30 else "31-60" if od<=60 else "61-90" if od<=90 else "أكثر من 90";b[k]+=bal;rr+=f"<tr><td>{x['customer']}</td><td>{x['no']}</td><td>{x['due_date']}</td><td>{bal:.2f}</td><td>{k}</td></tr>"
    cards="".join(f"<div class=card>{k}<strong>{v:.2f}</strong></div>" for k,v in b.items())
    return page(f"<h1>أعمار ديون العملاء</h1><div class=cards>{cards}</div><p><a href='/customer-receipts-v29'>تسجيل تحصيل عميل</a></p><table><tr><th>العميل</th><th>الفاتورة</th><th>الاستحقاق</th><th>الرصيد</th><th>العمر</th></tr>{rr}</table>")

