@app.route("/sales-dashboard-v30")
def sales_dashboard_v30():
    if session.get("role") not in ("admin","accountant","sales"):return ("غير مصرح",403)
    c=con()
    sales=c.execute("SELECT coalesce(sum(subtotal),0) s,coalesce(sum(total),0) t,coalesce(sum(total-paid),0) ar FROM customer_invoices_v29").fetchone()
    overdue=c.execute("SELECT coalesce(sum(total-paid),0) x FROM customer_invoices_v29 WHERE total>paid AND due_date<date('now')").fetchone()["x"]
    customers=c.execute("""SELECT p.name,coalesce(sum(i.subtotal),0) sales,coalesce(sum(i.total-i.paid),0) balance
    FROM partners p LEFT JOIN customer_invoices_v29 i ON i.customer_id=p.id WHERE p.type='customer'
    GROUP BY p.id ORDER BY sales DESC LIMIT 10""").fetchall()
    products=c.execute("""SELECT p.name,coalesce(sum(l.delivered_qty*l.unit_price),0) revenue,
    coalesce(sum(l.delivered_qty*(l.unit_price-p.cost)),0) gross_profit
    FROM products p LEFT JOIN sales_order_lines_v29 l ON l.product_id=p.id GROUP BY p.id ORDER BY revenue DESC LIMIT 10""").fetchall()
    reps=c.execute("""SELECT s.name,s.commission_rate,coalesce(sum(i.subtotal),0) sales,
    coalesce(sum(i.subtotal),0)*s.commission_rate/100 commission
    FROM sales_reps_v30 s LEFT JOIN customer_credit_v30 cc ON cc.sales_rep_id=s.id
    LEFT JOIN customer_invoices_v29 i ON i.customer_id=cc.customer_id GROUP BY s.id ORDER BY sales DESC""").fetchall();c.close()
    cr="".join(f"<tr><td>{x['name']}</td><td>{x['sales']:.2f}</td><td>{x['balance']:.2f}</td></tr>" for x in customers)
    pr="".join(f"<tr><td>{x['name']}</td><td>{x['revenue']:.2f}</td><td>{x['gross_profit']:.2f}</td></tr>" for x in products)
    sr="".join(f"<tr><td>{x['name']}</td><td>{x['sales']:.2f}</td><td>{x['commission_rate']:.2f}%</td><td>{x['commission']:.2f}</td></tr>" for x in reps)
    return page(f"""<h1>لوحة مؤشرات المبيعات v30</h1><div class=cards><div class=card>صافي المبيعات<strong>{sales['s']:.2f}</strong></div><div class=card>إجمالي الفواتير<strong>{sales['t']:.2f}</strong></div><div class=card>ذمم العملاء<strong>{sales['ar']:.2f}</strong></div><div class=card>متأخرات<strong>{overdue:.2f}</strong></div></div>
    <h2>أفضل العملاء</h2><table><tr><th>العميل</th><th>المبيعات</th><th>الرصيد</th></tr>{cr}</table>
    <h2>ربحية الأصناف التقديرية</h2><table><tr><th>الصنف</th><th>الإيراد</th><th>الربح الإجمالي</th></tr>{pr}</table>
    <h2>المندوبون والعمولات</h2><table><tr><th>المندوب</th><th>المبيعات</th><th>نسبة العمولة</th><th>العمولة</th></tr>{sr}</table>""")


