@app.route("/sales-returns-v31",methods=["GET","POST"])
def sales_returns_v31():
    if session.get("role") not in ("admin","sales","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            c.execute("BEGIN IMMEDIATE");iid=int(request.form["invoice"]);pid=int(request.form["product"]);qty=float(request.form["qty"]);wid=int(request.form["warehouse"]);d=request.form["date"];ensure_open_period(c,d)
            inv=c.execute("SELECT * FROM customer_invoices_v29 WHERE id=?",(iid,)).fetchone()
            ln=c.execute("""SELECT l.* FROM sales_order_lines_v29 l WHERE l.order_id=? AND l.product_id=? ORDER BY l.id LIMIT 1""",(inv["order_id"],pid)).fetchone() if inv else None
            if not inv or not ln or qty<=0 or qty>ln["delivered_qty"]+.0001:raise ValueError("بيانات المرتجع غير صحيحة")
            sub=qty*ln["unit_price"];vat=sub*ln["vat_rate"]/100;total=sub+vat;no=number("SRET")
            cur=c.execute("INSERT INTO sales_returns_v31(no,invoice_id,customer_id,warehouse_id,return_date,subtotal,vat,total,user_id,notes) VALUES(?,?,?,?,?,?,?,?,?,?)",(no,iid,inv["customer_id"],wid,d,sub,vat,total,session["uid"],request.form.get("notes","")));rid=cur.lastrowid
            c.execute("INSERT INTO sales_return_lines_v31(return_id,product_id,qty,unit_price,vat_rate,subtotal,vat,total) VALUES(?,?,?,?,?,?,?,?)",(rid,pid,qty,ln["unit_price"],ln["vat_rate"],sub,vat,total))
            if c.execute("SELECT 1 FROM stock WHERE warehouse_id=? AND product_id=?",(wid,pid)).fetchone():c.execute("UPDATE stock SET qty=qty+? WHERE warehouse_id=? AND product_id=?",(qty,wid,pid))
            else:c.execute("INSERT INTO stock(warehouse_id,product_id,qty) VALUES(?,?,?)",(wid,pid,qty))
            c.execute("INSERT INTO stock_moves(no,type,warehouse_id,product_id,qty,reference,created_at,user_id) VALUES(?,?,?,?,?,?,?,?)",(no,"SALES-RETURN",wid,pid,qty,inv["no"],now(),session["uid"]))
            cn=number("CN");c.execute("INSERT INTO credit_notes_v31(no,return_id,customer_id,note_date,subtotal,vat,total,user_id) VALUES(?,?,?,?,?,?,?,?)",(cn,rid,inv["customer_id"],d,sub,vat,total,session["uid"]))
            journal(c,"إشعار دائن "+cn,cn,[(acc(c,"4100"),sub,0),(acc(c,"2200"),vat,0),(acc(c,"1100"),0,total)])
            c.commit();flash("تم المرتجع وإصدار الإشعار الدائن "+cn)
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/sales-returns-v31")
    invs=c.execute("""SELECT i.*,p.name customer FROM customer_invoices_v29 i JOIN partners p ON p.id=i.customer_id ORDER BY i.id DESC""").fetchall();products=c.execute("SELECT * FROM products ORDER BY name").fetchall();wh=c.execute("SELECT * FROM warehouses WHERE active=1").fetchall()
    rows=c.execute("""SELECT r.*,p.name customer FROM sales_returns_v31 r JOIN partners p ON p.id=r.customer_id ORDER BY r.id DESC""").fetchall();c.close()
    io="".join(f"<option value='{x['id']}'>{x['no']} — {x['customer']}</option>" for x in invs);po="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in products);wo="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in wh)
    rr="".join(f"<tr><td>{x['no']}</td><td>{x['return_date']}</td><td>{x['customer']}</td><td>{x['total']:.2f}</td></tr>" for x in rows)
    return page(f"""<h1>مرتجعات المبيعات والإشعارات الدائنة</h1><form method=post class=panel><select name=invoice>{io}</select><select name=product>{po}</select><select name=warehouse>{wo}</select><input type=date name=date required><input name=qty type=number step=.01 min=.01 required placeholder=الكمية><input name=notes placeholder=ملاحظات><button>ترحيل المرتجع</button></form><table><tr><th>المرتجع</th><th>التاريخ</th><th>العميل</th><th>القيمة</th></tr>{rr}</table>""")

@app.route("/commissions-v31",methods=["GET","POST"])
def commissions_v31():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            recs=c.execute("""SELECT r.* FROM customer_receipts_v29 r LEFT JOIN sales_commissions_v31 x ON x.receipt_id=r.id WHERE x.id IS NULL""").fetchall();n=0
            for r in recs:
                cc=c.execute("SELECT sales_rep_id FROM customer_credit_v30 WHERE customer_id=?",(r["customer_id"],)).fetchone()
                if not cc or not cc["sales_rep_id"]:continue
                rep=c.execute("SELECT commission_rate FROM sales_reps_v30 WHERE id=?",(cc["sales_rep_id"],)).fetchone()
                rate=rep["commission_rate"] if rep else 0;amt=r["amount"]*rate/100
                c.execute("INSERT INTO sales_commissions_v31(receipt_id,sales_rep_id,customer_id,receipt_amount,commission_rate,commission_amount,created_at) VALUES(?,?,?,?,?,?,?)",(r["id"],cc["sales_rep_id"],r["customer_id"],r["amount"],rate,amt,now()));n+=1
            c.commit();flash(f"تم احتساب {n} عمولة جديدة")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/commissions-v31")
    rows=c.execute("""SELECT x.*,s.name rep,p.name customer,r.no receipt FROM sales_commissions_v31 x JOIN sales_reps_v30 s ON s.id=x.sales_rep_id JOIN partners p ON p.id=x.customer_id JOIN customer_receipts_v29 r ON r.id=x.receipt_id ORDER BY x.id DESC""").fetchall();c.close()
    rr="".join(f"<tr><td>{x['rep']}</td><td>{x['customer']}</td><td>{x['receipt']}</td><td>{x['receipt_amount']:.2f}</td><td>{x['commission_rate']:.2f}%</td><td>{x['commission_amount']:.2f}</td><td>{x['status']}</td></tr>" for x in rows)
    return page(f"<h1>العمولات بعد التحصيل</h1><form method=post class=panel><button>احتساب العمولات الجديدة من التحصيلات</button></form><table><tr><th>المندوب</th><th>العميل</th><th>سند التحصيل</th><th>المحصّل</th><th>النسبة</th><th>العمولة</th><th>الحالة</th></tr>{rr}</table>")

@app.route("/rep-performance-v31")
def rep_performance_v31():
    if session.get("role") not in ("admin","accountant","sales"):return ("غير مصرح",403)
    period=request.args.get("period") or now()[:7];c=con()
    rows=c.execute("""SELECT s.id,s.name,s.commission_rate,
    coalesce((SELECT target_amount FROM sales_targets_v30 t WHERE t.sales_rep_id=s.id AND t.period=?),s.target_monthly,0) target,
    coalesce(sum(CASE WHEN substr(i.invoice_date,1,7)=? THEN i.subtotal ELSE 0 END),0) actual,
    coalesce((SELECT sum(x.commission_amount) FROM sales_commissions_v31 x WHERE x.sales_rep_id=s.id AND substr(x.created_at,1,7)=?),0) commission
    FROM sales_reps_v30 s LEFT JOIN customer_credit_v30 cc ON cc.sales_rep_id=s.id LEFT JOIN customer_invoices_v29 i ON i.customer_id=cc.customer_id
    WHERE s.active=1 GROUP BY s.id ORDER BY actual DESC""",(period,period,period)).fetchall();c.close()
    rr=""
    for x in rows:
        pct=(x["actual"]/x["target"]*100) if x["target"] else 0
        rr+=f"<tr><td>{x['name']}</td><td>{x['target']:.2f}</td><td>{x['actual']:.2f}</td><td>{pct:.1f}%</td><td>{x['commission']:.2f}</td></tr>"
    return page(f"<h1>أداء المندوبين: الهدف مقابل الفعلي</h1><form method=get class=panel><input type=month name=period value='{period}'><button>عرض</button></form><table><tr><th>المندوب</th><th>الهدف</th><th>الفعلي</th><th>الإنجاز</th><th>عمولات التحصيل</th></tr>{rr}</table>")


