def qr_png_data_uri(payload):
    """Return a printable QR code as an inline PNG data URI."""
    import base64, qrcode
    img=qrcode.make(str(payload or ""))
    buf=BytesIO(); img.save(buf, format="PNG")
    return "data:image/png;base64,"+base64.b64encode(buf.getvalue()).decode("ascii")

def zatca_qr_payload(seller, vat_no, issue_date, total, vat):
    import base64
    return base64.b64encode(b"".join([
        tlv(1,seller), tlv(2,vat_no), tlv(3,issue_date),
        tlv(4,f"{float(total or 0):.2f}"), tlv(5,f"{float(vat or 0):.2f}")
    ])).decode("ascii")

def tlv(tag,value):
    b=str(value or "").encode("utf-8")
    return bytes([tag,len(b)])+b if len(b)<256 else bytes([tag,255])+b[:255]

