@app.route("/invoice-center-v33",methods=["GET","POST"])
def invoice_center_v33():
    if session.get("role") not in ("admin","accountant","sales"):return ("غير مصرح",403)
    import base64,uuid
    c=con()
    if request.method=="POST":
        try:
            iid=int(request.form["invoice"]);inv=c.execute("SELECT * FROM customer_invoices_v29 WHERE id=?",(iid,)).fetchone()
            if not inv:raise ValueError("الفاتورة غير موجودة")
            exists=c.execute("SELECT 1 FROM customer_invoice_lines_v33 WHERE invoice_id=?",(iid,)).fetchone()
            if not exists:
                ol=c.execute("SELECT * FROM sales_order_lines_v29 WHERE order_id=?",(inv["order_id"],)).fetchall()
                ratio=inv["subtotal"]/sum((x["subtotal"] for x in ol),0) if ol and sum((x["subtotal"] for x in ol),0)>0 else 1
                for x in ol:
                    q=x["qty"]*ratio;net=q*x["unit_price"];v=net*x["vat_rate"]/100
                    c.execute("INSERT INTO customer_invoice_lines_v33(invoice_id,product_id,description,qty,unit_price,discount,net,vat_rate,vat,total) VALUES(?,?,?,?,?,?,?,?,?,?)",(iid,x["product_id"],"",q,x["unit_price"],0,net,x["vat_rate"],v,net+v))
            co=c.execute("SELECT * FROM company_settings_v33 WHERE id=1").fetchone()
            payload=base64.b64encode(b"".join([tlv(1,co["legal_name"]),tlv(2,co["vat_number"]),tlv(3,inv["invoice_date"]),tlv(4,f"{inv['total']:.2f}"),tlv(5,f"{inv['vat']:.2f}")])).decode()
            c.execute("INSERT INTO invoice_qr_v33(invoice_id,qr_payload,created_at) VALUES(?,?,?) ON CONFLICT(invoice_id) DO UPDATE SET qr_payload=excluded.qr_payload,created_at=excluded.created_at",(iid,payload,now()))
            c.execute("INSERT OR IGNORE INTO zatca_queue_v33(invoice_id,invoice_uuid,status,created_at) VALUES(?,?,?,?)",(iid,str(uuid.uuid4()),"READY",now()))
            c.commit();flash("تم تجهيز بنود الفاتورة وبيانات QR وإضافتها لطابور الجاهزية")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/invoice-center-v33")
    invs=c.execute("""SELECT i.*,p.name customer,q.status zatca FROM customer_invoices_v29 i JOIN partners p ON p.id=i.customer_id LEFT JOIN zatca_queue_v33 q ON q.invoice_id=i.id ORDER BY i.id DESC""").fetchall();c.close()
    io="".join(f"<option value='{x['id']}'>{x['no']} — {x['customer']} — {x['total']:.2f}</option>" for x in invs)
    rr="".join(f"<tr><td>{x['no']}</td><td>{x['customer']}</td><td>{x['invoice_date']}</td><td>{x['subtotal']:.2f}</td><td>{x['vat']:.2f}</td><td>{x['total']:.2f}</td><td>{x['zatca'] or 'غير مجهزة'}</td><td><a href='/print-invoice-v33/{x['id']}' target=_blank>طباعة</a></td></tr>" for x in invs)
    return page(f"<h1>مركز الفواتير الإلكترونية v33</h1><div class=msg>هذه المرحلة تجهز بيانات الفاتورة وQR داخليًا. لا ترسل الفواتير إلى منصة ZATCA.</div><form method=post class=panel><select name=invoice>{io}</select><button>تجهيز الفاتورة إلكترونيًا</button></form><table><tr><th>الفاتورة</th><th>العميل</th><th>التاريخ</th><th>قبل الضريبة</th><th>VAT</th><th>الإجمالي</th><th>الحالة</th><th></th></tr>{rr}</table>")

