@app.route("/journal-v36",methods=["GET","POST"])
def journal_v36():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            c.execute("BEGIN IMMEDIATE");d=request.form["date"];ensure_open_period(c,d)
            aids=request.form.getlist("account_id");ds=request.form.getlist("debit");cs=request.form.getlist("credit");ccs=request.form.getlist("cost_center");lines=[]
            for i,a in enumerate(aids):
                if not a:continue
                dr=float(ds[i] or 0);cr=float(cs[i] or 0)
                if dr<0 or cr<0 or (dr and cr):raise ValueError("السطر يجب أن يكون مديناً أو دائناً فقط")
                if dr or cr:lines.append((int(a),dr,cr,int(ccs[i]) if i<len(ccs) and ccs[i] else None))
            if len(lines)<2 or abs(sum(x[1] for x in lines)-sum(x[2] for x in lines))>.005:raise ValueError("القيد غير متوازن")
            no=number("JV");cur=c.execute("INSERT INTO journals(no,date,description,source) VALUES(?,?,?,?)",(no,d,request.form["description"],"MANUAL-V36"));jid=cur.lastrowid
            for aid,dr,cr,ccid in lines:
                lid=c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,aid,dr,cr)).lastrowid
                if ccid:c.execute("INSERT INTO journal_line_dimensions_v36(journal_line_id,cost_center_id) VALUES(?,?)",(lid,ccid))
            c.commit();flash("تم ترحيل القيد "+no)
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/journal-v36")
    ac=c.execute("SELECT * FROM accounts ORDER BY code").fetchall();cc=c.execute("SELECT * FROM cost_centers WHERE active=1 ORDER BY code").fetchall();c.close()
    ao="".join(f"<option value='{x['id']}'>{x['code']} — {x['name']}</option>" for x in ac);co="<option value=''>بدون مركز تكلفة</option>"+"".join(f"<option value='{x['id']}'>{x['code']} — {x['name']}</option>" for x in cc)
    return page(f"<h1>قيد يومية متعدد البنود</h1><form method=post class=panel><input type=date name=date required><input name=description required placeholder='البيان'><div id=ls></div><button type=button onclick=add()>+ سطر</button> <button>ترحيل</button></form><template id=tpl><div class=line style='grid-template-columns:2fr 1fr 1fr 2fr'><select name=account_id>{ao}</select><input name=debit type=number step=.01 min=0 value=0 placeholder=مدين><input name=credit type=number step=.01 min=0 value=0 placeholder=دائن><select name=cost_center>{co}</select></div></template><script>function add(){{ls.append(tpl.content.cloneNode(true))}}add();add();</script>")

@app.route("/trial-balance-v36")
def trial_balance_v36():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    start,end=_range36();c=con()
    rows=c.execute("""SELECT a.code,a.name,coalesce(sum(CASE WHEN j.date<? THEN l.debit-l.credit ELSE 0 END),0) op,coalesce(sum(CASE WHEN j.date BETWEEN ? AND ? THEN l.debit ELSE 0 END),0) dr,coalesce(sum(CASE WHEN j.date BETWEEN ? AND ? THEN l.credit ELSE 0 END),0) cr FROM accounts a LEFT JOIN journal_lines l ON l.account_id=a.id LEFT JOIN journals j ON j.id=l.journal_id GROUP BY a.id ORDER BY a.code""",(start,start,end,start,end)).fetchall();c.close()
    rr="";td=tc=0
    for x in rows:
        b=x["op"]+x["dr"]-x["cr"];db=max(b,0);cr=max(-b,0);td+=db;tc+=cr;rr+=f"<tr><td>{x['code']}</td><td>{x['name']}</td><td>{x['op']:.2f}</td><td>{x['dr']:.2f}</td><td>{x['cr']:.2f}</td><td>{db:.2f}</td><td>{cr:.2f}</td></tr>"
    return page(f"<h1>ميزان المراجعة</h1><form method=get class=panel><input type=date name=start value='{start}'><input type=date name=end value='{end}'><button>عرض</button></form><table><tr><th>الكود</th><th>الحساب</th><th>افتتاحي</th><th>مدين</th><th>دائن</th><th>رصيد مدين</th><th>رصيد دائن</th></tr>{rr}<tr><th colspan=5>الإجمالي</th><th>{td:.2f}</th><th>{tc:.2f}</th></tr></table>")

@app.route("/income-statement-v36")
def income_statement_v36():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    start,end=_range36();c=con()
    rows=c.execute("""SELECT a.code,a.name,a.type,coalesce(sum(CASE WHEN j.date BETWEEN ? AND ? THEN l.debit-l.credit ELSE 0 END),0) bal FROM accounts a LEFT JOIN journal_lines l ON l.account_id=a.id LEFT JOIN journals j ON j.id=l.journal_id WHERE a.type IN ('income','expense') GROUP BY a.id ORDER BY a.code""",(start,end)).fetchall();c.close()
    rev=sum(-x["bal"] for x in rows if x["type"]=="income");exp=sum(x["bal"] for x in rows if x["type"]=="expense");profit=rev-exp
    rr="".join(f"<tr><td>{x['code']}</td><td>{x['name']}</td><td>{(-x['bal'] if x['type']=='income' else x['bal']):.2f}</td></tr>" for x in rows)
    return page(f"<h1>قائمة الدخل</h1><form method=get class=panel><input type=date name=start value='{start}'><input type=date name=end value='{end}'><button>عرض</button></form><div class=cards><div class=card>الإيرادات<strong>{rev:.2f}</strong></div><div class=card>المصروفات<strong>{exp:.2f}</strong></div><div class=card>صافي الربح<strong>{profit:.2f}</strong></div></div><table><tr><th>الكود</th><th>الحساب</th><th>القيمة</th></tr>{rr}</table>")

@app.route("/balance-sheet-v36")
def balance_sheet_v36():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    end=request.args.get("end") or now()[:10];c=con()
    rows=c.execute("""SELECT a.code,a.name,a.type,coalesce(sum(CASE WHEN j.date<=? THEN l.debit-l.credit ELSE 0 END),0) bal FROM accounts a LEFT JOIN journal_lines l ON l.account_id=a.id LEFT JOIN journals j ON j.id=l.journal_id WHERE a.type IN ('asset','liability','equity') GROUP BY a.id ORDER BY a.code""",(end,)).fetchall()
    p=c.execute("""SELECT coalesce(sum(CASE WHEN a.type='income' THEN l.credit-l.debit WHEN a.type='expense' THEN l.credit-l.debit ELSE 0 END),0) x FROM journal_lines l JOIN journals j ON j.id=l.journal_id JOIN accounts a ON a.id=l.account_id WHERE j.date<=? AND a.type IN ('income','expense')""",(end,)).fetchone()["x"];c.close()
    assets=sum(x["bal"] for x in rows if x["type"]=="asset");liab=sum(-x["bal"] for x in rows if x["type"]=="liability");eq=sum(-x["bal"] for x in rows if x["type"]=="equity")+p
    rr="".join(f"<tr><td>{x['code']}</td><td>{x['name']}</td><td>{x['type']}</td><td>{(x['bal'] if x['type']=='asset' else -x['bal']):.2f}</td></tr>" for x in rows)
    return page(f"<h1>الميزانية العمومية</h1><form method=get class=panel><input type=date name=end value='{end}'><button>عرض</button></form><div class=cards><div class=card>الأصول<strong>{assets:.2f}</strong></div><div class=card>الالتزامات<strong>{liab:.2f}</strong></div><div class=card>حقوق الملكية<strong>{eq:.2f}</strong></div><div class=card>الفرق<strong>{assets-liab-eq:.2f}</strong></div></div><table><tr><th>الكود</th><th>الحساب</th><th>النوع</th><th>الرصيد</th></tr>{rr}</table>")

@app.route("/cash-flow-v36")
def cash_flow_v36():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    start,end=_range36();c=con()
    rows=c.execute("""SELECT j.no,j.date,j.description,j.source,sum(CASE WHEN a.code IN ('1010','1020') THEN l.debit-l.credit ELSE 0 END) cash FROM journals j JOIN journal_lines l ON l.journal_id=j.id JOIN accounts a ON a.id=l.account_id WHERE j.date BETWEEN ? AND ? GROUP BY j.id HAVING abs(cash)>.0001 ORDER BY j.date,j.id""",(start,end)).fetchall();c.close()
    op=oth=0;rr=""
    for x in rows:
        txt=((x["source"] or "")+" "+(x["description"] or "")).lower();cat="استثماري/تمويلي" if any(k in txt for k in ("asset","capital","loan","قرض","أصل")) else "تشغيلي"
        if cat=="تشغيلي":op+=x["cash"]
        else:oth+=x["cash"]
        rr+=f"<tr><td>{x['date']}</td><td>{x['no']}</td><td>{x['description']}</td><td>{cat}</td><td>{x['cash']:.2f}</td></tr>"
    return page(f"<h1>التدفقات النقدية</h1><div class=msg>التصنيف في v36 تحليلي مبدئي حسب مصدر ووصف القيد.</div><form method=get class=panel><input type=date name=start value='{start}'><input type=date name=end value='{end}'><button>عرض</button></form><div class=cards><div class=card>تشغيلي<strong>{op:.2f}</strong></div><div class=card>استثماري/تمويلي<strong>{oth:.2f}</strong></div><div class=card>صافي التغير<strong>{op+oth:.2f}</strong></div></div><table><tr><th>التاريخ</th><th>القيد</th><th>البيان</th><th>التصنيف</th><th>التغير</th></tr>{rr}</table>")

@app.route("/fiscal-years-v36",methods=["GET","POST"])
def fiscal_years_v36():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            action=request.form["action"]
            if action=="create":c.execute("INSERT INTO fiscal_years_v36(name,start_date,end_date,status) VALUES(?,?,?,'OPEN')",(request.form["name"],request.form["start"],request.form["end"]))
            elif action=="close":
                if session.get("role")!="admin":raise ValueError("إقفال السنة للمدير فقط")
                fy=c.execute("SELECT * FROM fiscal_years_v36 WHERE id=?",(int(request.form["id"]),)).fetchone()
                if not fy or fy["status"]!="OPEN":raise ValueError("السنة غير متاحة")
                if c.execute("SELECT count(*) n FROM fiscal_periods WHERE status='OPEN' AND start_date<=? AND end_date>=?",(fy["end_date"],fy["start_date"])).fetchone()["n"]:raise ValueError("أقفل الفترات المالية المتداخلة أولاً")
                vals=c.execute("""SELECT a.id,coalesce(sum(CASE WHEN j.date BETWEEN ? AND ? THEN l.debit-l.credit ELSE 0 END),0) bal FROM accounts a LEFT JOIN journal_lines l ON l.account_id=a.id LEFT JOIN journals j ON j.id=l.journal_id WHERE a.type IN ('income','expense') GROUP BY a.id""",(fy["start_date"],fy["end_date"])).fetchall()
                lines=[]
                for x in vals:
                    if x["bal"]>.005:lines.append((x["id"],0,x["bal"]))
                    elif x["bal"]<-.005:lines.append((x["id"],-x["bal"],0))
                net=sum(x[2]-x[1] for x in lines);re=acc(c,"3100")
                if net>0:lines.append((re,net,0))
                elif net<0:lines.append((re,0,-net))
                jid=None
                if lines:
                    no=number("CLOSE");jid=c.execute("INSERT INTO journals(no,date,description,source) VALUES(?,?,?,?)",(no,fy["end_date"],"إقفال السنة "+fy["name"],"YEAR-CLOSE-V36")).lastrowid
                    for aid,dr,cr in lines:c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,aid,dr,cr))
                c.execute("UPDATE fiscal_years_v36 SET status='CLOSED',closing_journal_id=?,closed_at=?,closed_by=? WHERE id=?",(jid,now(),session["uid"],fy["id"]))
                c.execute("INSERT INTO year_close_log_v36(fiscal_year_id,action,journal_id,user_id,created_at,notes) VALUES(?,?,?,?,?,?)",(fy["id"],"CLOSE",jid,session["uid"],now(),"ترحيل النتيجة إلى الأرباح المبقاة"))
            c.commit();flash("تم تحديث السنة المالية")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/fiscal-years-v36")
    rows=c.execute("SELECT * FROM fiscal_years_v36 ORDER BY start_date DESC").fetchall();c.close();rr=""
    for x in rows:
        action="" if x["status"]=="CLOSED" else "<form method=post><input type=hidden name=id value='%s'><button name=action value=close>إقفال السنة</button></form>"%x["id"]
        rr+=f"<tr><td>{x['name']}</td><td>{x['start_date']}</td><td>{x['end_date']}</td><td>{x['status']}</td><td>{x['closing_journal_id'] or '-'}</td><td>{action}</td></tr>"
    return page(f"<h1>السنوات المالية وإقفال السنة</h1><div class=msg>يتم إقفال الإيرادات والمصروفات إلى حساب الأرباح المبقاة 3100 بعد إقفال الفترات.</div><form method=post class=panel><input type=hidden name=action value=create><input name=name required placeholder='السنة'><input type=date name=start required><input type=date name=end required><button>إنشاء سنة</button></form><table><tr><th>السنة</th><th>من</th><th>إلى</th><th>الحالة</th><th>قيد الإقفال</th><th></th></tr>{rr}</table>")


