@app.route("/bank-reconcile-v37",methods=["GET","POST"])
def bank_reconcile_v37():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            action=request.form["action"]
            if action=="statement":
                c.execute("INSERT INTO bank_statement_lines_v37(bank_account_id,line_date,reference,description,amount) VALUES(?,?,?,?,?)",(int(request.form["bank"]),request.form["date"],request.form.get("reference",""),request.form.get("description",""),float(request.form["amount"])))
            else:
                sid=int(request.form["statement"]);tid=int(request.form["tx"])
                st=c.execute("SELECT * FROM bank_statement_lines_v37 WHERE id=?",(sid,)).fetchone();tx=c.execute("SELECT * FROM treasury_transactions_v37 WHERE id=?",(tid,)).fetchone()
                if not st or not tx or st["bank_account_id"]!=tx["bank_account_id"]:raise ValueError("الحركة البنكية والسند غير متطابقين")
                signed=tx["amount"] if tx["tx_type"]=="RECEIPT" else -tx["amount"]
                if abs(st["amount"]-signed)>.01:raise ValueError("المبالغ غير متطابقة")
                c.execute("UPDATE bank_statement_lines_v37 SET matched_tx_id=?,status='MATCHED' WHERE id=?",(tid,sid))
            c.commit();flash("تم تحديث التسوية")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/bank-reconcile-v37")
    banks=c.execute("SELECT * FROM bank_accounts_v37 WHERE active=1 ORDER BY name").fetchall()
    sts=c.execute("""SELECT s.*,b.name bank FROM bank_statement_lines_v37 s JOIN bank_accounts_v37 b ON b.id=s.bank_account_id ORDER BY s.id DESC""").fetchall()
    tx=c.execute("""SELECT t.*,b.name bank FROM treasury_transactions_v37 t JOIN bank_accounts_v37 b ON b.id=t.bank_account_id ORDER BY t.id DESC LIMIT 200""").fetchall();c.close()
    bo="".join(f"<option value='{x['id']}'>{x['name']}</option>" for x in banks);so="".join(f"<option value='{x['id']}'>{x['line_date']} — {x['bank']} — {x['amount']:.2f}</option>" for x in sts if x["status"]=="UNMATCHED");to="".join(f"<option value='{x['id']}'>{x['no']} — {x['bank']} — {x['amount']:.2f} — {x['tx_type']}</option>" for x in tx)
    rr="".join(f"<tr><td>{x['line_date']}</td><td>{x['bank']}</td><td>{x['reference']}</td><td>{x['description']}</td><td>{x['amount']:.2f}</td><td>{x['status']}</td></tr>" for x in sts)
    return page(f"""<h1>التسوية البنكية</h1><h2>إضافة سطر كشف بنك</h2><form method=post class=panel><input type=hidden name=action value=statement><select name=bank>{bo}</select><input type=date name=date required><input name=reference placeholder=المرجع><input name=description placeholder=البيان><input name=amount type=number step=.01 required placeholder="موجب للإيداع / سالب للسحب"><button>إضافة</button></form>
    <h2>مطابقة مع سند</h2><form method=post class=panel><input type=hidden name=action value=match><select name=statement>{so}</select><select name=tx>{to}</select><button>مطابقة</button></form><table><tr><th>التاريخ</th><th>البنك</th><th>المرجع</th><th>البيان</th><th>المبلغ</th><th>الحالة</th></tr>{rr}</table>""")

