@app.route("/accruals-v37",methods=["GET","POST"])
def accruals_v37():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            action=request.form["action"]
            if action=="new":
                c.execute("INSERT INTO accruals_v37(no,kind,description,start_date,end_date,total_amount,expense_income_account_id,prepaid_accrued_account_id) VALUES(?,?,?,?,?,?,?,?)",(number("ACR"),request.form["kind"],request.form["description"],request.form["start"],request.form["end"],float(request.form["amount"]),int(request.form["main_account"]),int(request.form["balance_account"])))
            else:
                aid=int(request.form["id"]);a=c.execute("SELECT * FROM accruals_v37 WHERE id=?",(aid,)).fetchone();amt=float(request.form["amount"]);d=request.form["date"];ensure_open_period(c,d)
                remaining=a["total_amount"]-a["recognized_amount"]
                if amt<=0 or amt>remaining+.005:raise ValueError("مبلغ الاعتراف غير صحيح")
                if a["kind"]=="PREPAID_EXPENSE":lines=[(a["expense_income_account_id"],amt,0),(a["prepaid_accrued_account_id"],0,amt)]
                elif a["kind"]=="ACCRUED_EXPENSE":lines=[(a["expense_income_account_id"],amt,0),(a["prepaid_accrued_account_id"],0,amt)]
                elif a["kind"]=="DEFERRED_REVENUE":lines=[(a["prepaid_accrued_account_id"],amt,0),(a["expense_income_account_id"],0,amt)]
                else:lines=[(a["prepaid_accrued_account_id"],amt,0),(a["expense_income_account_id"],0,amt)]
                jid=c.execute("INSERT INTO journals(no,date,description,source) VALUES(?,?,?,?)",(number("JV"),d,"اعتراف دوري "+a["no"],"ACCRUAL-V37")).lastrowid
                for account,dr,cr in lines:c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,account,dr,cr))
                new=a["recognized_amount"]+amt;c.execute("UPDATE accruals_v37 SET recognized_amount=?,status=? WHERE id=?",(new,"CLOSED" if new>=a["total_amount"]-.005 else "OPEN",aid))
            c.commit();flash("تم تحديث المستحق/المقدم")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/accruals-v37")
    ac=c.execute("SELECT * FROM accounts ORDER BY code").fetchall();rows=c.execute("SELECT * FROM accruals_v37 ORDER BY id DESC").fetchall();c.close()
    ao="".join(f"<option value='{x['id']}'>{x['code']} — {x['name']}</option>" for x in ac)
    rr="".join(f"<tr><td>{x['no']}</td><td>{x['kind']}</td><td>{x['description']}</td><td>{x['total_amount']:.2f}</td><td>{x['recognized_amount']:.2f}</td><td>{x['status']}</td><td><form method=post><input type=hidden name=id value='{x['id']}'><input type=date name=date required><input name=amount type=number step=.01 min=.01 required placeholder='مبلغ الاعتراف'><button name=action value=recognize>ترحيل</button></form></td></tr>" for x in rows)
    return page(f"""<h1>المصروفات والإيرادات المستحقة والمقدمة</h1><form method=post class=panel><input type=hidden name=action value=new><select name=kind><option value=PREPAID_EXPENSE>مصروف مقدم</option><option value=ACCRUED_EXPENSE>مصروف مستحق</option><option value=DEFERRED_REVENUE>إيراد مقدم</option><option value=ACCRUED_REVENUE>إيراد مستحق</option></select><input name=description required placeholder=الوصف><input type=date name=start required><input type=date name=end required><input name=amount type=number step=.01 min=.01 required placeholder=الإجمالي><select name=main_account>{ao}</select><select name=balance_account>{ao}</select><button>إضافة</button></form>
    <table><tr><th>الرقم</th><th>النوع</th><th>الوصف</th><th>الإجمالي</th><th>المعترف</th><th>الحالة</th><th>اعتراف دوري</th></tr>{rr}</table>""")


@app.route("/treasury-dashboard-v38")
def treasury_dashboard_v38():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    banks=c.execute("""SELECT b.id,b.code,b.name,b.currency,a.code gl_code,
    coalesce(sum(l.debit-l.credit),0) balance_sar FROM bank_accounts_v37 b
    LEFT JOIN accounts a ON a.id=b.gl_account_id LEFT JOIN journal_lines l ON l.account_id=b.gl_account_id
    GROUP BY b.id ORDER BY b.name""").fetchall()
    open_adv=c.execute("SELECT coalesce(sum(amount-settled),0) x FROM advances_v38 WHERE status='OPEN'").fetchone()["x"]
    checks=c.execute("SELECT coalesce(sum(amount),0) x FROM checks_v37 WHERE status='ISSUED'").fetchone()["x"]
    forecast=c.execute("SELECT coalesce(sum(CASE WHEN kind='INFLOW' THEN amount*probability/100 ELSE -amount*probability/100 END),0) x FROM cash_forecast_v38 WHERE status='OPEN'").fetchone()["x"]
    c.close()
    total=sum(x["balance_sar"] for x in banks)
    rr="".join(f"<tr><td>{x['code']}</td><td>{x['name']}</td><td>{x['currency']}</td><td>{x['gl_code'] or ''}</td><td>{x['balance_sar']:.2f}</td></tr>" for x in banks)
    return page(f"<h1>لوحة الخزينة التنفيذية v38</h1><div class=cards><div class=card>أرصدة البنوك SAR<strong>{total:.2f}</strong></div><div class=card>عهد غير مسواة<strong>{open_adv:.2f}</strong></div><div class=card>شيكات قائمة<strong>{checks:.2f}</strong></div><div class=card>صافي التدفق المتوقع<strong>{forecast:.2f}</strong></div></div><table><tr><th>الكود</th><th>الحساب البنكي</th><th>العملة</th><th>GL</th><th>الرصيد SAR</th></tr>{rr}</table>")

@app.route("/bank-transfer-v38",methods=["GET","POST"])
def bank_transfer_v38():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            c.execute("BEGIN IMMEDIATE");fb=int(request.form["from_bank"]);tb=int(request.form["to_bank"])
            if fb==tb:raise ValueError("اختر حسابين مختلفين")
            f=c.execute("SELECT * FROM bank_accounts_v37 WHERE id=?",(fb,)).fetchone();t=c.execute("SELECT * FROM bank_accounts_v37 WHERE id=?",(tb,)).fetchone()
            d=request.form["date"];ensure_open_period(c,d);amt=float(request.form["amount"]);rate=float(request.form["rate"]);sar=amt*rate;fees=float(request.form.get("fees") or 0)
            jid=c.execute("INSERT INTO journals(no,date,description,source) VALUES(?,?,?,?)",(number("JV"),d,request.form.get("description","تحويل بنكي"),"BANK-TRANSFER-V38")).lastrowid
            c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,t["gl_account_id"],sar,0))
            c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,f["gl_account_id"],0,sar+fees))
            if fees:c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"5400"),fees,0))
            no=number("BT");c.execute("INSERT INTO bank_transfers_v38(no,tx_date,from_bank_id,to_bank_id,amount,currency,rate,amount_sar,fees,journal_id,description) VALUES(?,?,?,?,?,?,?,?,?,?,?)",(no,d,fb,tb,amt,request.form["currency"],rate,sar,fees,jid,request.form.get("description","")))
            c.commit();flash("تم التحويل "+no)
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/bank-transfer-v38")
    banks=c.execute("SELECT * FROM bank_accounts_v37 WHERE active=1 ORDER BY name").fetchall();cur=c.execute("SELECT * FROM currencies_v37 WHERE active=1 ORDER BY code").fetchall()
    rows=c.execute("""SELECT x.*,f.name fb,t.name tb FROM bank_transfers_v38 x JOIN bank_accounts_v37 f ON f.id=x.from_bank_id JOIN bank_accounts_v37 t ON t.id=x.to_bank_id ORDER BY x.id DESC""").fetchall();c.close()
    bo="".join(f"<option value='{x['id']}'>{x['code']} — {x['name']}</option>" for x in banks);cu="".join(f"<option value='{x['code']}'>{x['code']}</option>" for x in cur)
    rr="".join(f"<tr><td>{x['no']}</td><td>{x['tx_date']}</td><td>{x['fb']}</td><td>{x['tb']}</td><td>{x['amount']:.2f} {x['currency']}</td><td>{x['fees']:.2f}</td></tr>" for x in rows)
    return page(f"<h1>التحويلات بين البنوك</h1><form method=post class=panel><select name=from_bank>{bo}</select><select name=to_bank>{bo}</select><input type=date name=date required><input name=amount type=number step=.01 min=.01 required placeholder=المبلغ><select name=currency>{cu}</select><input name=rate type=number step=.000001 min=.000001 value=1 required><input name=fees type=number step=.01 min=0 value=0 placeholder=الرسوم><input name=description placeholder=البيان><button>ترحيل</button></form><table><tr><th>الرقم</th><th>التاريخ</th><th>من</th><th>إلى</th><th>المبلغ</th><th>الرسوم</th></tr>{rr}</table>")

