                jid=c.execute("INSERT INTO journals(no,date,description,source) VALUES(?,?,?,?)",(number("JV"),d,"صرف عهدة "+request.form["employee"],"ADVANCE-V38")).lastrowid
                aa=acc(c,"1060");c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,aa,amt,0));c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,bank["gl_account_id"],0,amt))
                c.execute("INSERT INTO advances_v38(no,advance_date,employee,amount,advance_account_id,cash_bank_account_id,journal_id,notes) VALUES(?,?,?,?,?,?,?,?)",(number("ADV"),d,request.form["employee"],amt,aa,bank["id"],jid,request.form.get("notes","")))
