                d=datetime.date.fromisoformat(request.form["date"]);h=datetime.date.fromisoformat(e["hire_date"]);years=max((d-h).days/365.25,0);basis=e["basic_salary"];eos=min(years,5)*basis/2+max(years-5,0)*basis
                last=float(request.form.get("last_salary") or 0);leave=float(request.form.get("leave_comp") or 0);ded=float(request.form.get("deductions") or 0);total=last+leave+eos-ded
