    times=c.execute("""SELECT t.*,p.project_no,e.name employee FROM project_timesheets_v43 t JOIN projects_v43 p ON p.id=t.project_id JOIN employees_v41 e ON e.id=t.employee_id ORDER BY t.work_date DESC,t.id DESC LIMIT 100""").fetchall();c.close()
