@app.route("/project-profitability-v43")
def project_profitability_v43():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con();rows=c.execute("""SELECT p.*,
    coalesce((SELECT sum(amount) FROM project_billing_v43 b WHERE b.project_id=p.id),0) revenue,
    coalesce((SELECT sum(total_cost) FROM project_timesheets_v43 t WHERE t.project_id=p.id),0) labor,
    coalesce((SELECT sum(amount) FROM project_expenses_v43 e WHERE e.project_id=p.id),0) expenses
    FROM projects_v43 p ORDER BY p.project_no""").fetchall();c.close()
    rr=""
    for x in rows:
        cost=x["labor"]+x["expenses"];profit=x["revenue"]-cost;variance=x["budget_cost"]-cost;margin=(profit/x["revenue"]*100) if x["revenue"] else 0
        rr+=f"<tr><td>{x['project_no']}</td><td>{x['name']}</td><td>{x['contract_value']:.2f}</td><td>{x['budget_cost']:.2f}</td><td>{x['revenue']:.2f}</td><td>{x['labor']:.2f}</td><td>{x['expenses']:.2f}</td><td>{cost:.2f}</td><td>{variance:.2f}</td><td>{profit:.2f}</td><td>{margin:.1f}%</td></tr>"
    return page(f"<h1>ربحية وميزانية المشاريع</h1><table><tr><th>الرقم</th><th>المشروع</th><th>قيمة العقد</th><th>ميزانية التكلفة</th><th>الإيراد المفوتر</th><th>العمالة</th><th>المصروفات</th><th>التكلفة الفعلية</th><th>متبقي الميزانية</th><th>الربح</th><th>الهامش</th></tr>{rr}</table>")


