@app.route("/project-certificates-v44",methods=["GET","POST"])
def project_certificates_v44():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="new":
                pid=int(request.form["project"]);gross=float(request.form["gross"]);ct=c.execute("SELECT * FROM project_contracts_v44 WHERE project_id=? AND status='ACTIVE' ORDER BY id DESC LIMIT 1",(pid,)).fetchone()
                taxrate=ct["tax_rate"] if ct else 15; retrate=ct["retention_rate"] if ct else 0
                tax=gross*taxrate/100;ret=gross*retrate/100;recover=float(request.form.get("advance_recovery") or 0);net=gross+tax-ret-recover
                c.execute("INSERT INTO project_certificates_v44(project_id,certificate_no,certificate_date,gross_amount,tax_amount,retention_amount,advance_recovery,net_due) VALUES(?,?,?,?,?,?,?,?)",(pid,request.form["no"],request.form["date"],gross,tax,ret,recover,net))
            else:
                x=c.execute("SELECT * FROM project_certificates_v44 WHERE id=?",(int(request.form["id"]),)).fetchone()
                if not x or x["status"]!="DRAFT":raise ValueError("المستخلص غير متاح")
                ensure_open_period(c,x["certificate_date"]);jid=c.execute("INSERT INTO journals(no,date,description,source) VALUES(?,?,?,?)",(number("JV"),x["certificate_date"],"مستخلص مشروع "+x["certificate_no"],"PROJECT-CERT-V44")).lastrowid
                # Debit customer net + retention + advance recovery; Credit revenue + VAT. Advance recovery debits customer advance liability.
                c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"1200"),x["net_due"],0))
                if x["retention_amount"]>0:c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"1210"),x["retention_amount"],0))
                if x["advance_recovery"]>0:c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"2200"),x["advance_recovery"],0))
                c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"4100"),0,x["gross_amount"]))
                if x["tax_amount"]>0:c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"2210"),0,x["tax_amount"]))
                c.execute("UPDATE project_certificates_v44 SET status='POSTED',journal_id=? WHERE id=?",(jid,x["id"]))
            c.commit();flash("تم تحديث المستخلص")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/project-certificates-v44")
    ps=c.execute("SELECT * FROM projects_v43 WHERE status='ACTIVE' ORDER BY project_no").fetchall();rows=c.execute("""SELECT x.*,p.project_no FROM project_certificates_v44 x JOIN projects_v43 p ON p.id=x.project_id ORDER BY x.id DESC""").fetchall();c.close()
    po="".join(f"<option value='{x['id']}'>{x['project_no']} — {x['name']}</option>" for x in ps);rr=""
    for x in rows:
        btn="" if x["status"]!="DRAFT" else f"<form method=post><input type=hidden name=action value=post><input type=hidden name=id value='{x['id']}'><button>ترحيل</button></form>"
        rr+=f"<tr><td>{x['certificate_no']}</td><td>{x['project_no']}</td><td>{x['gross_amount']:.2f}</td><td>{x['tax_amount']:.2f}</td><td>{x['retention_amount']:.2f}</td><td>{x['advance_recovery']:.2f}</td><td>{x['net_due']:.2f}</td><td>{x['status']}</td><td>{btn}</td></tr>"
    return page(f"<h1>مستخلصات المشاريع</h1><form method=post class=panel><input type=hidden name=action value=new><select name=project>{po}</select><input name=no required placeholder='رقم المستخلص'><input type=date name=date required><input name=gross type=number step=.01 min=.01 required placeholder='قيمة الأعمال قبل الضريبة'><input name=advance_recovery type=number step=.01 min=0 value=0 placeholder='استرداد دفعة مقدمة'><button>إنشاء المستخلص</button></form><table><tr><th>المستخلص</th><th>المشروع</th><th>الأعمال</th><th>VAT</th><th>احتجاز</th><th>استرداد مقدم</th><th>الصافي</th><th>الحالة</th><th></th></tr>{rr}</table>")

