@app.route("/project-recognition-v44",methods=["GET","POST"])
def project_recognition_v44():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            pid=int(request.form["project"]);period=request.form["period"]+"-01";pct=float(request.form["pct"]);p=c.execute("SELECT * FROM projects_v43 WHERE id=?",(pid,)).fetchone()
            changes=c.execute("SELECT coalesce(sum(amount),0) a FROM project_change_orders_v44 WHERE project_id=? AND status='APPROVED'",(pid,)).fetchone()["a"];total_contract=p["contract_value"]+changes;target=total_contract*pct/100
            prev=c.execute("SELECT coalesce(sum(recognized_revenue),0) a FROM project_revenue_recognition_v44 WHERE project_id=?",(pid,)).fetchone()["a"];rev=max(target-prev,0)
            cost=c.execute("SELECT coalesce(sum(total_cost),0) a FROM project_timesheets_v43 WHERE project_id=?",(pid,)).fetchone()["a"]+c.execute("SELECT coalesce(sum(amount),0) a FROM project_expenses_v43 WHERE project_id=?",(pid,)).fetchone()["a"]
            jid=None
            if rev>.005:
                jid=c.execute("INSERT INTO journals(no,date,description,source) VALUES(?,?,?,?)",(number("JV"),period,"اعتراف إيراد مشروع "+p["project_no"],"POC-V44")).lastrowid
                c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"1220"),rev,0));c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"4100"),0,rev))
            c.execute("INSERT INTO project_revenue_recognition_v44(project_id,period_date,completion_pct,recognized_revenue,recognized_cost,journal_id) VALUES(?,?,?,?,?,?)",(pid,period,pct,rev,cost,jid));c.commit();flash("تم تسجيل نسبة الإنجاز والاعتراف")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/project-recognition-v44")
    ps=c.execute("SELECT * FROM projects_v43 WHERE status='ACTIVE' ORDER BY project_no").fetchall();rows=c.execute("""SELECT r.*,p.project_no FROM project_revenue_recognition_v44 r JOIN projects_v43 p ON p.id=r.project_id ORDER BY r.period_date DESC""").fetchall();c.close()
    po="".join(f"<option value='{x['id']}'>{x['project_no']} — {x['name']}</option>" for x in ps);rr="".join(f"<tr><td>{x['period_date'][:7]}</td><td>{x['project_no']}</td><td>{x['completion_pct']:.2f}%</td><td>{x['recognized_revenue']:.2f}</td><td>{x['recognized_cost']:.2f}</td><td>{x['journal_id'] or '-'}</td></tr>" for x in rows)
    return page(f"<h1>نسبة الإنجاز والاعتراف بالإيراد</h1><div class=msg>هذه آلية تشغيلية مبسطة. سياسة الاعتراف بالإيراد يجب ضبطها ومراجعتها محاسبياً قبل الاستخدام الإنتاجي.</div><form method=post class=panel><select name=project>{po}</select><input type=month name=period required><input name=pct type=number step=.01 min=0 max=100 required placeholder='% الإنجاز التراكمي'><button>احتساب وترحيل</button></form><table><tr><th>الفترة</th><th>المشروع</th><th>الإنجاز</th><th>إيراد الفترة</th><th>التكلفة المسجلة</th><th>القيد</th></tr>{rr}</table>")


