    fr="".join(f"<tr><td>{x['owner'] or '-'}</td><td>{x['forecast']:.2f}</td><td>{x['won']:.2f}</td></tr>" for x in forecast)
    cr="".join(f"<tr><td>{x['tx_date']}</td><td>{x['owner']}</td><td>{x['reference']}</td><td>{x['sales_amount']:.2f}</td><td>{x['rate']:.2f}%</td><td>{x['commission_amount']:.2f}</td></tr>" for x in comm)
    return page(f"""<h1>أهداف وتوقعات وعمولات المبيعات</h1><h2>هدف مبيعات</h2><form method=post class=panel><input type=hidden name=action value=target><input name=owner required placeholder="مندوب المبيعات"><input type=month name=period required><input name=target type=number step=.01 min=0 required placeholder="الهدف"><button>حفظ الهدف</button></form>
    <h2>عمولة</h2><form method=post class=panel><input type=hidden name=action value=commission><input name=owner required placeholder="المندوب"><input name=reference required placeholder="مرجع البيع"><input type=date name=date required><input name=sales type=number step=.01 min=0 required placeholder="قيمة البيع"><input name=rate type=number step=.01 min=0 value=0 required placeholder="% العمولة"><button>احتساب العمولة</button></form>
    <h2>التوقعات</h2><table><tr><th>المندوب</th><th>التوقع المرجح</th><th>الفرص الرابحة</th></tr>{fr}</table><h2>الأهداف</h2><table><tr><th>المندوب</th><th>الفترة</th><th>الهدف</th></tr>{tr}</table><h2>العمولات</h2><table><tr><th>التاريخ</th><th>المندوب</th><th>المرجع</th><th>المبيعات</th><th>النسبة</th><th>العمولة</th></tr>{cr}</table>""")


