@app.route("/support-v46",methods=["GET","POST"])
def support_v46():
    if session.get("role") not in ("admin","accountant"): return ("غير مصرح",403)
    import datetime
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="new":
                c.execute("""INSERT INTO support_tickets_v46(ticket_no,customer,contract_id,subject,description,priority,category,opened_at,assigned_to,status)
                VALUES(?,?,?,?,?,?,?,?,?,'OPEN')""",(request.form["ticket_no"],request.form["customer"],int(request.form["contract"]) if request.form.get("contract") else None,request.form["subject"],request.form.get("description",""),request.form["priority"],request.form.get("category",""),request.form["opened"],request.form.get("assigned","")))
            elif a=="activity":
                hours=float(request.form.get("hours") or 0);rate=float(request.form.get("rate") or 0)
                c.execute("INSERT INTO ticket_activities_v46(ticket_id,activity_date,activity_type,technician,hours,hourly_cost,cost,notes) VALUES(?,?,?,?,?,?,?,?)",(int(request.form["ticket"]),request.form["date"],request.form["type"],request.form.get("technician",""),hours,rate,hours*rate,request.form.get("notes","")))
                c.execute("UPDATE support_tickets_v46 SET first_response_at=coalesce(first_response_at,?) WHERE id=?",(request.form["date"],int(request.form["ticket"])))
            elif a=="resolve":
                tid=int(request.form["id"]);t=c.execute("SELECT * FROM support_tickets_v46 WHERE id=?",(tid,)).fetchone()
                resolved=request.form["date"];c.execute("UPDATE support_tickets_v46 SET status='RESOLVED',resolved_at=?,resolution=? WHERE id=?",(resolved,request.form["resolution"],tid))
                if t["contract_id"]:
                    ct=c.execute("SELECT * FROM support_contracts_v46 WHERE id=?",(t["contract_id"],)).fetchone()
                    if ct:
                        try:
                            op=datetime.datetime.fromisoformat(t["opened_at"]);rs=datetime.datetime.fromisoformat(resolved)
                            actual=max((rs-op).total_seconds()/3600,0)
                            c.execute("INSERT INTO support_sla_events_v46(ticket_id,metric,target_hours,actual_hours,breached,event_date) VALUES(?,?,?,?,?,?)",(tid,"RESOLUTION",ct["sla_resolution_hours"],actual,1 if actual>ct["sla_resolution_hours"] else 0,resolved[:10]))
                        except: pass
            else:
                c.execute("UPDATE support_tickets_v46 SET status='CLOSED',closed_at=?,rating=?,rating_notes=? WHERE id=?",(request.form["date"],float(request.form["rating"]),request.form.get("notes",""),int(request.form["id"])))
            c.commit();flash("تم تحديث تذكرة الدعم")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/support-v46")
    contracts=c.execute("SELECT * FROM support_contracts_v46 WHERE status='ACTIVE' ORDER BY contract_no").fetchall()
    tickets=c.execute("SELECT * FROM support_tickets_v46 ORDER BY id DESC").fetchall();c.close()
    co="<option value=''>بدون عقد</option>"+"".join(f"<option value='{x['id']}'>{x['contract_no']} — {x['customer']}</option>" for x in contracts)
    to="".join(f"<option value='{x['id']}'>{x['ticket_no']} — {x['subject']}</option>" for x in tickets if x["status"] in ("OPEN","IN_PROGRESS"))
    rr=""
    for x in tickets:
        act=""
        if x["status"]=="OPEN":
            act=f"<form method=post><input type=hidden name=action value=resolve><input type=hidden name=id value='{x['id']}'><input type=datetime-local name=date required><input name=resolution required placeholder='الحل'><button>حل</button></form>"
        elif x["status"]=="RESOLVED":
            act=f"<form method=post><input type=hidden name=action value=close><input type=hidden name=id value='{x['id']}'><input type=date name=date required><input name=rating type=number min=1 max=5 step=.5 required placeholder='التقييم 1-5'><input name=notes placeholder='رأي العميل'><button>إغلاق</button></form>"
        rr+=f"<tr><td>{x['ticket_no']}</td><td>{x['customer']}</td><td>{x['subject']}</td><td>{x['priority']}</td><td>{x['assigned_to']}</td><td>{x['status']}</td><td>{x['rating'] or '-'}</td><td>{act}</td></tr>"
    return page(f"""<h1>تذاكر الدعم الفني v46</h1><h2>تذكرة جديدة</h2>
    <form method=post class=panel><input type=hidden name=action value=new><input name=ticket_no required placeholder="رقم التذكرة"><input name=customer required placeholder=العميل><select name=contract>{co}</select><input name=subject required placeholder=الموضوع><input name=description placeholder=الوصف><select name=priority><option>LOW</option><option selected>MEDIUM</option><option>HIGH</option><option>CRITICAL</option></select><input name=category placeholder=التصنيف><input type=datetime-local name=opened required><input name=assigned placeholder="الفني المسؤول"><button>فتح التذكرة</button></form>
    <h2>نشاط فني</h2><form method=post class=panel><input type=hidden name=action value=activity><select name=ticket>{to}</select><input type=datetime-local name=date required><select name=type><option>اتصال</option><option>دعم عن بعد</option><option>تشخيص</option><option>إصلاح</option></select><input name=technician placeholder=الفني><input name=hours type=number step=.25 min=0 value=0 placeholder=الساعات><input name=rate type=number step=.01 min=0 value=0 placeholder="تكلفة الساعة"><input name=notes placeholder=ملاحظات><button>تسجيل النشاط</button></form>
    <table><tr><th>التذكرة</th><th>العميل</th><th>الموضوع</th><th>الأولوية</th><th>الفني</th><th>الحالة</th><th>التقييم</th><th>الإجراء</th></tr>{rr}</table>""")

