@app.route("/support-reports-v46")
def support_reports_v46():
    if session.get("role") not in ("admin","accountant"): return ("غير مصرح",403)
    c=con()
    rows=c.execute("""SELECT t.id,t.ticket_no,t.customer,t.subject,t.priority,t.assigned_to,t.status,t.rating,
    coalesce((SELECT sum(cost) FROM ticket_activities_v46 a WHERE a.ticket_id=t.id),0) labor,
    coalesce((SELECT sum(travel_cost+service_cost) FROM field_visits_v46 v WHERE v.ticket_id=t.id),0) fieldcost,
    coalesce((SELECT sum(total_cost) FROM ticket_parts_v46 p WHERE p.ticket_id=t.id),0) parts,
    coalesce((SELECT max(breached) FROM support_sla_events_v46 s WHERE s.ticket_id=t.id),0) breached
    FROM support_tickets_v46 t ORDER BY t.id DESC""").fetchall()
    tech=c.execute("""SELECT assigned_to,count(*) tickets,
    sum(CASE WHEN status='CLOSED' THEN 1 ELSE 0 END) closed,
    avg(CASE WHEN rating>0 THEN rating END) rating
    FROM support_tickets_v46 GROUP BY assigned_to ORDER BY tickets DESC""").fetchall();c.close()
    rr=""
    for x in rows:
        total=x["labor"]+x["fieldcost"]+x["parts"]
        rr+=f"<tr><td>{x['ticket_no']}</td><td>{x['customer']}</td><td>{x['priority']}</td><td>{x['assigned_to']}</td><td>{x['status']}</td><td>{x['labor']:.2f}</td><td>{x['fieldcost']:.2f}</td><td>{x['parts']:.2f}</td><td>{total:.2f}</td><td>{'نعم' if x['breached'] else 'لا'}</td><td>{x['rating'] or '-'}</td></tr>"
    tr="".join(f"<tr><td>{x['assigned_to'] or 'غير معين'}</td><td>{x['tickets']}</td><td>{x['closed']}</td><td>{(x['rating'] or 0):.2f}</td></tr>" for x in tech)
    return page(f"""<h1>تقارير الدعم الفني</h1><h2>تكلفة وجودة كل تذكرة</h2><table><tr><th>التذكرة</th><th>العميل</th><th>الأولوية</th><th>الفني</th><th>الحالة</th><th>عمالة</th><th>زيارات</th><th>قطع</th><th>التكلفة</th><th>تجاوز SLA</th><th>التقييم</th></tr>{rr}</table><h2>أداء الفنيين</h2><table><tr><th>الفني</th><th>التذاكر</th><th>المغلقة</th><th>متوسط التقييم</th></tr>{tr}</table>""")


def inv_adjust_v47(c,item,wh,bn,lot,delta):
    r=c.execute("SELECT * FROM stock_balances_v47 WHERE item_id=? AND warehouse_id=? AND coalesce(bin_id,0)=coalesce(?,0) AND coalesce(lot_id,0)=coalesce(?,0)",(item,wh,bn,lot)).fetchone()
    if r:
        q=r["qty"]+delta
        if q < -0.00001: raise ValueError("الرصيد غير كافٍ")
        c.execute("UPDATE stock_balances_v47 SET qty=? WHERE id=?",(q,r["id"]))
    else:
        if delta<0: raise ValueError("الرصيد غير كافٍ")
        c.execute("INSERT INTO stock_balances_v47(item_id,warehouse_id,bin_id,lot_id,qty,reserved_qty) VALUES(?,?,?,?,?,0)",(item,wh,bn,lot,delta))

