    wo="".join("<option value='%s'>%s — %s</option>"%(x["id"],x["code"],x["name"]) for x in wh);io="".join("<option value='%s'>%s — %s</option>"%(x["id"],x["sku"],x["name"]) for x in it);bo="<option value=''>بدون رف</option>"+"".join("<option value='%s'>%s/%s</option>"%(x["id"],x["wh"],x["code"]) for x in bn);lo="<option value=''>بدون دفعة</option>"+"".join("<option value='%s'>%s — %s %s</option>"%(x["id"],x["sku"],x["lot_no"],x["serial_no"]) for x in lots)
    rr="".join("<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%.2f</td><td>%s</td></tr>"%(x["sku"],x["name"],x["barcode"] or "-",x["unit"],x["reorder_level"],x["track_type"]) for x in it)
