@app.route("/inventory-transfer-v47",methods=["GET","POST"])
def inventory_transfer_v47():
    if session.get("role") not in ("admin","accountant"): return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"];item=int(request.form["item"]);qty=float(request.form["qty"])
            if a=="transfer":
                fw=int(request.form["from_wh"]);tw=int(request.form["to_wh"]);fb=int(request.form["from_bin"]) if request.form.get("from_bin") else None;tb=int(request.form["to_bin"]) if request.form.get("to_bin") else None
                r=c.execute("SELECT coalesce(sum(qty-reserved_qty),0) a FROM stock_balances_v47 WHERE item_id=? AND warehouse_id=? AND coalesce(bin_id,0)=coalesce(?,0)",(item,fw,fb)).fetchone()["a"]
                if r<qty: raise ValueError("الرصيد المتاح غير كافٍ")
                inv_adjust_v47(c,item,fw,fb,None,-qty);inv_adjust_v47(c,item,tw,tb,None,qty)
                c.execute("INSERT INTO stock_moves_v47(move_no,move_date,item_id,qty,from_warehouse_id,from_bin_id,to_warehouse_id,to_bin_id,move_type,reference) VALUES(?,?,?,?,?,?,?,?,?,?)",(number("SM"),request.form["date"],item,qty,fw,fb,tw,tb,"TRANSFER",request.form.get("reference","")))
            else:
                wh=int(request.form["warehouse"]);bn=int(request.form["bin"]) if request.form.get("bin") else None
                r=c.execute("SELECT * FROM stock_balances_v47 WHERE item_id=? AND warehouse_id=? AND coalesce(bin_id,0)=coalesce(?,0)",(item,wh,bn)).fetchone()
                if not r or r["qty"]-r["reserved_qty"]<qty: raise ValueError("الكمية المتاحة للحجز غير كافية")
                c.execute("UPDATE stock_balances_v47 SET reserved_qty=reserved_qty+? WHERE id=?",(qty,r["id"]))
                c.execute("INSERT INTO stock_reservations_v47(item_id,warehouse_id,bin_id,qty,reference,reserve_date) VALUES(?,?,?,?,?,?)",(item,wh,bn,qty,request.form["reference"],request.form["date"]))
            c.commit();flash("تمت الحركة")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/inventory-transfer-v47")
    wh=c.execute("SELECT * FROM warehouses_v47 WHERE active=1").fetchall();bn=c.execute("SELECT b.*,w.code wh FROM warehouse_bins_v47 b JOIN warehouses_v47 w ON w.id=b.warehouse_id").fetchall();it=c.execute("SELECT * FROM inventory_items_v47 WHERE active=1").fetchall();c.close()
    wo="".join("<option value='%s'>%s — %s</option>"%(x["id"],x["code"],x["name"]) for x in wh);io="".join("<option value='%s'>%s — %s</option>"%(x["id"],x["sku"],x["name"]) for x in it);bo="<option value=''>بدون رف</option>"+"".join("<option value='%s'>%s/%s</option>"%(x["id"],x["wh"],x["code"]) for x in bn)
    return page(f"""<h1>تحويل وحجز المخزون</h1><form method=post class=panel><input type=hidden name=action value=transfer><select name=item>{io}</select><select name=from_wh>{wo}</select><select name=from_bin>{bo}</select><select name=to_wh>{wo}</select><select name=to_bin>{bo}</select><input type=date name=date required><input name=qty type=number step=.01 min=.01 required><input name=reference placeholder=المرجع><button>تحويل</button></form><h2>حجز المخزون</h2><form method=post class=panel><input type=hidden name=action value=reserve><select name=item>{io}</select><select name=warehouse>{wo}</select><select name=bin>{bo}</select><input type=date name=date required><input name=qty type=number step=.01 min=.01 required><input name=reference required placeholder="أمر بيع / مشروع"><button>حجز</button></form>""")

