def fifo_issue_v48(c,item,wh,qty):
    need=qty; total=0.0
    for x in c.execute("SELECT * FROM inventory_cost_layers_v48 WHERE item_id=? AND warehouse_id=? AND qty_remaining>0 ORDER BY receipt_date,id",(item,wh)).fetchall():
        if need<=0: break
        take=min(need,x["qty_remaining"]);total+=take*x["unit_cost"];need-=take
        c.execute("UPDATE inventory_cost_layers_v48 SET qty_remaining=qty_remaining-? WHERE id=?",(take,x["id"]))
    if need>.00001: raise ValueError("طبقات تكلفة FIFO غير كافية. استلم الصنف عن طريق مشتريات v48 أولاً.")
    return total

