        rr+=f"<tr><td>{x['delivery_no']}</td><td>{x['customer']}</td><td>{x['wh']}</td><td>{x['total']:.2f}</td><td>{x['cogs_total']:.2f}</td><td>{x['status']}</td><td>{b}</td></tr>"
