@app.route("/manufacturing-orders-v49",methods=["GET","POST"])
def manufacturing_orders_v49():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="new":
                bom=c.execute("SELECT * FROM boms_v49 WHERE id=?",(int(request.form["bom"]),)).fetchone();q=float(request.form["qty"])
                mid=c.execute("INSERT INTO manufacturing_orders_v49(mo_no,bom_id,warehouse_id,planned_qty,start_date,due_date,notes) VALUES(?,?,?,?,?,?,?)",(request.form["no"],bom["id"],int(request.form["warehouse"]),q,request.form["start"],request.form["due"],request.form.get("notes",""))).lastrowid
                factor=q/bom["output_qty"]
                for x in c.execute("SELECT * FROM bom_lines_v49 WHERE bom_id=?",(bom["id"],)).fetchall():
                    rq=x["qty"]*factor*(1+x["scrap_pct"]/100);c.execute("INSERT INTO mo_materials_v49(mo_id,item_id,required_qty) VALUES(?,?,?)",(mid,x["component_item_id"],rq))
                for x in c.execute("SELECT * FROM bom_operations_v49 WHERE bom_id=? ORDER BY sequence_no",(bom["id"],)).fetchall():c.execute("INSERT INTO mo_operations_v49(mo_id,sequence_no,work_center_id,operation_name,planned_hours) VALUES(?,?,?,?,?)",(mid,x["sequence_no"],x["work_center_id"],x["operation_name"],x["hours"]*factor))
            elif a=="issue":
                h=c.execute("SELECT * FROM manufacturing_orders_v49 WHERE id=?",(int(request.form["id"]),)).fetchone();mat=0
                for x in c.execute("SELECT * FROM mo_materials_v49 WHERE mo_id=?",(h["id"],)).fetchall():
                    need=x["required_qty"]-x["issued_qty"]
                    if need>0:
                        bal=c.execute("SELECT coalesce(sum(qty-reserved_qty),0) a FROM stock_balances_v47 WHERE item_id=? AND warehouse_id=?",(x["item_id"],h["warehouse_id"])).fetchone()["a"]
                        if bal<need:raise ValueError("مواد خام غير كافية")
                        # consume from available bins
                        rem=need
                        for b in c.execute("SELECT * FROM stock_balances_v47 WHERE item_id=? AND warehouse_id=? AND qty-reserved_qty>0 ORDER BY id",(x["item_id"],h["warehouse_id"])).fetchall():
                            take=min(rem,b["qty"]-b["reserved_qty"]);inv_adjust_v47(c,x["item_id"],h["warehouse_id"],b["bin_id"],b["lot_id"],-take);rem-=take
                            if rem<=.00001:break
                        cost=fifo_issue_v48(c,x["item_id"],h["warehouse_id"],need);mat+=cost;c.execute("UPDATE mo_materials_v49 SET issued_qty=issued_qty+?,unit_cost=?,total_cost=total_cost+? WHERE id=?",(need,cost/need,cost,x["id"]))
                c.execute("UPDATE manufacturing_orders_v49 SET status='IN_PROGRESS',material_cost=material_cost+? WHERE id=?",(mat,h["id"]))
            elif a=="hours":
                op=c.execute("SELECT o.*,w.hourly_cost FROM mo_operations_v49 o JOIN work_centers_v49 w ON w.id=o.work_center_id WHERE o.id=?",(int(request.form["op"]),)).fetchone();hrs=float(request.form["hours"]);cost=hrs*op["hourly_cost"];c.execute("UPDATE mo_operations_v49 SET actual_hours=actual_hours+?,cost=cost+?,status='DONE' WHERE id=?",(hrs,cost,op["id"]));c.execute("UPDATE manufacturing_orders_v49 SET labor_cost=labor_cost+? WHERE id=?",(cost,op["mo_id"]))
            elif a=="scrap":
                h=c.execute("SELECT * FROM manufacturing_orders_v49 WHERE id=?",(int(request.form["id"]),)).fetchone();q=float(request.form["qty"]);cost=float(request.form.get("cost") or 0);c.execute("INSERT INTO mo_scrap_v49(mo_id,item_id,qty,unit_cost,total_cost,reason,scrap_date) VALUES(?,?,?,?,?,?,?)",(h["id"],int(request.form["item"]),q,cost,q*cost,request.form.get("reason",""),request.form["date"]));c.execute("UPDATE manufacturing_orders_v49 SET scrap_cost=scrap_cost+? WHERE id=?",(q*cost,h["id"]))
            else:
                h=c.execute("SELECT m.*,b.product_item_id FROM manufacturing_orders_v49 m JOIN boms_v49 b ON b.id=m.bom_id WHERE m.id=?",(int(request.form["id"]),)).fetchone()
                if h["status"]=="COMPLETED":raise ValueError("أمر الإنتاج مكتمل")
                total=h["material_cost"]+h["labor_cost"]+h["overhead_cost"]+h["scrap_cost"];unit=total/h["planned_qty"] if h["planned_qty"] else 0
                inv_adjust_v47(c,h["product_item_id"],h["warehouse_id"],None,None,h["planned_qty"]);c.execute("INSERT INTO inventory_cost_layers_v48(item_id,warehouse_id,receipt_ref,receipt_date,qty_received,qty_remaining,unit_cost,source_type) VALUES(?,?,?,?,?,?,?,'MANUFACTURING')",(h["product_item_id"],h["warehouse_id"],h["mo_no"],request.form["date"],h["planned_qty"],h["planned_qty"],unit))
                c.execute("UPDATE manufacturing_orders_v49 SET status='COMPLETED',completed_qty=planned_qty,total_cost=? WHERE id=?",(total,h["id"]))
            c.commit();flash("تم تحديث أمر الإنتاج")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/manufacturing-orders-v49")
    boms=c.execute("SELECT b.*,i.name product FROM boms_v49 b JOIN inventory_items_v47 i ON i.id=b.product_item_id WHERE b.status='ACTIVE'").fetchall();wh=c.execute("SELECT * FROM warehouses_v47 WHERE active=1").fetchall();it=c.execute("SELECT * FROM inventory_items_v47 WHERE active=1").fetchall();mos=c.execute("SELECT m.*,b.bom_no,i.name product,w.code wh FROM manufacturing_orders_v49 m JOIN boms_v49 b ON b.id=m.bom_id JOIN inventory_items_v47 i ON i.id=b.product_item_id JOIN warehouses_v47 w ON w.id=m.warehouse_id ORDER BY m.id DESC").fetchall();ops=c.execute("SELECT o.*,m.mo_no,w.name wc FROM mo_operations_v49 o JOIN manufacturing_orders_v49 m ON m.id=o.mo_id JOIN work_centers_v49 w ON w.id=o.work_center_id WHERE m.status!='COMPLETED' ORDER BY m.id,o.sequence_no").fetchall();c.close()
    bo="".join(f"<option value='{x['id']}'>{x['bom_no']} — {x['product']}</option>" for x in boms);wo="".join(f"<option value='{x['id']}'>{x['code']} — {x['name']}</option>" for x in wh);io="".join(f"<option value='{x['id']}'>{x['sku']} — {x['name']}</option>" for x in it);oo="".join(f"<option value='{x['id']}'>{x['mo_no']} — {x['operation_name']} / {x['wc']}</option>" for x in ops)
    rr=""
    for x in mos:
        actions="" if x["status"]=="COMPLETED" else f"<form method=post><input type=hidden name=action value=issue><input type=hidden name=id value='{x['id']}'><button>صرف المواد</button></form><form method=post><input type=hidden name=action value=complete><input type=hidden name=id value='{x['id']}'><input type=date name=date required><button>إتمام الإنتاج</button></form>"
        rr+=f"<tr><td>{x['mo_no']}</td><td>{x['product']}</td><td>{x['planned_qty']:.2f}</td><td>{x['wh']}</td><td>{x['status']}</td><td>{x['material_cost']:.2f}</td><td>{x['labor_cost']:.2f}</td><td>{x['scrap_cost']:.2f}</td><td>{x['total_cost']:.2f}</td><td>{actions}</td></tr>"
    return page(f"""<h1>أوامر الإنتاج v49</h1><form method=post class=panel><input type=hidden name=action value=new><input name=no required placeholder="رقم أمر الإنتاج"><select name=bom>{bo}</select><select name=warehouse>{wo}</select><input name=qty type=number step=.01 min=.01 required placeholder="كمية الإنتاج"><input type=date name=start required><input type=date name=due required><input name=notes placeholder=ملاحظات><button>إنشاء أمر</button></form>
    <h2>تسجيل ساعات التشغيل</h2><form method=post class=panel><input type=hidden name=action value=hours><select name=op>{oo}</select><input name=hours type=number step=.01 min=.01 required placeholder="الساعات الفعلية"><button>تسجيل</button></form>
    <h2>هالك الإنتاج</h2><form method=post class=panel><input type=hidden name=action value=scrap><select name=id>{''.join(f"<option value='{x['id']}'>{x['mo_no']}</option>" for x in mos if x['status']!='COMPLETED')}</select><select name=item>{io}</select><input name=qty type=number step=.01 min=.01 required><input name=cost type=number step=.01 min=0 value=0 placeholder="تكلفة الوحدة"><input type=date name=date required><input name=reason placeholder="سبب الهالك"><button>تسجيل هالك</button></form>
    <table><tr><th>الأمر</th><th>المنتج</th><th>الكمية</th><th>المستودع</th><th>الحالة</th><th>مواد</th><th>تشغيل</th><th>هالك</th><th>الإجمالي</th><th>الإجراء</th></tr>{rr}</table>""")

@app.route("/mrp-planning-v49")
def mrp_planning_v49():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con();rows=c.execute("""SELECT i.sku,i.name,sum(m.required_qty-m.issued_qty) demand,
    coalesce((SELECT sum(s.qty-s.reserved_qty) FROM stock_balances_v47 s WHERE s.item_id=i.id),0) available
    FROM mo_materials_v49 m JOIN inventory_items_v47 i ON i.id=m.item_id JOIN manufacturing_orders_v49 o ON o.id=m.mo_id
    WHERE o.status IN ('PLANNED','IN_PROGRESS') GROUP BY i.id ORDER BY i.sku""").fetchall();c.close()
    rr="".join(f"<tr><td>{x['sku']}</td><td>{x['name']}</td><td>{x['demand']:.2f}</td><td>{x['available']:.2f}</td><td>{max(x['demand']-x['available'],0):.2f}</td><td>{'شراء/توريد مطلوب' if x['demand']>x['available'] else 'متوفر'}</td></tr>" for x in rows)
    return page(f"<h1>تخطيط احتياجات المواد MRP</h1><table><tr><th>SKU</th><th>المادة</th><th>الطلب الإنتاجي</th><th>المتاح</th><th>العجز</th><th>التوصية</th></tr>{rr}</table>")


