@app.route("/attendance-v50",methods=["GET","POST"])
def attendance_v50():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    import datetime
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="attendance":
                ci=request.form.get("in","");co=request.form.get("out","");hrs=0
                if ci and co:
                    t1=datetime.datetime.strptime(ci,"%H:%M");t2=datetime.datetime.strptime(co,"%H:%M");hrs=max((t2-t1).total_seconds()/3600,0)
                c.execute("""INSERT OR REPLACE INTO attendance_v50(employee_id,work_date,check_in,check_out,worked_hours,overtime_hours,late_minutes,status)
                VALUES(?,?,?,?,?,?,?,?)""",(int(request.form["employee"]),request.form["date"],ci,co,hrs,float(request.form.get("overtime") or 0),float(request.form.get("late") or 0),request.form["status"]))
            else:
                d1=datetime.date.fromisoformat(request.form["start"]);d2=datetime.date.fromisoformat(request.form["end"]);days=(d2-d1).days+1
                c.execute("INSERT INTO leave_requests_v50(employee_id,leave_type,start_date,end_date,days,paid,status,notes) VALUES(?,?,?,?,?,?,?,?)",(int(request.form["employee"]),request.form["type"],request.form["start"],request.form["end"],days,1 if request.form.get("paid")=="1" else 0,"APPROVED",request.form.get("notes","")))
            c.commit();flash("تم الحفظ")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/attendance-v50")
    em=c.execute("SELECT * FROM employees_v50 WHERE status='ACTIVE' ORDER BY emp_no").fetchall();at=c.execute("SELECT a.*,e.emp_no,e.name FROM attendance_v50 a JOIN employees_v50 e ON e.id=a.employee_id ORDER BY a.work_date DESC,a.id DESC LIMIT 200").fetchall();lv=c.execute("SELECT l.*,e.name FROM leave_requests_v50 l JOIN employees_v50 e ON e.id=l.employee_id ORDER BY l.id DESC LIMIT 100").fetchall();c.close()
    eo="".join(f"<option value='{x['id']}'>{x['emp_no']} — {x['name']}</option>" for x in em);ar="".join(f"<tr><td>{x['work_date']}</td><td>{x['emp_no']}</td><td>{x['name']}</td><td>{x['check_in'] or '-'}</td><td>{x['check_out'] or '-'}</td><td>{x['worked_hours']:.2f}</td><td>{x['overtime_hours']:.2f}</td><td>{x['late_minutes']:.0f}</td><td>{x['status']}</td></tr>" for x in at)
    return page(f"""<h1>الحضور والإجازات v50</h1><form method=post class=panel><input type=hidden name=action value=attendance><select name=employee>{eo}</select><input type=date name=date required><input type=time name=in><input type=time name=out><input name=overtime type=number step=.25 min=0 value=0 placeholder="إضافي"><input name=late type=number min=0 value=0 placeholder="دقائق التأخير"><select name=status><option>PRESENT</option><option>ABSENT</option><option>REMOTE</option></select><button>تسجيل</button></form>
    <h2>إجازة</h2><form method=post class=panel><input type=hidden name=action value=leave><select name=employee>{eo}</select><select name=type><option>سنوية</option><option>مرضية</option><option>بدون راتب</option><option>أخرى</option></select><input type=date name=start required><input type=date name=end required><select name=paid><option value=1>مدفوعة</option><option value=0>غير مدفوعة</option></select><input name=notes placeholder=ملاحظات><button>اعتماد الإجازة</button></form>
    <table><tr><th>التاريخ</th><th>الرقم</th><th>الموظف</th><th>دخول</th><th>خروج</th><th>الساعات</th><th>إضافي</th><th>تأخير</th><th>الحالة</th></tr>{ar}</table>""")

@app.route("/payroll-v50",methods=["GET","POST"])
def payroll_v50():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="new":
                run=c.execute("INSERT INTO payroll_runs_v50(run_no,period_month,pay_date) VALUES(?,?,?)",(request.form["no"],request.form["month"],request.form["paydate"])).lastrowid
                month=request.form["month"]
                for e in c.execute("SELECT * FROM employees_v50 WHERE status='ACTIVE'").fetchall():
                    ot=c.execute("SELECT coalesce(sum(overtime_hours),0) x FROM attendance_v50 WHERE employee_id=? AND substr(work_date,1,7)=?",(e["id"],month)).fetchone()["x"]
                    absent=c.execute("SELECT count(*) x FROM attendance_v50 WHERE employee_id=? AND substr(work_date,1,7)=? AND status='ABSENT'",(e["id"],month)).fetchone()["x"]
                    overtime=(e["basic_salary"]/240.0)*1.5*ot if e["basic_salary"] else 0;absence=e["basic_salary"]/30.0*absent
                    loan=c.execute("SELECT * FROM employee_loans_v50 WHERE employee_id=? AND status='ACTIVE' AND balance>0 ORDER BY id LIMIT 1",(e["id"],)).fetchone();ld=min(loan["installment"],loan["balance"]) if loan else 0
                    gross=e["basic_salary"]+e["housing_allowance"]+e["transport_allowance"]+e["other_allowance"]+overtime;net=gross-absence-ld
                    c.execute("INSERT INTO payroll_lines_v50(run_id,employee_id,basic,housing,transport,other_allowance,overtime,absence_deduction,loan_deduction,gross,net) VALUES(?,?,?,?,?,?,?,?,?,?,?)",(run,e["id"],e["basic_salary"],e["housing_allowance"],e["transport_allowance"],e["other_allowance"],overtime,absence,ld,gross,net))
                x=c.execute("SELECT coalesce(sum(gross),0) g,coalesce(sum(absence_deduction+loan_deduction+other_deduction),0) d,coalesce(sum(net),0) n FROM payroll_lines_v50 WHERE run_id=?",(run,)).fetchone();c.execute("UPDATE payroll_runs_v50 SET gross_total=?,deduction_total=?,net_total=? WHERE id=?",(x["g"],x["d"],x["n"],run))
            else:
                h=c.execute("SELECT * FROM payroll_runs_v50 WHERE id=?",(int(request.form["id"]),)).fetchone()
                if h["status"]!="DRAFT":raise ValueError("المسير مرحل")
                ensure_open_period(c,h["pay_date"]);jid=c.execute("INSERT INTO journals(no,date,description,source) VALUES(?,?,?,?)",(number("JV"),h["pay_date"],"مسير رواتب "+h["run_no"],"PAYROLL-V50")).lastrowid
                basic=sum(x["basic"] for x in c.execute("SELECT * FROM payroll_lines_v50 WHERE run_id=?",(h["id"],)).fetchall());allow=sum(x["housing"]+x["transport"]+x["other_allowance"] for x in c.execute("SELECT * FROM payroll_lines_v50 WHERE run_id=?",(h["id"],)).fetchall());ot=sum(x["overtime"] for x in c.execute("SELECT * FROM payroll_lines_v50 WHERE run_id=?",(h["id"],)).fetchall())
                c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"5200"),basic,0))
                if allow:c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"5210"),allow,0))
                if ot:c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"5220"),ot,0))
                c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"2300"),0,h["net_total"]))
                for x in c.execute("SELECT * FROM payroll_lines_v50 WHERE run_id=? AND loan_deduction>0",(h["id"],)).fetchall():
                    loan=c.execute("SELECT * FROM employee_loans_v50 WHERE employee_id=? AND status='ACTIVE' AND balance>0 ORDER BY id LIMIT 1",(x["employee_id"],)).fetchone()
                    if loan:
                        nb=max(loan["balance"]-x["loan_deduction"],0);c.execute("UPDATE employee_loans_v50 SET balance=?,status=? WHERE id=?",(nb,"CLOSED" if nb<=.00001 else "ACTIVE",loan["id"]))
                c.execute("UPDATE payroll_runs_v50 SET status='POSTED',journal_id=? WHERE id=?",(jid,h["id"]))
            c.commit();flash("تم تحديث مسير الرواتب")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/payroll-v50")
    runs=c.execute("SELECT * FROM payroll_runs_v50 ORDER BY id DESC").fetchall();lines=c.execute("SELECT l.*,e.emp_no,e.name,r.run_no FROM payroll_lines_v50 l JOIN employees_v50 e ON e.id=l.employee_id JOIN payroll_runs_v50 r ON r.id=l.run_id ORDER BY l.id DESC LIMIT 300").fetchall();c.close()
    rr=""
    for x in runs:
        b="" if x["status"]!="DRAFT" else f"<form method=post><input type=hidden name=action value=post><input type=hidden name=id value='{x['id']}'><button>ترحيل للمحاسبة</button></form>"
        rr+=f"<tr><td>{x['run_no']}</td><td>{x['period_month']}</td><td>{x['pay_date']}</td><td>{x['gross_total']:.2f}</td><td>{x['deduction_total']:.2f}</td><td>{x['net_total']:.2f}</td><td>{x['status']}</td><td>{b}</td></tr>"
    lr="".join(f"<tr><td>{x['run_no']}</td><td>{x['emp_no']}</td><td>{x['name']}</td><td>{x['basic']:.2f}</td><td>{x['housing']+x['transport']+x['other_allowance']:.2f}</td><td>{x['overtime']:.2f}</td><td>{x['absence_deduction']:.2f}</td><td>{x['loan_deduction']:.2f}</td><td>{x['net']:.2f}</td></tr>" for x in lines)
    return page(f"""<h1>مسير الرواتب v50</h1><form method=post class=panel><input type=hidden name=action value=new><input name=no required placeholder="رقم المسير"><input type=month name=month required><input type=date name=paydate required><button>إنشاء المسير</button></form><table><tr><th>المسير</th><th>الشهر</th><th>الدفع</th><th>الإجمالي</th><th>الخصومات</th><th>الصافي</th><th>الحالة</th><th></th></tr>{rr}</table><h2>تفاصيل الرواتب</h2><table><tr><th>المسير</th><th>الرقم</th><th>الموظف</th><th>الأساسي</th><th>البدلات</th><th>الإضافي</th><th>غياب</th><th>سلفة</th><th>الصافي</th></tr>{lr}</table>""")

