@app.route("/depreciation-v51",methods=["GET","POST"])
def depreciation_v51():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            period=request.form["period"];depdate=request.form["date"];total=0
            ensure_open_period(c,depdate);jid=c.execute("INSERT INTO journals(no,date,description,source) VALUES(?,?,?,?)",(number("JV"),depdate,"إهلاك الأصول "+period,"DEPRECIATION-V51")).lastrowid
            for x in c.execute("SELECT * FROM fixed_assets_v51 WHERE status='ACTIVE'").fetchall():
                remaining=max(x["cost"]-x["salvage_value"]-x["accum_depreciation"],0)
                monthly=(x["cost"]-x["salvage_value"])/x["useful_life_months"] if x["useful_life_months"] else 0;amt=min(monthly,remaining)
                if amt<=0:continue
                c.execute("INSERT OR IGNORE INTO asset_depreciation_v51(asset_id,period,dep_date,amount,accum_amount,book_value,status,journal_id) VALUES(?,?,?,?,?,?,'POSTED',?)",(x["id"],period,depdate,amt,x["accum_depreciation"]+amt,x["book_value"]-amt,jid))
                if c.execute("SELECT changes() x").fetchone()["x"]:
                    c.execute("UPDATE fixed_assets_v51 SET accum_depreciation=accum_depreciation+?,book_value=book_value-? WHERE id=?",(amt,amt,x["id"]));total+=amt
            if total>0:
                c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"5300"),total,0));c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"1590"),0,total))
            c.commit();flash("تم ترحيل الإهلاك")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/depreciation-v51")
    rows=c.execute("SELECT d.*,a.asset_no,a.name FROM asset_depreciation_v51 d JOIN fixed_assets_v51 a ON a.id=d.asset_id ORDER BY d.dep_date DESC,d.id DESC LIMIT 500").fetchall();assets=c.execute("SELECT * FROM fixed_assets_v51 ORDER BY asset_no").fetchall();c.close()
    rr="".join(f"<tr><td>{x['period']}</td><td>{x['asset_no']}</td><td>{x['name']}</td><td>{x['amount']:.2f}</td><td>{x['accum_amount']:.2f}</td><td>{x['book_value']:.2f}</td><td>{x['status']}</td></tr>" for x in rows)
    return page(f"""<h1>إهلاك الأصول v51</h1><form method=post class=panel><input type=month name=period required><input type=date name=date required><button>احتساب وترحيل إهلاك الشهر</button></form><table><tr><th>الفترة</th><th>الأصل</th><th>الاسم</th><th>الإهلاك</th><th>المجمع</th><th>القيمة الدفترية</th><th>الحالة</th></tr>{rr}</table>""")

@app.route("/maintenance-v51",methods=["GET","POST"])
def maintenance_v51():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    import datetime
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="plan":
                c.execute("INSERT INTO maintenance_plans_v51(asset_id,plan_name,frequency_days,next_due_date,estimated_cost,notes) VALUES(?,?,?,?,?,?)",(int(request.form["asset"]),request.form["name"],int(request.form["days"]),request.form["due"],float(request.form.get("cost") or 0),request.form.get("notes","")))
            elif a=="order":
                c.execute("INSERT INTO maintenance_orders_v51(order_no,asset_id,plan_id,order_date,due_date,maintenance_type,technician,description) VALUES(?,?,?,?,?,?,?,?)",(request.form["no"],int(request.form["asset"]),int(request.form["plan"]) if request.form.get("plan") else None,request.form["date"],request.form["due"],request.form["type"],request.form.get("tech",""),request.form.get("desc","")))
            elif a=="part":
                o=c.execute("SELECT * FROM maintenance_orders_v51 WHERE id=?",(int(request.form["order"]),)).fetchone();item=int(request.form["item"]);wh=int(request.form["warehouse"]);q=float(request.form["qty"])
                bal=c.execute("SELECT coalesce(sum(qty-reserved_qty),0) a FROM stock_balances_v47 WHERE item_id=? AND warehouse_id=?",(item,wh)).fetchone()["a"]
                if bal<q:raise ValueError("رصيد قطع الغيار غير كافٍ")
                rem=q
                for b in c.execute("SELECT * FROM stock_balances_v47 WHERE item_id=? AND warehouse_id=? AND qty-reserved_qty>0 ORDER BY id",(item,wh)).fetchall():
                    take=min(rem,b["qty"]-b["reserved_qty"]);inv_adjust_v47(c,item,wh,b["bin_id"],b["lot_id"],-take);rem-=take
                    if rem<=.00001:break
                cost=fifo_issue_v48(c,item,wh,q)
                c.execute("INSERT INTO maintenance_parts_v51(order_id,item_id,warehouse_id,qty,unit_cost,total_cost) VALUES(?,?,?,?,?,?)",(o["id"],item,wh,q,cost/q,cost));c.execute("UPDATE maintenance_orders_v51 SET parts_cost=parts_cost+?,total_cost=total_cost+? WHERE id=?",(cost,cost,o["id"]))
            else:
                oid=int(request.form["order"]);labor=float(request.form.get("labor") or 0);o=c.execute("SELECT * FROM maintenance_orders_v51 WHERE id=?",(oid,)).fetchone();total=o["parts_cost"]+labor
                jid=c.execute("INSERT INTO journals(no,date,description,source) VALUES(?,?,?,?)",(number("JV"),request.form["date"],"صيانة أصل "+o["order_no"],"MAINTENANCE-V51")).lastrowid
                if total>0:c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"5310"),total,0));c.execute("INSERT INTO journal_lines(journal_id,account_id,debit,credit) VALUES(?,?,?,?)",(jid,acc(c,"1300"),0,o["parts_cost"]))
                c.execute("UPDATE maintenance_orders_v51 SET labor_cost=?,total_cost=?,status='COMPLETED',completion_date=? WHERE id=?",(labor,total,request.form["date"],oid))
                if o["plan_id"]:
                    p=c.execute("SELECT * FROM maintenance_plans_v51 WHERE id=?",(o["plan_id"],)).fetchone();nd=datetime.date.fromisoformat(request.form["date"])+datetime.timedelta(days=p["frequency_days"]);c.execute("UPDATE maintenance_plans_v51 SET next_due_date=? WHERE id=?",(nd.isoformat(),p["id"]))
            c.commit();flash("تم تحديث الصيانة")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/maintenance-v51")
    assets=c.execute("SELECT * FROM fixed_assets_v51 WHERE status='ACTIVE' ORDER BY asset_no").fetchall();plans=c.execute("SELECT p.*,a.asset_no,a.name asset FROM maintenance_plans_v51 p JOIN fixed_assets_v51 a ON a.id=p.asset_id WHERE p.active=1 ORDER BY p.next_due_date").fetchall();orders=c.execute("SELECT o.*,a.asset_no,a.name asset FROM maintenance_orders_v51 o JOIN fixed_assets_v51 a ON a.id=o.asset_id ORDER BY o.id DESC").fetchall();items=c.execute("SELECT * FROM inventory_items_v47 WHERE active=1").fetchall();wh=c.execute("SELECT * FROM warehouses_v47 WHERE active=1").fetchall();c.close()
    ao="".join(f"<option value='{x['id']}'>{x['asset_no']} — {x['name']}</option>" for x in assets);po="<option value=''>بدون خطة</option>"+"".join(f"<option value='{x['id']}'>{x['plan_name']} — {x['asset']}</option>" for x in plans);oo="".join(f"<option value='{x['id']}'>{x['order_no']} — {x['asset']}</option>" for x in orders if x["status"]!="COMPLETED");io="".join(f"<option value='{x['id']}'>{x['sku']} — {x['name']}</option>" for x in items);wo="".join(f"<option value='{x['id']}'>{x['code']} — {x['name']}</option>" for x in wh)
    rr="".join(f"<tr><td>{x['order_no']}</td><td>{x['asset_no']}</td><td>{x['asset']}</td><td>{x['maintenance_type']}</td><td>{x['due_date']}</td><td>{x['technician']}</td><td>{x['parts_cost']:.2f}</td><td>{x['labor_cost']:.2f}</td><td>{x['total_cost']:.2f}</td><td>{x['status']}</td></tr>" for x in orders)
    return page(f"""<h1>الصيانة الوقائية وأوامر الصيانة v51</h1><h2>خطة صيانة</h2><form method=post class=panel><input type=hidden name=action value=plan><select name=asset>{ao}</select><input name=name required placeholder="اسم الخطة"><input name=days type=number min=1 required placeholder="كل كم يوم"><input type=date name=due required><input name=cost type=number step=.01 min=0 value=0 placeholder="تكلفة تقديرية"><input name=notes placeholder=ملاحظات><button>إضافة خطة</button></form>
    <h2>أمر صيانة</h2><form method=post class=panel><input type=hidden name=action value=order><input name=no required placeholder="رقم الأمر"><select name=asset>{ao}</select><select name=plan>{po}</select><input type=date name=date required><input type=date name=due required><select name=type><option>وقائية</option><option>تصحيحية</option><option>طارئة</option></select><input name=tech placeholder="الفني / المقاول"><input name=desc placeholder="وصف العمل"><button>فتح الأمر</button></form>
    <h2>صرف قطع غيار</h2><form method=post class=panel><input type=hidden name=action value=part><select name=order>{oo}</select><select name=item>{io}</select><select name=warehouse>{wo}</select><input name=qty type=number step=.01 min=.01 required placeholder=الكمية><button>صرف</button></form>
    <h2>إكمال أمر الصيانة</h2><form method=post class=panel><input type=hidden name=action value=complete><select name=order>{oo}</select><input type=date name=date required><input name=labor type=number step=.01 min=0 value=0 placeholder="تكلفة العمل"><button>إكمال وترحيل</button></form>
    <table><tr><th>الأمر</th><th>الأصل</th><th>الاسم</th><th>النوع</th><th>الاستحقاق</th><th>الفني</th><th>قطع</th><th>عمل</th><th>الإجمالي</th><th>الحالة</th></tr>{rr}</table>""")


