@app.route("/crm-pipeline-v53")
def crm_pipeline_v53():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con();stages=c.execute("""SELECT stage,count(*) cnt,coalesce(sum(expected_value),0) value,coalesce(sum(expected_value*probability/100.0),0) weighted FROM crm_opportunities_v53 GROUP BY stage ORDER BY CASE stage WHEN 'QUALIFICATION' THEN 1 WHEN 'PROPOSAL' THEN 2 WHEN 'NEGOTIATION' THEN 3 WHEN 'WON' THEN 4 ELSE 5 END""").fetchall();owners=c.execute("""SELECT owner,count(*) cnt,coalesce(sum(expected_value),0) pipeline,coalesce(sum(CASE WHEN stage='WON' THEN won_value ELSE 0 END),0) won FROM crm_opportunities_v53 GROUP BY owner ORDER BY won DESC""").fetchall();c.close()
    sr="".join(f"<tr><td>{x['stage']}</td><td>{x['cnt']}</td><td>{x['value']:.2f}</td><td>{x['weighted']:.2f}</td></tr>" for x in stages);orows="".join(f"<tr><td>{x['owner']}</td><td>{x['cnt']}</td><td>{x['pipeline']:.2f}</td><td>{x['won']:.2f}</td></tr>" for x in owners)
    return page(f"<h1>تحليل Sales Pipeline v53</h1><table><tr><th>المرحلة</th><th>عدد الفرص</th><th>القيمة</th><th>القيمة المرجحة</th></tr>{sr}</table><h2>حسب مندوب المبيعات</h2><table><tr><th>المندوب</th><th>الفرص</th><th>Pipeline</th><th>المبيعات الرابحة</th></tr>{orows}</table>")


