@app.route("/company-ledger-v55",methods=["GET","POST"])
def company_ledger_v55():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            company=int(request.form["company"]);branch=int(request.form["branch"])
            if not company_access_v55(c,session.get("user",""),company,branch,True):raise ValueError("لا توجد صلاحية ترحيل لهذا الفرع")
            debit=float(request.form.get("debit") or 0);credit=float(request.form.get("credit") or 0)
            if debit<=0 and credit<=0:raise ValueError("أدخل مبلغ مدين أو دائن")
            cur=request.form["currency"];rate=float(request.form.get("rate") or 1)
            jid=c.execute("INSERT INTO company_journals_v55(no,company_id,branch_id,date,description,source,currency_code,exchange_rate) VALUES(?,?,?,?,?,'MANUAL-V55',?,?)",(request.form["no"],company,branch,request.form["date"],request.form["description"],cur,rate)).lastrowid
            aid=int(request.form["account"]);offset=int(request.form["offset"])
            c.execute("INSERT INTO company_journal_lines_v55(journal_id,account_id,debit,credit,foreign_debit,foreign_credit) VALUES(?,?,?,?,?,?)",(jid,aid,debit*rate,credit*rate,debit,credit))
            c.execute("INSERT INTO company_journal_lines_v55(journal_id,account_id,debit,credit,foreign_debit,foreign_credit) VALUES(?,?,?,?,?,?)",(jid,offset,credit*rate,debit*rate,credit,debit))
            c.commit();flash("تم ترحيل القيد للشركة والفرع")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/company-ledger-v55")
    co=c.execute("SELECT * FROM companies_v54 WHERE active=1").fetchall();br=c.execute("SELECT b.*,c.code company FROM branches_v54 b JOIN companies_v54 c ON c.id=b.company_id WHERE b.active=1").fetchall();ac=c.execute("SELECT * FROM accounts ORDER BY code").fetchall();cu=c.execute("SELECT * FROM currencies_v54 WHERE active=1").fetchall()
    rows=c.execute("""SELECT j.*,c.code company,b.code branch FROM company_journals_v55 j JOIN companies_v54 c ON c.id=j.company_id JOIN branches_v54 b ON b.id=j.branch_id ORDER BY j.id DESC LIMIT 200""").fetchall();c.close()
    coo="".join(f"<option value='{x['id']}'>{x['code']} — {x['name']}</option>" for x in co);bo="".join(f"<option value='{x['id']}'>{x['company']}/{x['code']} — {x['name']}</option>" for x in br);ao="".join(f"<option value='{x['id']}'>{x['code']} — {x['name']}</option>" for x in ac);cuo="".join(f"<option value='{x['code']}'>{x['code']}</option>" for x in cu);rr="".join(f"<tr><td>{x['no']}</td><td>{x['date']}</td><td>{x['company']}</td><td>{x['branch']}</td><td>{x['currency_code']}</td><td>{x['exchange_rate']:.6f}</td><td>{x['description']}</td></tr>" for x in rows)
    return page(f"<h1>دفتر الشركة والفرع v55</h1><form method=post class=panel><input name=no required placeholder='رقم القيد'><select name=company>{coo}</select><select name=branch>{bo}</select><input type=date name=date required><input name=description required placeholder=البيان><select name=account>{ao}</select><select name=offset>{ao}</select><input name=debit type=number step=.01 min=0 value=0 placeholder=مدين><input name=credit type=number step=.01 min=0 value=0 placeholder=دائن><select name=currency>{cuo}</select><input name=rate type=number step=.000001 min=.000001 value=1><button>ترحيل</button></form><table><tr><th>القيد</th><th>التاريخ</th><th>الشركة</th><th>الفرع</th><th>العملة</th><th>الصرف</th><th>البيان</th></tr>{rr}</table>")

