def safe_sum_v59(c,sql,args=()):
    try:
        x=c.execute(sql,args).fetchone()
        return float(x[0] or 0) if x else 0
    except: return 0

@app.route("/executive-dashboard-v59")
def executive_dashboard_v59():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con()
    company=request.args.get("company","");branch=request.args.get("branch","");start=request.args.get("start","");end=request.args.get("end","")
    co=c.execute("SELECT * FROM companies_v54 WHERE active=1 ORDER BY code").fetchall()
    br=c.execute("SELECT b.*,co.code company FROM branches_v54 b JOIN companies_v54 co ON co.id=b.company_id WHERE b.active=1 ORDER BY co.code,b.code").fetchall()
    cond=[];args=[]
    if company:cond.append("company_id=?");args.append(int(company))
    if branch:cond.append("branch_id=?");args.append(int(branch))
    scope=(" WHERE "+" AND ".join(cond)) if cond else ""
    def dated(table,datecol,amountcol):
        q=f"SELECT coalesce(sum({amountcol}),0) FROM {table}"+scope
        aa=list(args); extra=[]
        if start:extra.append(f"{datecol}>=?");aa.append(start)
        if end:extra.append(f"{datecol}<=?");aa.append(end)
        if extra:q+=(" AND " if scope else " WHERE ")+" AND ".join(extra)
        return safe_sum_v59(c,q,aa)
    sales=dated("company_sales_v56","doc_date","amount");purchases=dated("company_purchases_v56","doc_date","amount")
    inventory=safe_sum_v59(c,"SELECT coalesce(sum(qty),0) FROM company_inventory_v56"+scope,args)
    project_cost=safe_sum_v59(c,"SELECT coalesce(sum(actual_cost),0) FROM (SELECT p.id,coalesce((SELECT sum(total_cost) FROM project_timesheets_v52 t WHERE t.project_id=p.id),0)+coalesce((SELECT sum(amount) FROM project_expenses_v52 e WHERE e.project_id=p.id),0)+coalesce((SELECT sum(amount) FROM project_purchases_v52 q WHERE q.project_id=p.id),0) actual_cost FROM projects_v52 p)")
    payroll=safe_sum_v59(c,"SELECT coalesce(sum(net_salary),0) FROM payroll_v50")
    assets=safe_sum_v59(c,"SELECT coalesce(sum(purchase_cost),0) FROM fixed_assets_v51")
    receivables=safe_sum_v59(c,"SELECT coalesce(sum(debit-credit),0) FROM company_journal_lines_v55 l JOIN accounts a ON a.id=l.account_id WHERE a.type='asset'")
    payables=safe_sum_v59(c,"SELECT coalesce(sum(credit-debit),0) FROM company_journal_lines_v55 l JOIN accounts a ON a.id=l.account_id WHERE a.type='liability'")
    gross=sales-purchases
    monthly=c.execute("""SELECT substr(doc_date,1,7) m,sum(amount) v FROM company_sales_v56 GROUP BY substr(doc_date,1,7) ORDER BY m DESC LIMIT 12""").fetchall()
    low=c.execute("""SELECT co.code company,b.code branch,w.code warehouse,i.sku,i.name,x.qty FROM company_inventory_v56 x JOIN companies_v54 co ON co.id=x.company_id JOIN branches_v54 b ON b.id=x.branch_id JOIN warehouses_v47 w ON w.id=x.warehouse_id JOIN inventory_items_v47 i ON i.id=x.item_id WHERE x.qty<=5 ORDER BY x.qty LIMIT 20""").fetchall()
    projects=c.execute("""SELECT project_no,name,budget,completion_pct FROM projects_v52 ORDER BY id DESC LIMIT 10""").fetchall()
    c.close()
    coo="<option value=''>كل الشركات</option>"+"".join(f"<option value='{x['id']}' {'selected' if str(x['id'])==company else ''}>{x['code']} — {x['name']}</option>" for x in co)
    bo="<option value=''>كل الفروع</option>"+"".join(f"<option value='{x['id']}' {'selected' if str(x['id'])==branch else ''}>{x['company']}/{x['code']} — {x['name']}</option>" for x in br)
    mr="".join(f"<tr><td>{x['m']}</td><td>{x['v']:.2f}</td></tr>" for x in monthly)
    lr="".join(f"<tr><td>{x['company']}</td><td>{x['branch']}</td><td>{x['warehouse']}</td><td>{x['sku']}</td><td>{x['name']}</td><td>{x['qty']:.2f}</td></tr>" for x in low)
    pr="".join(f"<tr><td>{x['project_no']}</td><td>{x['name']}</td><td>{x['budget']:.2f}</td><td>{x['completion_pct']:.1f}%</td></tr>" for x in projects)
    return page(f"""<h1>لوحة الإدارة التنفيذية v59</h1>
    <form method=get class=panel><select name=company>{coo}</select><select name=branch>{bo}</select><label>من</label><input type=date name=start value="{start}"><label>إلى</label><input type=date name=end value="{end}"><button>تحديث المؤشرات</button></form>
    <div class=panel><h2>المؤشرات الرئيسية KPI</h2>
    <table><tr><th>المبيعات</th><th>المشتريات</th><th>الهامش الأولي</th><th>كمية المخزون</th><th>الذمم المدينة</th><th>الذمم الدائنة</th><th>تكلفة المشاريع</th><th>الرواتب</th><th>قيمة الأصول</th></tr>
    <tr><td>{sales:.2f}</td><td>{purchases:.2f}</td><td>{gross:.2f}</td><td>{inventory:.2f}</td><td>{receivables:.2f}</td><td>{payables:.2f}</td><td>{project_cost:.2f}</td><td>{payroll:.2f}</td><td>{assets:.2f}</td></tr></table></div>
    <h2>اتجاه المبيعات الشهري</h2><table><tr><th>الشهر</th><th>المبيعات</th></tr>{mr}</table>
    <h2>تنبيهات المخزون المنخفض</h2><table><tr><th>الشركة</th><th>الفرع</th><th>المستودع</th><th>الصنف</th><th>الاسم</th><th>الكمية</th></tr>{lr}</table>
    <h2>حالة المشاريع</h2><table><tr><th>المشروع</th><th>الاسم</th><th>الميزانية</th><th>الإنجاز</th></tr>{pr}</table>""")

