def report_data_v60(c,code,start="",end="",company="",branch=""):
    if code=="SALES":
        q="""SELECT s.doc_no 'رقم المستند',s.doc_date 'التاريخ',co.code 'الشركة',b.code 'الفرع',
        coalesce(cu.name,'') 'العميل',s.amount 'المبلغ',s.status 'الحالة',coalesce(s.reference,'') 'المرجع'
        FROM company_sales_v56 s JOIN companies_v54 co ON co.id=s.company_id JOIN branches_v54 b ON b.id=s.branch_id
        LEFT JOIN company_customers_v55 cu ON cu.id=s.customer_id WHERE 1=1"""; args=[]
        if start:q+=" AND s.doc_date>=?";args.append(start)
        if end:q+=" AND s.doc_date<=?";args.append(end)
        if company:q+=" AND s.company_id=?";args.append(int(company))
        if branch:q+=" AND s.branch_id=?";args.append(int(branch))
        q+=" ORDER BY s.doc_date,s.doc_no"; rows=c.execute(q,args).fetchall()
    elif code=="PURCHASES":
        q="""SELECT p.doc_no 'رقم المستند',p.doc_date 'التاريخ',co.code 'الشركة',b.code 'الفرع',
        coalesce(su.name,'') 'المورد',p.amount 'المبلغ',p.status 'الحالة',coalesce(p.reference,'') 'المرجع'
        FROM company_purchases_v56 p JOIN companies_v54 co ON co.id=p.company_id JOIN branches_v54 b ON b.id=p.branch_id
        LEFT JOIN company_suppliers_v55 su ON su.id=p.supplier_id WHERE 1=1""";args=[]
        if start:q+=" AND p.doc_date>=?";args.append(start)
        if end:q+=" AND p.doc_date<=?";args.append(end)
        if company:q+=" AND p.company_id=?";args.append(int(company))
        if branch:q+=" AND p.branch_id=?";args.append(int(branch))
        q+=" ORDER BY p.doc_date,p.doc_no";rows=c.execute(q,args).fetchall()
    elif code=="TRIAL":
        q="""SELECT co.code 'الشركة',b.code 'الفرع',a.code 'الحساب',a.name 'اسم الحساب',
        round(sum(l.debit),2) 'مدين',round(sum(l.credit),2) 'دائن',round(sum(l.debit-l.credit),2) 'الرصيد'
        FROM company_journal_lines_v55 l JOIN company_journals_v55 j ON j.id=l.journal_id
        JOIN companies_v54 co ON co.id=j.company_id JOIN branches_v54 b ON b.id=j.branch_id JOIN accounts a ON a.id=l.account_id WHERE 1=1""";args=[]
        if start:q+=" AND j.date>=?";args.append(start)
        if end:q+=" AND j.date<=?";args.append(end)
        if company:q+=" AND j.company_id=?";args.append(int(company))
        if branch:q+=" AND j.branch_id=?";args.append(int(branch))
        q+=" GROUP BY co.id,b.id,a.id ORDER BY co.code,b.code,a.code";rows=c.execute(q,args).fetchall()
    else:
        q="""SELECT co.code 'الشركة',b.code 'الفرع',w.code 'المستودع',i.sku 'الصنف',i.name 'الاسم',x.qty 'الكمية'
        FROM company_inventory_v56 x JOIN companies_v54 co ON co.id=x.company_id JOIN branches_v54 b ON b.id=x.branch_id
        JOIN warehouses_v47 w ON w.id=x.warehouse_id JOIN inventory_items_v47 i ON i.id=x.item_id WHERE 1=1""";args=[]
        if company:q+=" AND x.company_id=?";args.append(int(company))
        if branch:q+=" AND x.branch_id=?";args.append(int(branch))
        q+=" ORDER BY co.code,b.code,w.code,i.sku";rows=c.execute(q,args).fetchall()
    headers=list(rows[0].keys()) if rows else []
    return headers,[list(r) for r in rows]

def csv_response_v60(headers,rows,filename):
    from flask import Response
    out=BytesIO(); out.write(b'\xef\xbb\xbf')
    text=[]
    import io
    sio=io.StringIO();w=csv.writer(sio);w.writerow(headers);w.writerows(rows);out.write(sio.getvalue().encode("utf-8"))
    return Response(out.getvalue(),mimetype="text/csv",headers={"Content-Disposition":f"attachment; filename={filename}.csv"})

@app.route("/report-center-v60")
def report_center_v60():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    code=request.args.get("code","SALES");start=request.args.get("start","");end=request.args.get("end","");company=request.args.get("company","");branch=request.args.get("branch","")
    c=con();co=c.execute("SELECT * FROM companies_v54 WHERE active=1 ORDER BY code").fetchall();br=c.execute("SELECT b.*,co.code company FROM branches_v54 b JOIN companies_v54 co ON co.id=b.company_id WHERE b.active=1").fetchall();headers,rows=report_data_v60(c,code,start,end,company,branch);c.close()
    coo="<option value=''>كل الشركات</option>"+"".join(f"<option value='{x['id']}' {'selected' if str(x['id'])==company else ''}>{x['code']} — {x['name']}</option>" for x in co);bo="<option value=''>كل الفروع</option>"+"".join(f"<option value='{x['id']}' {'selected' if str(x['id'])==branch else ''}>{x['company']}/{x['code']} — {x['name']}</option>" for x in br)
    opts="".join(f"<option value='{x}' {'selected' if x==code else ''}>{y}</option>" for x,y in [('SALES','المبيعات'),('PURCHASES','المشتريات'),('TRIAL','ميزان المراجعة'),('INVENTORY','المخزون')])
    th="".join(f"<th>{html.escape(str(x))}</th>" for x in headers);rr="".join("<tr>"+"".join(f"<td>{html.escape(str(v if v is not None else ''))}</td>" for v in r)+"</tr>" for r in rows)
    qs=f"code={code}&start={start}&end={end}&company={company}&branch={branch}"
    return page(f"""<h1>مركز التقارير الاحترافية v60</h1><form method=get class=panel><select name=code>{opts}</select><select name=company>{coo}</select><select name=branch>{bo}</select><input type=date name=start value="{start}"><input type=date name=end value="{end}"><button>عرض</button></form>
    <div class=panel><a href="/export-report-v60?{qs}&format=csv">تصدير Excel/CSV</a> | <a href="/export-report-v60?{qs}&format=pdf">تصدير PDF</a> | <a href="#" onclick="window.print();return false">طباعة</a></div>
    <table><tr>{th}</tr>{rr}</table>""")

@app.route("/export-report-v60")
def export_report_v60():
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    from flask import Response
    code=request.args.get("code","SALES");fmt=request.args.get("format","csv");start=request.args.get("start","");end=request.args.get("end","");company=request.args.get("company","");branch=request.args.get("branch","")
    c=con();headers,rows=report_data_v60(c,code,start,end,company,branch)
    c.execute("INSERT INTO report_exports_v60(username,report_code,format,filters) VALUES(?,?,?,?)",(session.get("user",""),code,fmt,str(dict(request.args))));c.commit();c.close()
    if fmt=="csv":return csv_response_v60(headers,rows,"sati_"+code.lower())
    try:
        from reportlab.platypus import SimpleDocTemplate,Table,TableStyle,Paragraph,Spacer
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4,landscape
        from reportlab.lib.styles import getSampleStyleSheet
        from reportlab.pdfbase import pdfmetrics
        from reportlab.pdfbase.cidfonts import UnicodeCIDFont
        pdfmetrics.registerFont(UnicodeCIDFont('STSong-Light'))
        buf=BytesIO();doc=SimpleDocTemplate(buf,pagesize=landscape(A4),rightMargin=24,leftMargin=24,topMargin=24,bottomMargin=24)
        st=getSampleStyleSheet();title=st["Title"];title.fontName='STSong-Light'
        data=[[str(x) for x in headers]]+[[str(v if v is not None else "") for v in r] for r in rows]
        t=Table(data,repeatRows=1);t.setStyle(TableStyle([('FONTNAME',(0,0),(-1,-1),'STSong-Light'),('FONTSIZE',(0,0),(-1,-1),8),('GRID',(0,0),(-1,-1),.25,colors.grey),('BACKGROUND',(0,0),(-1,0),colors.lightgrey),('ALIGN',(0,0),(-1,-1),'CENTER')]))
        doc.build([Paragraph("Sati ERP - "+code,title),Spacer(1,12),t]);pdf=buf.getvalue()
        return Response(pdf,mimetype="application/pdf",headers={"Content-Disposition":f"attachment; filename=sati_{code.lower()}.pdf"})
    except Exception as e:return ("تعذر إنشاء PDF: "+str(e),500)

