def generate_alerts_v61(c,username):
    rules={x["code"]:x for x in c.execute("SELECT * FROM alert_rules_v61 WHERE enabled=1").fetchall()}
    if "LOW_STOCK" in rules:
        r=rules["LOW_STOCK"]; rows=c.execute("""SELECT x.id,co.id company_id,b.id branch_id,i.sku,i.name,x.qty FROM company_inventory_v56 x JOIN companies_v54 co ON co.id=x.company_id JOIN branches_v54 b ON b.id=x.branch_id JOIN inventory_items_v47 i ON i.id=x.item_id WHERE x.qty<=?""",(r["threshold_value"],)).fetchall()
        for x in rows:c.execute("INSERT OR IGNORE INTO notifications_v61(username,company_id,branch_id,notification_type,title,message,severity,entity_type,entity_id) VALUES(?,?,?,?,?,?,?,?,?)",(username,x["company_id"],x["branch_id"],"LOW_STOCK","مخزون منخفض: "+x["sku"],f"{x['name']} — الرصيد {x['qty']}",r["severity"],"inventory",x["id"]))
    if "PENDING_APPROVAL" in rules:
        r=rules["PENDING_APPROVAL"]
        for x in c.execute("SELECT * FROM approval_requests_v57 WHERE status='PENDING'").fetchall():c.execute("INSERT OR IGNORE INTO notifications_v61(username,notification_type,title,message,severity,entity_type,entity_id) VALUES(?,?,?,?,?,?,?)",(username,"PENDING_APPROVAL","طلب اعتماد "+x["request_no"],x["module"]+" / "+x["operation"],r["severity"],"approval",x["id"]))
    if "OVERDUE_PROJECT" in rules:
        r=rules["OVERDUE_PROJECT"]
        for x in c.execute("SELECT * FROM projects_v52 WHERE status='ACTIVE' AND end_date IS NOT NULL AND end_date<date('now') AND completion_pct<100").fetchall():c.execute("INSERT OR IGNORE INTO notifications_v61(username,notification_type,title,message,severity,entity_type,entity_id) VALUES(?,?,?,?,?,?,?)",(username,"OVERDUE_PROJECT","مشروع متأخر: "+x["project_no"],f"{x['name']} — الإنجاز {x['completion_pct']:.1f}%",r["severity"],"project",x["id"]))
    if "DUE_MAINTENANCE" in rules:
        r=rules["DUE_MAINTENANCE"]
        try:
            for x in c.execute("SELECT * FROM maintenance_plans_v51 WHERE next_due_date IS NOT NULL AND next_due_date<=date('now','+'||?||' day')",(r["days_before"],)).fetchall():c.execute("INSERT OR IGNORE INTO notifications_v61(username,notification_type,title,message,severity,entity_type,entity_id) VALUES(?,?,?,?,?,?,?)",(username,"DUE_MAINTENANCE","صيانة مستحقة","موعد الصيانة: "+str(x["next_due_date"]),r["severity"],"maintenance",x["id"]))
        except: pass
    c.commit()

