DOC_DIR_V62=os.path.join(os.path.dirname(os.path.abspath(__file__)),"uploads_v62")
os.makedirs(DOC_DIR_V62,exist_ok=True)

def save_document_file_v62(f,doc_id,version):
    original=f.filename or "file"
    ext=os.path.splitext(secure_filename(original))[1].lower()
    stored=f"{doc_id}_{version}_{uuid.uuid4().hex}{ext}"
    path=os.path.join(DOC_DIR_V62,stored);f.save(path)
    h=hashlib.sha256()
    with open(path,"rb") as z:
        for chunk in iter(lambda:z.read(1024*1024),b""):h.update(chunk)
    return original,stored,path,os.path.getsize(path),h.hexdigest(),f.mimetype or "application/octet-stream"

