BACKUP_DIR_V63=os.path.join(os.path.dirname(os.path.abspath(__file__)),"backups_v63")
os.makedirs(BACKUP_DIR_V63,exist_ok=True)

def db_path_v63():
    return os.path.join(os.path.dirname(os.path.abspath(__file__)),"sati_v106.db")

def sha256_file_v63(path):
    h=hashlib.sha256()
    with open(path,"rb") as f:
        for chunk in iter(lambda:f.read(1024*1024),b""):h.update(chunk)
    return h.hexdigest()

def integrity_file_v63(path):
    try:
        x=sqlite3.connect(path);r=x.execute("PRAGMA integrity_check").fetchone()[0];x.close()
        return "OK" if str(r).lower()=="ok" else str(r)
    except Exception as e:return "ERROR: "+str(e)

def make_backup_v63(kind="MANUAL",user="system",notes=""):
    source=db_path_v63()
    stamp=datetime.datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    name=f"sati_erp_v63_{kind.lower()}_{stamp}.db";dest=os.path.join(BACKUP_DIR_V63,name)
    src=sqlite3.connect(source);dst=sqlite3.connect(dest)
    with dst:src.backup(dst)
    dst.close();src.close()
    size=os.path.getsize(dest);sha=sha256_file_v63(dest);integ=integrity_file_v63(dest)
    c=con();c.execute("INSERT INTO backup_history_v63(backup_name,backup_path,backup_type,created_by,file_size,sha256,integrity_status,notes) VALUES(?,?,?,?,?,?,?,?)",(name,dest,kind,user,size,sha,integ,notes));bid=c.execute("SELECT last_insert_rowid()").fetchone()[0];c.commit();c.close()
    return bid,name,dest

def prune_backups_v63():
    c=con();st=c.execute("SELECT keep_count FROM backup_settings_v63 WHERE id=1").fetchone();keep=max(1,int(st["keep_count"]))
    rows=c.execute("SELECT * FROM backup_history_v63 ORDER BY id DESC").fetchall()
    for x in rows[keep:]:
        try:
            if os.path.exists(x["backup_path"]):os.remove(x["backup_path"])
            c.execute("DELETE FROM backup_history_v63 WHERE id=?",(x["id"],))
        except:pass
    c.commit();c.close()

