@app.route("/restore-backup-v63/<int:id>",methods=["GET","POST"])
def restore_backup_v63(id):
    if session.get("role")!="admin":return ("غير مصرح",403)
    c=con();x=c.execute("SELECT * FROM backup_history_v63 WHERE id=?",(id,)).fetchone();c.close()
    if not x:return ("النسخة غير موجودة",404)
    if request.method=="GET":
        return page(f"""<h1>استعادة نسخة احتياطية</h1><div class=panel><strong>تحذير:</strong> ستتم إعادة قاعدة البيانات إلى النسخة: {x['backup_name']}. سيتم إنشاء نسخة أمان من الحالة الحالية أولاً.</div><form method=post><input name=confirm required placeholder="اكتب RESTORE للتأكيد"><button>تنفيذ الاستعادة</button></form>""")
    if request.form.get("confirm")!="RESTORE":flash("لم يتم التأكيد");return redirect(f"/restore-backup-v63/{id}")
    try:
        if integrity_file_v63(x["backup_path"])!="OK":raise ValueError("فشل فحص سلامة النسخة")
        _,pre_name,pre_path=make_backup_v63("PRE_RESTORE",session.get("user",""),"نسخة تلقائية قبل الاستعادة")
        source=sqlite3.connect(x["backup_path"]);target=sqlite3.connect(db_path_v63())
        with target:source.backup(target)
        target.close();source.close()
        c=con();c.execute("INSERT INTO restore_history_v63(backup_id,restored_by,pre_restore_backup,status,details) VALUES(?,?,?,?,?)",(id,session.get("user",""),pre_name,"SUCCESS","تمت الاستعادة بعد فحص integrity_check"));c.commit();c.close()
        flash("تمت الاستعادة بنجاح. يفضل إعادة تشغيل التطبيق.");return redirect("/backup-center-v63")
    except Exception as e:
        try:
            c=con();c.execute("INSERT INTO restore_history_v63(backup_id,restored_by,status,details) VALUES(?,?,?,?)",(id,session.get("user",""),"FAILED",str(e)));c.commit();c.close()
        except:pass
        flash("فشلت الاستعادة: "+str(e));return redirect("/backup-center-v63")

@app.route("/database-health-v63")
def database_health_v63():
    if session.get("role")!="admin":return ("غير مصرح",403)
    c=con();integrity=c.execute("PRAGMA integrity_check").fetchone()[0];fk=c.execute("PRAGMA foreign_key_check").fetchall();pages=c.execute("PRAGMA page_count").fetchone()[0];page_size=c.execute("PRAGMA page_size").fetchone()[0];tables=c.execute("SELECT count(*) x FROM sqlite_master WHERE type='table'").fetchone()["x"];restores=c.execute("SELECT * FROM restore_history_v63 ORDER BY id DESC LIMIT 50").fetchall();c.close()
    rr="".join(f"<tr><td>{x['restored_at']}</td><td>{x['restored_by']}</td><td>{x['status']}</td><td>{x['pre_restore_backup'] or ''}</td><td>{x['details']}</td></tr>" for x in restores)
    return page(f"""<h1>سلامة قاعدة البيانات v63</h1><table><tr><th>Integrity Check</th><td>{integrity}</td></tr><tr><th>مخالفات Foreign Keys</th><td>{len(fk)}</td></tr><tr><th>عدد الجداول</th><td>{tables}</td></tr><tr><th>حجم صفحات SQLite</th><td>{pages*page_size} bytes</td></tr></table><h2>سجل الاستعادة</h2><table><tr><th>الوقت</th><th>المستخدم</th><th>الحالة</th><th>نسخة ما قبل الاستعادة</th><th>التفاصيل</th></tr>{rr}</table>""")

def scheduled_backup_tick_v63():
    # تستدعى من scheduler خارجي أو cron؛ لا يتم تشغيل thread خفي داخل Flask.
    c=con();st=c.execute("SELECT * FROM backup_settings_v63 WHERE id=1").fetchone();c.close()
    if not st or not st["enabled"]:return False
    now=datetime.datetime.now();last=None
    if st["last_run"]:
        try:last=datetime.datetime.fromisoformat(st["last_run"])
        except:last=None
    due=not last or (st["frequency"]=="DAILY" and now-last>=datetime.timedelta(days=1)) or (st["frequency"]=="WEEKLY" and now-last>=datetime.timedelta(days=7)) or (st["frequency"]=="MONTHLY" and now-last>=datetime.timedelta(days=30))
    if due:
        make_backup_v63("AUTO","scheduler","نسخة مجدولة");prune_backups_v63()
        c=con();c.execute("UPDATE backup_settings_v63 SET last_run=? WHERE id=1",(now.isoformat(timespec="seconds"),));c.commit();c.close();return True
    return False


def api_hash_v64(key):
    return hashlib.sha256(key.encode("utf-8")).hexdigest()

def api_auth_v64(permission=None):
    def deco(fn):
        @wraps(fn)
        def inner(*args,**kwargs):
            started=time.time()
            key=request.headers.get("X-API-Key","")
            prefix=key[:10] if key else ""
            c=con();client=None;status=401
            try:
                if key:
                    client=c.execute("""SELECT * FROM api_clients_v64 WHERE api_key_hash=? AND active=1
                    AND (expires_at IS NULL OR expires_at='' OR expires_at>CURRENT_TIMESTAMP)""",(api_hash_v64(key),)).fetchone()
                if not client:
                    status=401
                    return {"error":"unauthorized","message":"API key غير صالح"},401
                if permission:
                    p=c.execute("SELECT allowed FROM api_client_permissions_v64 WHERE client_id=? AND permission_code=?",(client["id"],permission)).fetchone()
                    if not p or not p["allowed"]:
                        status=403
                        return {"error":"forbidden","message":"لا توجد صلاحية API"},403
                # basic hourly rate limit
                lim=c.execute("SELECT requests_per_hour FROM api_rate_limits_v64 WHERE client_id=?",(client["id"],)).fetchone()
                limit=int(lim["requests_per_hour"]) if lim else 1000
                used=c.execute("SELECT count(*) n FROM api_request_log_v64 WHERE client_id=? AND request_time>=datetime('now','-1 hour')",(client["id"],)).fetchone()["n"]
                if used>=limit:
                    status=429
                    return {"error":"rate_limit","message":"تم تجاوز حد الطلبات"},429
                request.api_client_v64=dict(client)
                c.execute("UPDATE api_clients_v64 SET last_used_at=CURRENT_TIMESTAMP WHERE id=?",(client["id"],));c.commit()
                result=fn(*args,**kwargs)
                status=result[1] if isinstance(result,tuple) and len(result)>1 and isinstance(result[1],int) else 200
                return result
            finally:
                try:
                    cid=client["id"] if client else None
                    c.execute("INSERT INTO api_request_log_v64(client_id,key_prefix,method,path,status_code,duration_ms,ip_address,user_agent) VALUES(?,?,?,?,?,?,?,?)",(cid,prefix,request.method,request.path,status,int((time.time()-started)*1000),request.remote_addr or "",request.headers.get("User-Agent","")));c.commit();c.close()
                except: pass
        return inner
    return deco

def api_scope_v64(alias=""):
    cl=request.api_client_v64;pre=(alias+".") if alias else ""
    cond=[];args=[]
    if cl.get("company_id"):cond.append(pre+"company_id=?");args.append(cl["company_id"])
    if cl.get("branch_id"):cond.append(pre+"branch_id=?");args.append(cl["branch_id"])
    return cond,args

