    if session.get("role")!="admin":return ("غير مصرح",403)
    c=con();new_key=""
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="new":
                raw="sati_"+secrets.token_urlsafe(32);prefix=raw[:10]
                cur=c.execute("INSERT INTO api_clients_v64(name,api_key_hash,key_prefix,company_id,branch_id,created_by,expires_at) VALUES(?,?,?,?,?,?,?)",(request.form["name"],api_hash_v64(raw),prefix,int(request.form["company"]) if request.form.get("company") else None,int(request.form["branch"]) if request.form.get("branch") else None,session.get("user",""),request.form.get("expires") or None))
                cid=cur.lastrowid
                for p in request.form.getlist("permissions"):c.execute("INSERT OR IGNORE INTO api_client_permissions_v64(client_id,permission_code,allowed) VALUES(?,?,1)",(cid,p))
                c.execute("INSERT OR REPLACE INTO api_rate_limits_v64(client_id,requests_per_hour) VALUES(?,?)",(cid,int(request.form.get("rate") or 1000)));c.commit();new_key=raw
            elif a=="toggle":
                c.execute("UPDATE api_clients_v64 SET active=CASE active WHEN 1 THEN 0 ELSE 1 END WHERE id=?",(int(request.form["id"]),));c.commit()
        except Exception as e:c.rollback();flash(str(e))
    clients=c.execute("""SELECT a.*,coalesce(co.code,'') company,coalesce(b.code,'') branch,coalesce(r.requests_per_hour,1000) rate
    FROM api_clients_v64 a LEFT JOIN companies_v54 co ON co.id=a.company_id LEFT JOIN branches_v54 b ON b.id=a.branch_id LEFT JOIN api_rate_limits_v64 r ON r.client_id=a.id ORDER BY a.id DESC""").fetchall()
    co=c.execute("SELECT * FROM companies_v54 WHERE active=1").fetchall();br=c.execute("SELECT b.*,co.code company FROM branches_v54 b JOIN companies_v54 co ON co.id=b.company_id WHERE b.active=1").fetchall();c.close()
    coo="<option value=''>كل الشركات</option>"+"".join(f"<option value='{x['id']}'>{x['code']} — {x['name']}</option>" for x in co);bo="<option value=''>كل الفروع</option>"+"".join(f"<option value='{x['id']}'>{x['company']}/{x['code']} — {x['name']}</option>" for x in br)
    perms=['customers.read','suppliers.read','inventory.read','sales.read','sales.create','purchases.read','purchases.create','accounting.read'];checks=" ".join(f"<label><input type=checkbox name=permissions value='{p}'>{p}</label>" for p in perms)
    rr="".join(f"<tr><td>{x['name']}</td><td>{x['key_prefix']}…</td><td>{x['company']}</td><td>{x['branch']}</td><td>{x['rate']}/ساعة</td><td>{'نشط' if x['active'] else 'معطل'}</td><td>{x['last_used_at'] or ''}</td><td><form method=post><input type=hidden name=action value=toggle><input type=hidden name=id value='{x['id']}'><button>تفعيل/تعطيل</button></form></td></tr>" for x in clients)
    keybox=f"<div class=panel><strong>API Key الجديدة — انسخها الآن، لن تعرض مرة أخرى:</strong><br><code>{html.escape(new_key)}</code></div>" if new_key else ""
    return page(f"""<h1>إدارة REST API v64</h1>{keybox}<form method=post class=panel><input type=hidden name=action value=new><input name=name required placeholder="اسم التطبيق/التكامل"><select name=company>{coo}</select><select name=branch>{bo}</select><input type=date name=expires><input name=rate type=number min=10 value=1000 placeholder="طلبات/ساعة"><div>{checks}</div><button>إنشاء API Key</button></form><table><tr><th>العميل</th><th>المفتاح</th><th>الشركة</th><th>الفرع</th><th>الحد</th><th>الحالة</th><th>آخر استخدام</th><th></th></tr>{rr}</table><div class=panel>استخدم الهيدر: <code>X-API-Key: YOUR_KEY</code><br>Endpoints: /api/v1/health, /customers, /suppliers, /inventory, /sales, /purchases, /trial-balance</div>""")

