@app.route("/pos-return-v65/<int:id>",methods=["GET","POST"])
def pos_return_v65(id):
    if not session.get("user"):return redirect("/login")
    c=con();u=session.get("user");sale=c.execute("SELECT * FROM pos_sales_v65 WHERE id=?",(id,)).fetchone()
    if not sale:c.close();return ("غير موجود",404)
    sh=pos_open_shift_v65(c,u)
    if not sh:c.close();return page("<h1>مرتجع POS</h1><div class=panel>يجب فتح وردية لتنفيذ المرتجع.</div>")
    lines=c.execute("SELECT * FROM pos_sale_lines_v65 WHERE sale_id=?",(id,)).fetchall()
    if request.method=="POST":
        try:
            total=0;chosen=[]
            for l in lines:
                qty=float(request.form.get(f"q{l['id']}") or 0)
                if qty<0 or qty>float(l["qty"]):raise ValueError("كمية المرتجع غير صحيحة")
                if qty:
                    amount=round(float(l["line_total"])*(qty/float(l["qty"])),2);total+=amount;chosen.append((l,qty,amount))
            if not chosen:raise ValueError("اختر كمية للمرتجع")
            no="RET-"+datetime.datetime.now().strftime("%Y%m%d%H%M%S%f")
            cur=c.execute("INSERT INTO pos_returns_v65(return_no,original_sale_id,shift_id,total,reason,created_by) VALUES(?,?,?,?,?,?)",(no,id,sh["id"],total,request.form.get("reason",""),u));rid=cur.lastrowid
            for l,qty,amount in chosen:
                c.execute("INSERT INTO pos_return_lines_v65(return_id,sale_line_id,item_id,qty,amount) VALUES(?,?,?,?,?)",(rid,l["id"],l["item_id"],qty,amount))
                c.execute("UPDATE company_inventory_v56 SET qty=qty+? WHERE company_id=? AND branch_id=? AND warehouse_id=? AND item_id=?",(qty,sale["company_id"],sale["branch_id"],sale["warehouse_id"],l["item_id"]))
            pos_post_return_v66(c,rid)
            c.commit();flash(f"تم المرتجع بقيمة {total:.2f}");c.close();return redirect("/pos-v65")
        except Exception as e:c.rollback();flash(str(e));c.close();return redirect(f"/pos-return-v65/{id}")
    rr="".join(f"<tr><td>{l['sku']}</td><td>{html.escape(l['description'])}</td><td>{l['qty']:.3f}</td><td><input name='q{l['id']}' type=number min=0 max='{l['qty']}' step=.001 value=0></td><td>{l['line_total']:.2f}</td></tr>" for l in lines);c.close()
    return page(f"""<h1>مرتجع الفاتورة {sale['receipt_no']}</h1><form method=post class=panel><table><tr><th>SKU</th><th>الصنف</th><th>المباع</th><th>كمية المرتجع</th><th>قيمة السطر</th></tr>{rr}</table><input name=reason required placeholder="سبب المرتجع"><button>تنفيذ المرتجع وإعادة الكمية للمخزون</button></form>""")


def pos_accounts_v66(c):
    return c.execute("SELECT * FROM pos_account_settings_v66 WHERE id=1").fetchone()

def pos_post_journal_v66(c,source_type,source_id,company_id,branch_id,doc_date,description,entries):
    old=c.execute("SELECT journal_id FROM pos_accounting_links_v66 WHERE source_type=? AND source_id=?",(source_type,source_id)).fetchone()
    if old:return old["journal_id"]
    # company_journals_v55 / company_journal_lines_v55 are the multi-company GL introduced earlier.
    jno="POSJ-"+datetime.datetime.now().strftime("%Y%m%d%H%M%S%f")
    cur=c.execute("""INSERT INTO company_journals_v55(company_id,branch_id,journal_no,date,description,status)
    VALUES(?,?,?,?,?,'POSTED')""",(company_id,branch_id,jno,doc_date,description))
    jid=cur.lastrowid
    debit=sum(float(x[1] or 0) for x in entries);credit=sum(float(x[2] or 0) for x in entries)
    if round(debit,2)!=round(credit,2):raise ValueError("القيد غير متوازن")
    for account_id,dr,cr,memo in entries:
        if not account_id:raise ValueError("إعدادات حسابات POS غير مكتملة")
        if round(float(dr or 0),2)==0 and round(float(cr or 0),2)==0:continue
        c.execute("INSERT INTO company_journal_lines_v55(journal_id,account_id,debit,credit,description) VALUES(?,?,?,?,?)",(jid,account_id,round(dr,2),round(cr,2),memo))
    c.execute("INSERT INTO pos_accounting_links_v66(source_type,source_id,journal_id) VALUES(?,?,?)",(source_type,source_id,jid))
    return jid

def pos_post_sale_v66(c,sale_id):
    s=c.execute("SELECT * FROM pos_sales_v65 WHERE id=?",(sale_id,)).fetchone()
    if not s:raise ValueError("فاتورة POS غير موجودة")
    a=pos_accounts_v66(c);entries=[]
    for p in c.execute("SELECT payment_method,sum(amount) amount FROM pos_payments_v65 WHERE sale_id=? GROUP BY payment_method",(sale_id,)).fetchall():
        aid=a["cash_account_id"] if p["payment_method"]=="CASH" else a["card_account_id"] if p["payment_method"]=="CARD" else a["bank_account_id"]
        entries.append((aid,p["amount"],0,"تحصيل "+p["payment_method"]))
    net_sales=float(s["subtotal"])-float(s["discount"])
    entries.append((a["sales_account_id"],0,net_sales,"مبيعات POS"))
    if float(s["vat"]):entries.append((a["vat_account_id"],0,s["vat"],"ضريبة مخرجات POS"))
    return pos_post_journal_v66(c,"SALE",sale_id,s["company_id"],s["branch_id"],str(s["sale_time"])[:10],"فاتورة POS "+s["receipt_no"],entries)

def pos_post_return_v66(c,return_id):
    r=c.execute("""SELECT r.*,s.company_id,s.branch_id FROM pos_returns_v65 r JOIN pos_sales_v65 s ON s.id=r.original_sale_id WHERE r.id=?""",(return_id,)).fetchone()
    if not r:raise ValueError("المرتجع غير موجود")
    a=pos_accounts_v66(c);total=float(r["total"]);net=round(total/1.15,2);vat=round(total-net,2)
    entries=[(a["returns_account_id"],net,0,"مرتجع مبيعات POS"),(a["vat_account_id"],vat,0,"عكس ضريبة المخرجات"),(a["cash_account_id"],0,total,"استرداد مرتجع POS")]
    return pos_post_journal_v66(c,"RETURN",return_id,r["company_id"],r["branch_id"],str(r["return_time"])[:10],"مرتجع POS "+r["return_no"],entries)

