@app.route("/pos-settle-v66/<int:shift_id>",methods=["GET","POST"])
def pos_settle_v66(shift_id):
    if session.get("role") not in ("admin","accountant"):return ("غير مصرح",403)
    c=con();sh=c.execute("""SELECT s.*,t.company_id,t.branch_id FROM pos_shifts_v65 s JOIN pos_terminals_v65 t ON t.id=s.terminal_id WHERE s.id=?""",(shift_id,)).fetchone()
    if not sh:c.close();return ("غير موجود",404)
    cash=float(c.execute("""SELECT coalesce(sum(p.amount),0) x FROM pos_payments_v65 p JOIN pos_sales_v65 s ON s.id=p.sale_id WHERE s.shift_id=? AND p.payment_method='CASH'""",(shift_id,)).fetchone()["x"])
    expected=float(sh["opening_cash"])+cash
    if request.method=="POST":
        try:
            actual=float(request.form["actual"]);diff=round(actual-expected,2);a=pos_accounts_v66(c);jid=None
            if diff:
                if diff>0:entries=[(a["cash_account_id"],diff,0,"زيادة صندوق POS"),(a["cash_difference_account_id"],0,diff,"فرق صندوق")]
                else:entries=[(a["cash_difference_account_id"],-diff,0,"عجز صندوق"),(a["cash_account_id"],0,-diff,"عجز صندوق POS")]
                jid=pos_post_journal_v66(c,"SHIFT_DIFF",shift_id,sh["company_id"],sh["branch_id"],datetime.date.today().isoformat(),"تسوية وردية "+sh["shift_no"],entries)
            c.execute("INSERT INTO pos_shift_settlements_v66(shift_id,expected_cash,actual_cash,difference,settled_by,journal_id,notes) VALUES(?,?,?,?,?,?,?)",(shift_id,expected,actual,diff,session.get("user",""),jid,request.form.get("notes","")))
            c.commit();flash("تمت تسوية الوردية")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/pos-shifts-v65")
    c.close();return page(f"""<h1>تسوية الوردية {sh['shift_no']}</h1><div class=panel>رصيد الافتتاح: {sh['opening_cash']:.2f}<br>المبيعات النقدية: {cash:.2f}<br><strong>النقدية المتوقعة: {expected:.2f}</strong></div><form method=post class=panel><input name=actual type=number step=.01 required placeholder="النقدية الفعلية"><input name=notes placeholder="ملاحظات التسوية"><button>تسوية وترحيل الفرق</button></form>""")


def pos_effective_price_v67(c,item_id,company_id,branch_id,terminal_id=None):
    today=datetime.date.today().isoformat()
    pl=None
    if terminal_id:
        st=c.execute("SELECT price_list_id FROM pos_terminal_settings_v67 WHERE terminal_id=?",(terminal_id,)).fetchone()
        if st and st["price_list_id"]:pl=st["price_list_id"]
    if not pl:
        x=c.execute("""SELECT id FROM pos_price_lists_v66 WHERE active=1 AND (company_id IS NULL OR company_id=?)
        AND (branch_id IS NULL OR branch_id=?) AND (start_date IS NULL OR start_date<=?) AND (end_date IS NULL OR end_date>=?)
        ORDER BY CASE WHEN branch_id IS NOT NULL THEN 0 WHEN company_id IS NOT NULL THEN 1 ELSE 2 END,id DESC LIMIT 1""",(company_id,branch_id,today,today)).fetchone()
        pl=x["id"] if x else None
    if pl:
        x=c.execute("SELECT price FROM pos_price_list_items_v66 WHERE price_list_id=? AND item_id=?",(pl,item_id)).fetchone()
        if x:return float(x["price"])
    # fallback to a common price-like column when present
    cols=[x["name"] for x in c.execute("PRAGMA table_info(inventory_items_v47)").fetchall()]
    for col in ["sale_price","price","selling_price"]:
        if col in cols:
            x=c.execute(f"SELECT {col} p FROM inventory_items_v47 WHERE id=?",(item_id,)).fetchone()
            if x and x["p"] is not None:return float(x["p"])
    return 0.0

def pos_promotion_v67(c,company_id,branch_id,subtotal):
    today=datetime.date.today().isoformat()
    rows=c.execute("""SELECT * FROM pos_promotions_v66 WHERE active=1
    AND (company_id IS NULL OR company_id=?) AND (branch_id IS NULL OR branch_id=?)
    AND (start_date IS NULL OR start_date<=?) AND (end_date IS NULL OR end_date>=?)
    AND min_total<=? ORDER BY discount_value DESC,id DESC""",(company_id,branch_id,today,today,subtotal)).fetchall()
    if not rows:return None,0
    p=rows[0]
    d=subtotal*float(p["discount_value"])/100 if p["discount_type"]=="PERCENT" else float(p["discount_value"])
    return dict(p),min(subtotal,round(d,2))

@app.route("/api/pos-v67/item")
def api_pos_item_v67():
    if not session.get("user"):return {"error":"login"},401
    c=con();sh=pos_open_shift_v65(c,session.get("user"))
    if not sh:c.close();return {"error":"no_open_shift"},400
    q=(request.args.get("q") or "").strip()
    item=c.execute("SELECT * FROM inventory_items_v47 WHERE sku=?",(q,)).fetchone()
    if not item:
        item=c.execute("SELECT * FROM inventory_items_v47 WHERE name LIKE ? ORDER BY name LIMIT 1",("%"+q+"%",)).fetchone()
    if not item:c.close();return {"error":"not_found"},404
    stock=c.execute("SELECT qty FROM company_inventory_v56 WHERE company_id=? AND branch_id=? AND warehouse_id=? AND item_id=?",(sh["company_id"],sh["branch_id"],sh["warehouse_id"],item["id"])).fetchone()
    price=pos_effective_price_v67(c,item["id"],sh["company_id"],sh["branch_id"],sh["terminal_id"]);c.close()
    return {"id":item["id"],"sku":item["sku"],"name":item["name"],"price":price,"stock":float(stock["qty"]) if stock else 0}

@app.route("/api/pos-v67/search")
def api_pos_search_v67():
    if not session.get("user"):return {"error":"login"},401
    c=con();sh=pos_open_shift_v65(c,session.get("user"))
    if not sh:c.close();return {"error":"no_open_shift"},400
    q=(request.args.get("q") or "").strip()
    rows=c.execute("""SELECT i.id,i.sku,i.name,coalesce(x.qty,0) stock FROM inventory_items_v47 i
    LEFT JOIN company_inventory_v56 x ON x.item_id=i.id AND x.company_id=? AND x.branch_id=? AND x.warehouse_id=?
    WHERE i.sku LIKE ? OR i.name LIKE ? ORDER BY i.name LIMIT 30""",(sh["company_id"],sh["branch_id"],sh["warehouse_id"],"%"+q+"%","%"+q+"%")).fetchall()
    out=[]
    for x in rows:
        out.append({"id":x["id"],"sku":x["sku"],"name":x["name"],"stock":x["stock"],"price":pos_effective_price_v67(c,x["id"],sh["company_id"],sh["branch_id"],sh["terminal_id"])})
    c.close();return {"data":out}

