def pos_user_role_v68():
    return session.get("role","")

def pos_secure_quote_v68(c,sh,cart):
    sec=c.execute("SELECT * FROM pos_security_settings_v68 WHERE id=1").fetchone()
    role=pos_user_role_v68();is_manager=role in ("admin","manager")
    lines=[];gross=0;manual_discount=0
    for row in cart:
        sku=str(row.get("sku","")).strip()
        item=c.execute("SELECT * FROM inventory_items_v47 WHERE sku=?",(sku,)).fetchone()
        if not item:raise ValueError("الصنف غير موجود: "+sku)
        qty=float(row.get("qty") or 0)
        if qty<=0:raise ValueError("كمية غير صحيحة للصنف "+sku)
        stock=c.execute("SELECT qty FROM company_inventory_v56 WHERE company_id=? AND branch_id=? AND warehouse_id=? AND item_id=?",(sh["company_id"],sh["branch_id"],sh["warehouse_id"],item["id"])).fetchone()
        if not stock or float(stock["qty"])<qty:raise ValueError("الرصيد غير كافٍ: "+sku)
        sys_price=round(pos_effective_price_v67(c,item["id"],sh["company_id"],sh["branch_id"],sh["terminal_id"]),2)
        req_price=float(row.get("price",sys_price) or 0)
        price=sys_price
        if round(req_price,2)!=round(sys_price,2):
            if not (is_manager or sec["allow_cashier_price_override"]):raise ValueError("غير مسموح بتغيير سعر "+sku)
            price=round(req_price,2)
            c.execute("""INSERT INTO pos_override_audit_v68(username,shift_id,item_id,sku,override_type,system_value,requested_value,approved_value,reason,ip_address)
            VALUES(?,?,?,?,?,?,?,?,?,?)""",(session.get("user",""),sh["id"],item["id"],sku,"PRICE",sys_price,req_price,price,row.get("reason",""),request.remote_addr or ""))
        requested_discount=max(0,float(row.get("discount") or 0))
        allowed_discount=requested_discount
        if requested_discount:
            pct=(requested_discount/(qty*price)*100) if qty*price else 0
            if not is_manager:
                if not sec["allow_cashier_discount_override"]:raise ValueError("غير مسموح بخصم يدوي للصنف "+sku)
                if pct>float(sec["max_cashier_discount_percent"] or 0):raise ValueError("الخصم يتجاوز الحد المسموح للصنف "+sku)
            c.execute("""INSERT INTO pos_override_audit_v68(username,shift_id,item_id,sku,override_type,system_value,requested_value,approved_value,reason,ip_address)
            VALUES(?,?,?,?,?,?,?,?,?,?)""",(session.get("user",""),sh["id"],item["id"],sku,"DISCOUNT",0,requested_discount,allowed_discount,row.get("reason",""),request.remote_addr or ""))
        base=round(qty*price,2);net=max(0,round(base-allowed_discount,2))
        gross+=base;manual_discount+=allowed_discount
        lines.append({"item":item,"sku":sku,"qty":qty,"price":price,"system_price":sys_price,"manual_discount":allowed_discount,"net_before_promo":net})
    promo, promo_discount=pos_promotion_v67(c,sh["company_id"],sh["branch_id"],max(0,gross-manual_discount))
    remaining=promo_discount
    eligible=sum(x["net_before_promo"] for x in lines)
    for i,x in enumerate(lines):
        share=round(promo_discount*(x["net_before_promo"]/eligible),2) if eligible and i<len(lines)-1 else round(remaining,2)
        share=min(share,x["net_before_promo"]);remaining=round(remaining-share,2)
        x["promo_discount"]=share;x["discount"]=round(x["manual_discount"]+share,2)
        net=round(x["net_before_promo"]-share,2);x["vat"]=round(net*.15,2);x["total"]=round(net+x["vat"],2)
    return {"lines":lines,"subtotal":round(gross,2),"manual_discount":round(manual_discount,2),"promotion":promo,"promotion_discount":round(promo_discount,2),"discount":round(manual_discount+promo_discount,2),"vat":round(sum(x["vat"] for x in lines),2),"total":round(sum(x["total"] for x in lines),2)}

@app.route("/api/pos-v68/quote",methods=["POST"])
def api_pos_quote_v68():
    if not session.get("user"):return {"error":"login"},401
    c=con();sh=pos_open_shift_v65(c,session.get("user"))
    if not sh:c.close();return {"error":"لا توجد وردية مفتوحة"},400
    try:
        q=pos_secure_quote_v68(c,sh,(request.get_json(silent=True) or {}).get("cart",[]));c.rollback();c.close()
        return {"subtotal":q["subtotal"],"discount":q["discount"],"promotion_discount":q["promotion_discount"],"promotion":q["promotion"],"vat":q["vat"],"total":q["total"],"lines":[{"sku":x["sku"],"price":x["price"],"discount":x["discount"],"vat":x["vat"],"total":x["total"]} for x in q["lines"]]}
    except Exception as e:c.rollback();c.close();return {"error":str(e)},400

@app.route("/pos-secure-v68",methods=["GET","POST"])
def pos_secure_v68():
    if not session.get("user"):return redirect("/login")
    c=con();u=session.get("user");sh=pos_open_shift_v65(c,u)
    if not sh:c.close();return page("<h1>POS الآمن v68</h1><div class=panel>افتح وردية أولاً.</div>")
    if request.method=="POST":
        try:
            cart=json.loads(request.form.get("cart_json") or "[]");q=pos_secure_quote_v68(c,sh,cart)
            cash=float(request.form.get("cash") or 0);card=float(request.form.get("card") or 0);transfer=float(request.form.get("transfer") or 0)
            if round(cash+card+transfer,2)!=q["total"]:raise ValueError(f"إجمالي الدفع يجب أن يساوي {q['total']:.2f}")
            receipt="POS-"+datetime.datetime.now().strftime("%Y%m%d%H%M%S%f")
            cur=c.execute("""INSERT INTO pos_sales_v65(receipt_no,shift_id,company_id,branch_id,warehouse_id,customer_id,subtotal,discount,vat,total,created_by,reference)
            VALUES(?,?,?,?,?,?,?,?,?,?,?,?)""",(receipt,sh["id"],sh["company_id"],sh["branch_id"],sh["warehouse_id"],int(request.form["customer"]) if request.form.get("customer") else None,q["subtotal"],q["discount"],q["vat"],q["total"],u,"POS-V68-SECURE"))
            sid=cur.lastrowid
            for x in q["lines"]:
                c.execute("""INSERT INTO pos_sale_lines_v65(sale_id,item_id,sku,description,qty,unit_price,discount,vat_rate,line_subtotal,line_vat,line_total)
                VALUES(?,?,?,?,?,?,?,?,?,?,?)""",(sid,x["item"]["id"],x["sku"],x["item"]["name"],x["qty"],x["price"],x["discount"],15,round(x["qty"]*x["price"]-x["discount"],2),x["vat"],x["total"]))
                c.execute("UPDATE company_inventory_v56 SET qty=qty-? WHERE company_id=? AND branch_id=? AND warehouse_id=? AND item_id=?",(x["qty"],sh["company_id"],sh["branch_id"],sh["warehouse_id"],x["item"]["id"]))
            for method,amount in [("CASH",cash),("CARD",card),("TRANSFER",transfer)]:
                if amount>0:c.execute("INSERT INTO pos_payments_v65(sale_id,payment_method,amount) VALUES(?,?,?)",(sid,method,amount))
            c.execute("INSERT INTO pos_pricing_snapshot_v68(sale_id,promotion_id,promotion_discount,pricing_json) VALUES(?,?,?,?)",(sid,q["promotion"]["id"] if q["promotion"] else None,q["promotion_discount"],json.dumps({"subtotal":q["subtotal"],"discount":q["discount"],"vat":q["vat"],"total":q["total"],"lines":[{"sku":x["sku"],"system_price":x["system_price"],"price":x["price"],"manual_discount":x["manual_discount"],"promo_discount":x["promo_discount"]} for x in q["lines"]]},ensure_ascii=False)))
            pos_post_sale_v66(c,sid);c.commit();c.close();return redirect(f"/pos-receipt-v65/{sid}")
        except Exception as e:c.rollback();flash(str(e));c.close();return redirect("/pos-secure-v68")
    customers=c.execute("SELECT * FROM company_customers_v55 WHERE company_id=? AND branch_id=? AND active=1 ORDER BY name",(sh["company_id"],sh["branch_id"])).fetchall();c.close()
    cu="<option value=''>عميل نقدي</option>"+"".join(f"<option value='{x['id']}'>{x['customer_code']} — {x['name']}</option>" for x in customers)
    return page(f"""<style>.v68grid{{display:grid;grid-template-columns:2fr 1fr;gap:12px}}.big{{font-size:19px;padding:12px}}#cart68 input{{width:90px}}@media(max-width:800px){{.v68grid{{grid-template-columns:1fr}}}}</style>
    <h1>POS الآمن v68</h1><div class=v68grid><div><div class=panel><input id=scan68 class=big autofocus placeholder="باركود / SKU"><input id=search68 class=big placeholder="بحث عن صنف"><div id=res68></div></div>
    <form method=post id=form68><select name=customer class=big>{cu}</select><input type=hidden name=cart_json id=cartjson68><table id=cart68><thead><tr><th>الصنف</th><th>كمية</th><th>سعر</th><th>خصم</th><th>إجمالي</th><th></th></tr></thead><tbody></tbody></table><div class=panel><input name=cash id=cash68 type=number step=.01 value=0 placeholder="نقدي"><input name=card type=number step=.01 value=0 placeholder="بطاقة"><input name=transfer type=number step=.01 value=0 placeholder="تحويل"><button class=big>إتمام البيع الآمن</button></div></form></div>
    <div class=panel><div>قبل الخصم: <b id=sub68>0.00</b></div><div>العرض: <b id=promo68>—</b></div><div>الخصم: <b id=disc68>0.00</b></div><div>VAT: <b id=vat68>0.00</b></div><h2>الإجمالي: <span id=total68>0.00</span></h2><button type=button onclick="cash68.value=total68.textContent">نقدي كامل</button></div></div>
    <script>
    const b68=document.querySelector('#cart68 tbody');function cart68(){{return [...b68.rows].map(r=>({{sku:r.dataset.sku,qty:r.querySelector('.q').value,price:r.querySelector('.p').value,discount:r.querySelector('.d').value}}))}}
    async function quote68(){{let cart=cart68();cartjson68.value=JSON.stringify(cart);if(!cart.length){{sub68.textContent=disc68.textContent=vat68.textContent=total68.textContent='0.00';return}}let r=await fetch('/api/pos-v68/quote',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{cart}})}});let x=await r.json();if(!r.ok){{total68.textContent='خطأ';return}}sub68.textContent=x.subtotal.toFixed(2);disc68.textContent=x.discount.toFixed(2);vat68.textContent=x.vat.toFixed(2);total68.textContent=x.total.toFixed(2);promo68.textContent=x.promotion?x.promotion.name:'—';x.lines.forEach((l,i)=>{{if(b68.rows[i])b68.rows[i].querySelector('.tot').textContent=l.total.toFixed(2)}})}}
    async function add68(q){{let r=await fetch('/api/pos-v67/item?q='+encodeURIComponent(q)),x=await r.json();if(!r.ok)return alert('الصنف غير موجود');let old=[...b68.rows].find(z=>z.dataset.sku===x.sku);if(old)old.querySelector('.q').value=+old.querySelector('.q').value+1;else{{let tr=document.createElement('tr');tr.dataset.sku=x.sku;tr.innerHTML=`<td>${{x.sku}}<br>${{x.name}}</td><td><input class=q type=number step=.001 min=.001 max="${{x.stock}}" value=1></td><td><input class=p type=number step=.01 value="${{x.price.toFixed(2)}}"></td><td><input class=d type=number step=.01 value=0></td><td class=tot>0.00</td><td><button type=button onclick="this.closest('tr').remove();quote68()">×</button></td>`;b68.appendChild(tr);tr.querySelectorAll('input').forEach(i=>i.onchange=quote68)}}quote68()}}
    scan68.onkeydown=e=>{{if(e.key==='Enter'){{e.preventDefault();add68(e.target.value);e.target.value=''}}}};let t68;search68.oninput=e=>{{clearTimeout(t68);t68=setTimeout(async()=>{{let r=await fetch('/api/pos-v67/search?q='+encodeURIComponent(e.target.value)),x=await r.json();res68.innerHTML=(x.data||[]).map(i=>`<button type=button onclick="add68('${{i.sku}}')">${{i.sku}} — ${{i.name}} — ${{i.price.toFixed(2)}}</button>`).join('')}},250)}};form68.onsubmit=()=>{{cartjson68.value=JSON.stringify(cart68())}};
    </script>""")

@app.route("/pos-security-v68",methods=["GET","POST"])
def pos_security_v68():
    if session.get("role")!="admin":return ("غير مصرح",403)
    c=con()
