def pos_cashier_allowed_v69(c,user,perm):
    if session.get("role") in ("admin","manager"):return True
    x=c.execute("SELECT allowed FROM pos_cashier_permissions_v69 WHERE username=? AND permission_code=?",(user,perm)).fetchone()
    return bool(x and x["allowed"])

def pos_shift_cash_summary_v69(c,shift_id):
    sh=c.execute("SELECT * FROM pos_shifts_v65 WHERE id=?",(shift_id,)).fetchone()
    if not sh:return None
    cash=float(c.execute("""SELECT coalesce(sum(p.amount),0) x FROM pos_payments_v65 p JOIN pos_sales_v65 s ON s.id=p.sale_id WHERE s.shift_id=? AND p.payment_method='CASH'""",(shift_id,)).fetchone()["x"])
    mov=c.execute("""SELECT
      coalesce(sum(CASE WHEN movement_type IN ('CASH_IN','DEPOSIT') THEN amount ELSE 0 END),0) cash_in,
      coalesce(sum(CASE WHEN movement_type IN ('CASH_OUT','EXPENSE') THEN amount ELSE 0 END),0) cash_out
      FROM pos_cash_movements_v69 WHERE shift_id=?""",(shift_id,)).fetchone()
    expected=round(float(sh["opening_cash"])+cash+float(mov["cash_in"])-float(mov["cash_out"]),2)
    return sh,cash,float(mov["cash_in"]),float(mov["cash_out"]),expected

@app.route("/pos-cash-v69",methods=["GET","POST"])
def pos_cash_v69():
    if not session.get("user"):return redirect("/login")
    c=con();u=session.get("user");sh=pos_open_shift_v65(c,u)
    if not sh:c.close();return page("<h1>حركة الصندوق v69</h1><div class=panel>يجب فتح وردية أولاً.</div>")
    if request.method=="POST":
        try:
            typ=request.form["type"]
            perm={"CASH_IN":"cash.in","DEPOSIT":"cash.in","CASH_OUT":"cash.out","EXPENSE":"cash.expense"}.get(typ,"")
            if not pos_cashier_allowed_v69(c,u,perm):raise ValueError("لا توجد صلاحية لهذه العملية")
            amount=float(request.form["amount"])
            if amount<=0:raise ValueError("المبلغ يجب أن يكون أكبر من صفر")
            c.execute("INSERT INTO pos_cash_movements_v69(shift_id,movement_type,amount,reason,reference,created_by) VALUES(?,?,?,?,?,?)",(sh["id"],typ,amount,request.form.get("reason",""),request.form.get("reference",""),u))
            c.commit();flash("تم تسجيل حركة الصندوق")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/pos-cash-v69")
    summary=pos_shift_cash_summary_v69(c,sh["id"])
    rows=c.execute("SELECT * FROM pos_cash_movements_v69 WHERE shift_id=? ORDER BY id DESC",(sh["id"],)).fetchall();c.close()
    rr="".join(f"<tr><td>{x['created_at']}</td><td>{x['movement_type']}</td><td>{x['amount']:.2f}</td><td>{html.escape(x['reason'] or '')}</td><td>{html.escape(x['reference'] or '')}</td><td>{x['created_by']}</td></tr>" for x in rows)
    _,cash,cin,cout,expected=summary
    return page(f"""<h1>حركة الصندوق v69</h1><div class=panel>الوردية: {sh['shift_no']} | مبيعات نقدية: {cash:.2f} | إدخال: {cin:.2f} | إخراج/مصروفات: {cout:.2f} | <strong>المتوقع: {expected:.2f}</strong></div>
    <form method=post class=panel><select name=type><option value=CASH_IN>إيداع نقدي</option><option value=CASH_OUT>سحب نقدي</option><option value=EXPENSE>مصروف من الصندوق</option></select><input name=amount type=number step=.01 required placeholder="المبلغ"><input name=reason required placeholder="السبب"><input name=reference placeholder="المرجع"><button>تسجيل</button></form>
    <table><tr><th>الوقت</th><th>النوع</th><th>المبلغ</th><th>السبب</th><th>المرجع</th><th>المستخدم</th></tr>{rr}</table>""")

