@app.route("/reorder-v70",methods=["GET","POST"])
def reorder_v70():
    if session.get("role") not in ("admin","manager","purchasing"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            c.execute("""INSERT OR REPLACE INTO reorder_rules_v70(company_id,branch_id,warehouse_id,item_id,min_qty,reorder_qty,target_qty,lead_days,preferred_supplier_id,active)
            VALUES(?,?,?,?,?,?,?,?,?,1)""",(int(request.form["company"]),int(request.form["branch"]),int(request.form["warehouse"]),int(request.form["item"]),float(request.form["min"]),float(request.form["reorder"]),float(request.form["target"]),int(request.form["lead"]),int(request.form["supplier"]) if request.form.get("supplier") else None))
            c.commit();flash("تم حفظ قاعدة إعادة الطلب")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/reorder-v70")
    rules=c.execute("""SELECT r.*,i.sku,i.name item,w.code warehouse,co.code company,b.code branch,coalesce(s.name,'') supplier,
    coalesce(inv.qty,0) stock
    FROM reorder_rules_v70 r JOIN inventory_items_v47 i ON i.id=r.item_id JOIN warehouses_v47 w ON w.id=r.warehouse_id
    JOIN companies_v54 co ON co.id=r.company_id JOIN branches_v54 b ON b.id=r.branch_id
    LEFT JOIN company_suppliers_v55 s ON s.id=r.preferred_supplier_id
    LEFT JOIN company_inventory_v56 inv ON inv.company_id=r.company_id AND inv.branch_id=r.branch_id AND inv.warehouse_id=r.warehouse_id AND inv.item_id=r.item_id
    ORDER BY i.sku""").fetchall()
    co=c.execute("SELECT * FROM companies_v54 WHERE active=1").fetchall();br=c.execute("SELECT b.*,co.code company FROM branches_v54 b JOIN companies_v54 co ON co.id=b.company_id WHERE b.active=1").fetchall();wh=c.execute("SELECT * FROM warehouses_v47 ORDER BY code").fetchall();items=c.execute("SELECT id,sku,name FROM inventory_items_v47 ORDER BY sku").fetchall();sup=c.execute("SELECT id,supplier_code,name FROM company_suppliers_v55 WHERE active=1 ORDER BY name").fetchall();c.close()
    def op(rows,lab):return "".join(f"<option value='{x['id']}'>{lab(x)}</option>" for x in rows)
    rr=""
    for x in rules:
        suggested=max(float(x["reorder_qty"]),float(x["target_qty"])-float(x["stock"])) if float(x["stock"])<=float(x["min_qty"]) else 0
        rr+=f"<tr><td>{x['company']}/{x['branch']}</td><td>{x['warehouse']}</td><td>{x['sku']} — {x['item']}</td><td>{x['stock']:.2f}</td><td>{x['min_qty']:.2f}</td><td>{suggested:.2f}</td><td>{x['supplier']}</td><td>{'اطلب' if suggested>0 else 'كافٍ'}</td></tr>"
    return page(f"""<h1>إعادة الطلب الذكية v70</h1><form method=post class=panel><select name=company>{op(co,lambda x:x['code']+' — '+x['name'])}</select><select name=branch>{op(br,lambda x:x['company']+'/'+x['code'])}</select><select name=warehouse>{op(wh,lambda x:x['code']+' — '+x['name'])}</select><select name=item>{op(items,lambda x:x['sku']+' — '+x['name'])}</select><input name=min type=number step=.001 required placeholder="حد إعادة الطلب"><input name=reorder type=number step=.001 required placeholder="كمية إعادة الطلب"><input name=target type=number step=.001 required placeholder="المخزون المستهدف"><input name=lead type=number value=7 min=0 placeholder="مهلة التوريد"><select name=supplier><option value="">بدون مورد مفضل</option>{op(sup,lambda x:x['supplier_code']+' — '+x['name'])}</select><button>حفظ</button></form><table><tr><th>الشركة/الفرع</th><th>المستودع</th><th>الصنف</th><th>الرصيد</th><th>الحد</th><th>المقترح</th><th>المورد</th><th>الحالة</th></tr>{rr}</table>""")

