    ao="".join(f"<option value='{x['id']}'>{x['bank_name']} — {x['account_name']}</option>" for x in ac);so="".join(f"<option value='{x['id']}'>{x['statement_date']} | {x['reference']} | {abs(float(x['credit'])-float(x['debit'])):.2f}</option>" for x in st);to="".join(f"<option value='{x['id']}'>{x['txn_date']} | {x['reference']} | {x['amount']:.2f}</option>" for x in tx)
    rr="".join(f"<tr><td>{x['bank_name']} — {x['account_name']}</td><td>{x['period_end']}</td><td>{x['statement_balance']:.2f}</td><td>{x['book_balance']:.2f}</td><td>{x['difference']:.2f}</td></tr>" for x in rec)
    return page(f"""<h1>التسوية البنكية v73</h1><form method=post class=panel><input type=hidden name=action value=match><select name=statement>{so}</select><select name=transaction>{to}</select><button>مطابقة الحركة</button></form><form method=post class=panel><input type=hidden name=action value=close><select name=bank>{ao}</select><input type=date name=period_end required value="{datetime.date.today()}"><input name=statement_balance type=number step=.01 required placeholder="رصيد كشف البنك"><button>إقفال التسوية</button></form><table><tr><th>الحساب</th><th>الفترة</th><th>رصيد البنك</th><th>رصيد الدفاتر</th><th>الفرق</th></tr>{rr}</table>""")

