def bank_match_score_v74(st,tx):
    import difflib
    sval=abs(float(st["credit"] or 0)-float(st["debit"] or 0));tval=abs(float(tx["amount"] or 0))
    amount_score=100 if abs(sval-tval)<.01 else max(0,100-(abs(sval-tval)/max(sval,tval,1))*100)
    try:
        sd=datetime.date.fromisoformat(st["value_date"] or st["statement_date"])
        td=datetime.date.fromisoformat(tx["txn_date"])
        dd=abs((sd-td).days);date_score=max(0,100-dd*20)
    except: date_score=0
    sr=((st["reference"] or "")+" "+(st["description"] or "")).strip().lower()
    tr=((tx["reference"] or "")+" "+(tx["description"] or "")).strip().lower()
    reference_score=round(difflib.SequenceMatcher(None,sr,tr).ratio()*100,2) if sr and tr else 0
    score=round(amount_score*.60+date_score*.25+reference_score*.15,2)
    return score,round(amount_score,2),round(date_score,2),reference_score

@app.route("/bank-import-v74",methods=["GET","POST"])
def bank_import_v74():
    if session.get("role") not in ("admin","manager","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            import csv,io
            bid=int(request.form["bank"]);f=request.files.get("file")
            if not f:raise ValueError("اختر ملف CSV")
            raw=f.read()
            text=None
            for enc in ("utf-8-sig","utf-8","cp1256","latin1"):
                try:text=raw.decode(enc);break
                except:pass
            if text is None:raise ValueError("تعذر قراءة ترميز الملف")
            reader=csv.DictReader(io.StringIO(text));count=0
            def val(row,*names):
                low={str(k).strip().lower():v for k,v in row.items()}
                for n in names:
                    if n.lower() in low:return low[n.lower()]
                return ""
            for row in reader:
                date=val(row,"date","statement_date","التاريخ")
                if not date:continue
                debit=float((val(row,"debit","مدين") or "0").replace(",",""))
                credit=float((val(row,"credit","دائن") or "0").replace(",",""))
                balance_txt=val(row,"balance","الرصيد")
                balance=float(balance_txt.replace(",","")) if balance_txt else None
                c.execute("""INSERT INTO bank_statement_lines_v73(bank_account_id,statement_date,value_date,reference,description,debit,credit,balance)
                VALUES(?,?,?,?,?,?,?,?)""",(bid,date,val(row,"value_date","تاريخ القيمة") or date,val(row,"reference","ref","المرجع"),val(row,"description","details","الوصف"),debit,credit,balance))
                count+=1
            c.execute("INSERT INTO bank_import_batches_v74(bank_account_id,file_name,imported_rows,imported_by) VALUES(?,?,?,?)",(bid,f.filename,count,session.get("user","")))
            c.commit();flash(f"تم استيراد {count} حركة")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/bank-import-v74")
    ac=c.execute("SELECT * FROM bank_accounts_v73 WHERE active=1").fetchall();batches=c.execute("""SELECT x.*,b.bank_name,b.account_name FROM bank_import_batches_v74 x JOIN bank_accounts_v73 b ON b.id=x.bank_account_id ORDER BY x.id DESC""").fetchall();c.close()
    ao="".join(f"<option value='{x['id']}'>{x['bank_name']} — {x['account_name']}</option>" for x in ac)
    rr="".join(f"<tr><td>{x['file_name']}</td><td>{x['bank_name']} — {x['account_name']}</td><td>{x['imported_rows']}</td><td>{x['imported_by']}</td><td>{x['imported_at']}</td></tr>" for x in batches)
    return page(f"""<h1>استيراد كشف البنك CSV v74</h1><div class=panel>الأعمدة المدعومة: date, value_date, reference, description, debit, credit, balance. ويمكن استخدام أسماء عربية مقابلة.</div><form method=post enctype=multipart/form-data class=panel><select name=bank>{ao}</select><input type=file name=file accept=".csv,text/csv" required><button>استيراد CSV</button></form><table><tr><th>الملف</th><th>الحساب</th><th>الصفوف</th><th>المستخدم</th><th>الوقت</th></tr>{rr}</table>""")

@app.route("/bank-smart-match-v74",methods=["GET","POST"])
def bank_smart_match_v74():
    if session.get("role") not in ("admin","manager","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            action=request.form["action"]
            if action=="scan":
                c.execute("DELETE FROM bank_match_suggestions_v74 WHERE status='SUGGESTED'")
                sts=c.execute("SELECT * FROM bank_statement_lines_v73 WHERE reconciled=0").fetchall()
                for st in sts:
                    txs=c.execute("SELECT * FROM bank_transactions_v73 WHERE bank_account_id=? AND reconciled=0",(st["bank_account_id"],)).fetchall()
                    ranked=[]
                    for tx in txs:
                        sc,a,d,r=bank_match_score_v74(st,tx)
                        if sc>=65:ranked.append((sc,a,d,r,tx["id"]))
                    for sc,a,d,r,tid in sorted(ranked,reverse=True)[:3]:
                        c.execute("INSERT OR IGNORE INTO bank_match_suggestions_v74(statement_line_id,transaction_id,score,amount_score,date_score,reference_score) VALUES(?,?,?,?,?,?)",(st["id"],tid,sc,a,d,r))
            elif action=="accept":
                sid=int(request.form["suggestion"]);sg=c.execute("SELECT * FROM bank_match_suggestions_v74 WHERE id=?",(sid,)).fetchone()
                if not sg:raise ValueError("الاقتراح غير موجود")
                c.execute("UPDATE bank_statement_lines_v73 SET reconciled=1,matched_transaction_id=? WHERE id=?",(sg["transaction_id"],sg["statement_line_id"]))
                c.execute("UPDATE bank_transactions_v73 SET reconciled=1 WHERE id=?",(sg["transaction_id"],))
                c.execute("UPDATE bank_match_suggestions_v74 SET status='ACCEPTED' WHERE id=?",(sid,))
                c.execute("UPDATE bank_match_suggestions_v74 SET status='REJECTED' WHERE statement_line_id=? AND id<>?",(sg["statement_line_id"],sid))
            elif action=="create":
                st=c.execute("SELECT * FROM bank_statement_lines_v73 WHERE id=?",(int(request.form["statement"]),)).fetchone()
                if not st:raise ValueError("سطر الكشف غير موجود")
                typ=request.form["type"];amount=abs(float(st["credit"] or 0)-float(st["debit"] or 0))
                cur=c.execute("""INSERT INTO bank_transactions_v73(bank_account_id,txn_date,txn_type,amount,reference,description,source_type,created_by,reconciled)
                VALUES(?,?,?,?,?,?,?,?,1)""",(st["bank_account_id"],st["value_date"] or st["statement_date"],typ,amount,st["reference"],st["description"],"BANK_STATEMENT",session.get("user","")))
                tid=cur.lastrowid;c.execute("UPDATE bank_statement_lines_v73 SET reconciled=1,matched_transaction_id=? WHERE id=?",(tid,st["id"]))
                c.execute("INSERT INTO bank_unmatched_actions_v74(statement_line_id,action_type,created_transaction_id,notes,created_by) VALUES(?,?,?,?,?)",(st["id"],typ,tid,request.form.get("notes",""),session.get("user","")))
            c.commit();flash("تم تنفيذ العملية")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/bank-smart-match-v74")
    sug=c.execute("""SELECT g.*,s.statement_date,s.reference sref,s.description sdesc,s.debit,s.credit,t.txn_date,t.reference tref,t.description tdesc,t.amount,b.bank_name,b.account_name
    FROM bank_match_suggestions_v74 g JOIN bank_statement_lines_v73 s ON s.id=g.statement_line_id JOIN bank_transactions_v73 t ON t.id=g.transaction_id JOIN bank_accounts_v73 b ON b.id=s.bank_account_id WHERE g.status='SUGGESTED' ORDER BY g.score DESC""").fetchall()
    unmatched=c.execute("""SELECT s.*,b.bank_name,b.account_name FROM bank_statement_lines_v73 s JOIN bank_accounts_v73 b ON b.id=s.bank_account_id WHERE s.reconciled=0 ORDER BY s.statement_date""").fetchall();c.close()
    rr="".join(f"<tr><td>{x['bank_name']}</td><td>{x['statement_date']} | {html.escape(x['sref'] or '')}</td><td>{abs(float(x['credit'])-float(x['debit'])):.2f}</td><td>{x['txn_date']} | {html.escape(x['tref'] or '')}</td><td>{x['amount']:.2f}</td><td>{x['score']:.1f}%</td><td><form method=post><input type=hidden name=action value=accept><input type=hidden name=suggestion value={x['id']}><button>اعتماد المطابقة</button></form></td></tr>" for x in sug)
    uo="".join(f"<option value='{x['id']}'>{x['statement_date']} | {x['bank_name']} | {abs(float(x['credit'])-float(x['debit'])):.2f} | {html.escape(x['reference'] or '')}</option>" for x in unmatched)
    return page(f"""<h1>المطابقة الذكية v74</h1><form method=post class=panel><input type=hidden name=action value=scan><button>تحليل الحركات واقتراح المطابقات</button></form><table><tr><th>البنك</th><th>حركة الكشف</th><th>المبلغ</th><th>حركة النظام</th><th>المبلغ</th><th>درجة التطابق</th><th></th></tr>{rr}</table><h2>معالجة حركة غير معروفة</h2><form method=post class=panel><input type=hidden name=action value=create><select name=statement>{uo}</select><select name=type><option value=BANK_FEE>رسوم بنكية</option><option value=INTEREST>عائد/فوائد</option><option value=DEPOSIT>إيداع غير مسجل</option><option value=WITHDRAWAL>سحب غير مسجل</option><option value=OTHER>أخرى</option></select><input name=notes placeholder="ملاحظات"><button>إنشاء حركة ومطابقتها</button></form>""")

