def norm_import_date_v75(v,fmt=""):
    if v is None:return ""
    if hasattr(v,"strftime"):return v.strftime("%Y-%m-%d")
    x=str(v).strip()
    if not x:return ""
    for f in ([fmt] if fmt else [])+["%Y-%m-%d","%d/%m/%Y","%m/%d/%Y","%d-%m-%Y"]:
        if not f:continue
        try:return datetime.datetime.strptime(x,f).date().isoformat()
        except:pass
    return x

def money_v75(v):
    if v is None or v=="":return 0.0
    if isinstance(v,(int,float)):return float(v)
    x=str(v).replace(",","").replace("SAR","").replace("ر.س","").strip()
    try:return float(x)
    except:return 0.0

def bank_post_auto_v75(c,transaction_id):
    tx=c.execute("""SELECT t.*,b.gl_account_code bank_gl FROM bank_transactions_v73 t JOIN bank_accounts_v73 b ON b.id=t.bank_account_id WHERE t.id=?""",(transaction_id,)).fetchone()
    if not tx or c.execute("SELECT 1 FROM bank_auto_postings_v75 WHERE transaction_id=?",(transaction_id,)).fetchone():return None
    rule=c.execute("SELECT * FROM bank_gl_rules_v75 WHERE txn_type=?",(tx["txn_type"],)).fetchone()
    if not rule:return None
    tables={x["name"] for x in c.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
    jid=None
    if {"journal_entries_v36","journal_lines_v36","chart_accounts_v36"}.issubset(tables):
        bank=c.execute("SELECT id FROM chart_accounts_v36 WHERE code=?",(tx["bank_gl"] or "1100",)).fetchone()
        other=c.execute("SELECT id FROM chart_accounts_v36 WHERE code=?",(rule["gl_account_code"],)).fetchone()
        if bank and other:
            no="JE-"+datetime.datetime.now().strftime("%Y%m%d%H%M%S%f")
            cur=c.execute("INSERT INTO journal_entries_v36(entry_no,entry_date,description,status,created_by) VALUES(?,?,?,?,?)",(no,tx["txn_date"],rule["description"],"POSTED",session.get("user","")));jid=cur.lastrowid
            incoming=tx["txn_type"]=="INTEREST"
            pairs=[(bank["id"],tx["amount"],0),(other["id"],0,tx["amount"])] if incoming else [(other["id"],tx["amount"],0),(bank["id"],0,tx["amount"])]
            for aid,d,cr in pairs:c.execute("INSERT INTO journal_lines_v36(entry_id,account_id,debit,credit,description) VALUES(?,?,?,?,?)",(jid,aid,d,cr,rule["description"]))
    c.execute("INSERT INTO bank_auto_postings_v75(transaction_id,journal_entry_id,posted_by) VALUES(?,?,?)",(transaction_id,jid,session.get("user","")))
    return jid

