def bank_score_v76(c,st,tx):
    import difflib
    r=c.execute("SELECT * FROM bank_match_rules_v75 WHERE id=1").fetchone()
    sval=abs(float(st["credit"] or 0)-float(st["debit"] or 0));tval=abs(float(tx["amount"] or 0))
    diff=abs(sval-tval)
    amount_score=100 if diff<=.01 else max(0,100-(diff/max(sval,tval,1))*100)
    try:
        sd=datetime.date.fromisoformat(st["value_date"] or st["statement_date"]);td=datetime.date.fromisoformat(tx["txn_date"])
        days=abs((sd-td).days)
        date_score=max(0,100-(days/max(1,int(r["max_date_days"])))*100) if days else 100
    except:date_score=0
    sr=((st["reference"] or "")+" "+(st["description"] or "")).strip().lower()
    tr=((tx["reference"] or "")+" "+(tx["description"] or "")).strip().lower()
    ref_score=difflib.SequenceMatcher(None,sr,tr).ratio()*100 if sr and tr else 0
    total=float(r["amount_weight"])+float(r["date_weight"])+float(r["reference_weight"])
    score=(amount_score*float(r["amount_weight"])+date_score*float(r["date_weight"])+ref_score*float(r["reference_weight"]))/max(total,1)
    return round(score,2),round(diff,2)

def audit_v76(c,st,tx,action,score=0,diff=0,notes=""):
    c.execute("INSERT INTO bank_reconcile_audit_v76(statement_line_id,transaction_id,action,score,amount_difference,notes,username) VALUES(?,?,?,?,?,?,?)",(st,tx,action,score,diff,notes,session.get("user","")))

@app.route("/bank-match-v76",methods=["GET","POST"])
def bank_match_v76():
    if session.get("role") not in ("admin","manager","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            action=request.form["action"];cfg=c.execute("SELECT * FROM bank_reconcile_settings_v76 WHERE id=1").fetchone()
            if action=="settings":
                c.execute("""UPDATE bank_reconcile_settings_v76 SET auto_match_score=?,review_score=?,amount_tolerance=?,difference_tolerance=?,auto_post_difference=? WHERE id=1""",
                (float(request.form["auto"]),float(request.form["review"]),float(request.form["amount_tol"]),float(request.form["diff_tol"]),1 if request.form.get("auto_diff") else 0))
            elif action=="scan":
                sts=c.execute("SELECT * FROM bank_statement_lines_v73 WHERE reconciled=0").fetchall()
                for st in sts:
                    txs=c.execute("SELECT * FROM bank_transactions_v73 WHERE bank_account_id=? AND reconciled=0",(st["bank_account_id"],)).fetchall()
                    ranked=[]
                    for tx in txs:
                        score,diff=bank_score_v76(c,st,tx)
                        if score>=float(cfg["review_score"]):ranked.append((score,-diff,tx,diff))
                    if ranked:
                        score,_,tx,diff=max(ranked,key=lambda z:(z[0],z[1]))
                        exists=c.execute("SELECT 1 FROM bank_match_suggestions_v74 WHERE statement_line_id=? AND transaction_id=? AND status='SUGGESTED'",(st["id"],tx["id"])).fetchone()
                        if not exists:c.execute("INSERT OR IGNORE INTO bank_match_suggestions_v74(statement_line_id,transaction_id,score,amount_score,date_score,reference_score,status) VALUES(?,?,?,?,?,?,'SUGGESTED')",(st["id"],tx["id"],score,0,0,0))
                        if score>=float(cfg["auto_match_score"]) and diff<=float(cfg["amount_tolerance"]):
                            c.execute("UPDATE bank_statement_lines_v73 SET reconciled=1,matched_transaction_id=? WHERE id=?",(tx["id"],st["id"]))
                            c.execute("UPDATE bank_transactions_v73 SET reconciled=1 WHERE id=?",(tx["id"],))
                            c.execute("UPDATE bank_match_suggestions_v74 SET status='ACCEPTED' WHERE statement_line_id=? AND transaction_id=?",(st["id"],tx["id"]))
                            audit_v76(c,st["id"],tx["id"],"AUTO_MATCH",score,diff,"مطابقة تلقائية عالية الثقة")
            elif action=="accept":
                sid=int(request.form["suggestion"]);sg=c.execute("SELECT * FROM bank_match_suggestions_v74 WHERE id=?",(sid,)).fetchone()
                if not sg:raise ValueError("الاقتراح غير موجود")
                st=c.execute("SELECT * FROM bank_statement_lines_v73 WHERE id=?",(sg["statement_line_id"],)).fetchone();tx=c.execute("SELECT * FROM bank_transactions_v73 WHERE id=?",(sg["transaction_id"],)).fetchone()
                if not st or not tx or st["reconciled"] or tx["reconciled"]:raise ValueError("الحركة سبق تسويتها")
                score,diff=bank_score_v76(c,st,tx)
                if diff>float(cfg["difference_tolerance"]):raise ValueError("الفرق يتجاوز حد السماح")
                c.execute("UPDATE bank_statement_lines_v73 SET reconciled=1,matched_transaction_id=? WHERE id=?",(tx["id"],st["id"]));c.execute("UPDATE bank_transactions_v73 SET reconciled=1 WHERE id=?",(tx["id"],));c.execute("UPDATE bank_match_suggestions_v74 SET status='ACCEPTED' WHERE id=?",(sid,))
                audit_v76(c,st["id"],tx["id"],"MANUAL_ACCEPT",score,diff,request.form.get("notes",""))
                if diff>float(cfg["amount_tolerance"]) and cfg["auto_post_difference"]:
                    sval=abs(float(st["credit"] or 0)-float(st["debit"] or 0));tval=abs(float(tx["amount"]));signed=sval-tval
                    typ="BANK_DIFFERENCE";cur=c.execute("""INSERT INTO bank_transactions_v73(bank_account_id,txn_date,txn_type,amount,reference,description,source_type,source_id,reconciled,created_by)
                    VALUES(?,?,?,?,?,?,?,?,1,?)""",(st["bank_account_id"],st["value_date"] or st["statement_date"],typ,abs(signed),"DIFF-"+str(st["id"]),"فرق تسوية بنكية","RECON_DIFFERENCE",st["id"],session.get("user","")))
                    dtid=cur.lastrowid;jid=bank_post_auto_v75(c,dtid)
                    c.execute("INSERT INTO bank_difference_postings_v76(statement_line_id,transaction_id,difference_amount,bank_transaction_id,journal_entry_id,created_by) VALUES(?,?,?,?,?,?)",(st["id"],tx["id"],signed,dtid,jid,session.get("user","")))
                    audit_v76(c,st["id"],tx["id"],"DIFFERENCE_POSTED",score,diff,f"فرق {signed:.2f}")
            elif action=="unmatch":
                stid=int(request.form["statement"]);st=c.execute("SELECT * FROM bank_statement_lines_v73 WHERE id=?",(stid,)).fetchone()
                if not st or not st["reconciled"]:raise ValueError("السطر غير مطابق")
                tid=st["matched_transaction_id"]
                c.execute("UPDATE bank_statement_lines_v73 SET reconciled=0,matched_transaction_id=NULL WHERE id=?",(stid,))
                if tid:c.execute("UPDATE bank_transactions_v73 SET reconciled=0 WHERE id=?",(tid,))
                audit_v76(c,stid,tid,"UNMATCH",0,0,request.form.get("notes","إلغاء المطابقة"))
            c.commit();flash("تم تنفيذ العملية")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/bank-match-v76")
    cfg=c.execute("SELECT * FROM bank_reconcile_settings_v76 WHERE id=1").fetchone()
    sug=c.execute("""SELECT g.*,s.statement_date,s.reference sref,s.debit,s.credit,t.txn_date,t.reference tref,t.amount,b.bank_name
    FROM bank_match_suggestions_v74 g JOIN bank_statement_lines_v73 s ON s.id=g.statement_line_id JOIN bank_transactions_v73 t ON t.id=g.transaction_id JOIN bank_accounts_v73 b ON b.id=s.bank_account_id
    WHERE g.status='SUGGESTED' AND s.reconciled=0 AND t.reconciled=0 ORDER BY g.score DESC""").fetchall()
    matched=c.execute("""SELECT s.*,b.bank_name,t.reference tref,t.amount FROM bank_statement_lines_v73 s JOIN bank_accounts_v73 b ON b.id=s.bank_account_id LEFT JOIN bank_transactions_v73 t ON t.id=s.matched_transaction_id WHERE s.reconciled=1 ORDER BY s.id DESC LIMIT 100""").fetchall();c.close()
    rr="".join(f"<tr><td>{x['bank_name']}</td><td>{x['statement_date']} / {html.escape(x['sref'] or '')}</td><td>{abs(float(x['credit'])-float(x['debit'])):.2f}</td><td>{x['txn_date']} / {html.escape(x['tref'] or '')}</td><td>{x['amount']:.2f}</td><td>{x['score']:.1f}%</td><td><form method=post><input type=hidden name=action value=accept><input type=hidden name=suggestion value={x['id']}><input name=notes placeholder='ملاحظة'><button>اعتماد</button></form></td></tr>" for x in sug)
    mm="".join(f"<tr><td>{x['bank_name']}</td><td>{x['statement_date']}</td><td>{html.escape(x['reference'] or '')}</td><td>{html.escape(x['tref'] or '')}</td><td><form method=post><input type=hidden name=action value=unmatch><input type=hidden name=statement value={x['id']}><input name=notes placeholder='سبب الإلغاء'><button>إلغاء المطابقة</button></form></td></tr>" for x in matched)
    return page(f"""<h1>محرك المطابقة الموحد v76</h1><form method=post class=panel><input type=hidden name=action value=settings><label>Auto-match من %</label><input name=auto type=number step=.1 value="{cfg['auto_match_score']}"><label>المراجعة من %</label><input name=review type=number step=.1 value="{cfg['review_score']}"><label>سماح المبلغ</label><input name=amount_tol type=number step=.01 value="{cfg['amount_tolerance']}"><label>أقصى فرق مسموح</label><input name=diff_tol type=number step=.01 value="{cfg['difference_tolerance']}"><label><input type=checkbox name=auto_diff {'checked' if cfg['auto_post_difference'] else ''}> إنشاء قيد فرق تلقائياً</label><button>حفظ</button></form><form method=post class=panel><input type=hidden name=action value=scan><button>تشغيل التحليل وAuto-Match</button></form><h2>مطابقات تحتاج مراجعة</h2><table><tr><th>البنك</th><th>الكشف</th><th>المبلغ</th><th>النظام</th><th>المبلغ</th><th>الثقة</th><th></th></tr>{rr}</table><h2>آخر المطابقات</h2><table><tr><th>البنك</th><th>التاريخ</th><th>مرجع الكشف</th><th>مرجع النظام</th><th></th></tr>{mm}</table>""")

