def bank_balance_v77(c,bid):
    rows=c.execute("SELECT txn_type,amount FROM bank_transactions_v73 WHERE bank_account_id=?",(bid,)).fetchall()
    incoming={"DEPOSIT","TRANSFER_IN","INTEREST"}
    return round(sum(float(x["amount"]) if x["txn_type"] in incoming else -float(x["amount"]) for x in rows),2)

def cash_balance_v77(c,cid):
    x=c.execute("""SELECT coalesce(sum(CASE WHEN txn_type IN ('RECEIPT','TRANSFER_IN','OPENING') THEN amount ELSE -amount END),0) x
    FROM treasury_cash_transactions_v77 WHERE cash_account_id=?""",(cid,)).fetchone()
    acc=c.execute("SELECT opening_balance FROM treasury_cash_accounts_v77 WHERE id=?",(cid,)).fetchone()
    return round((float(acc["opening_balance"]) if acc else 0)+float(x["x"]),2)

