@app.route("/fx-revaluation-v79",methods=["GET","POST"])
def fx_revaluation_v79():
    if session.get("role") not in ("admin","manager","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="calculate":
                d=request.form["date"];no="FXR-"+datetime.datetime.now().strftime("%Y%m%d%H%M%S%f")
                bid=c.execute("INSERT INTO fx_revaluation_batches_v79(batch_no,revaluation_date,created_by) VALUES(?,?,?)",(no,d,session.get("user",""))).lastrowid
                gain=loss=0
                for b in c.execute("SELECT * FROM bank_accounts_v73 WHERE active=1 AND currency<>'SAR'").fetchall():
                    bal=bank_balance_v77(c,b["id"]);closing=fx_rate_v78(c,b["currency"],d)
                    old=c.execute("SELECT rate_to_sar FROM exchange_rates_v78 WHERE currency_code=? AND rate_date<? ORDER BY rate_date DESC LIMIT 1",(b["currency"],d)).fetchone()
                    oldrate=float(old["rate_to_sar"]) if old else closing
                    gl=bal*(closing-oldrate)
                    c.execute("""INSERT INTO fx_revaluation_lines_v79(batch_id,account_type,account_id,account_name,currency_code,foreign_balance,book_rate,closing_rate,book_value_sar,closing_value_sar,gain_loss_sar)
                    VALUES(?,?,?,?,?,?,?,?,?,?,?)""",(bid,"BANK",b["id"],b["bank_name"]+" — "+b["account_name"],b["currency"],bal,oldrate,closing,bal*oldrate,bal*closing,gl))
                    if gl>=0:gain+=gl
                    else:loss+=abs(gl)
                for x in c.execute("SELECT * FROM treasury_cash_accounts_v77 WHERE active=1 AND currency<>'SAR'").fetchall():
                    bal=cash_balance_v77(c,x["id"]);closing=fx_rate_v78(c,x["currency"],d)
                    old=c.execute("SELECT rate_to_sar FROM exchange_rates_v78 WHERE currency_code=? AND rate_date<? ORDER BY rate_date DESC LIMIT 1",(x["currency"],d)).fetchone()
                    oldrate=float(old["rate_to_sar"]) if old else closing;gl=bal*(closing-oldrate)
                    c.execute("""INSERT INTO fx_revaluation_lines_v79(batch_id,account_type,account_id,account_name,currency_code,foreign_balance,book_rate,closing_rate,book_value_sar,closing_value_sar,gain_loss_sar)
                    VALUES(?,?,?,?,?,?,?,?,?,?,?)""",(bid,"CASH",x["id"],x["name"],x["currency"],bal,oldrate,closing,bal*oldrate,bal*closing,gl))
                    if gl>=0:gain+=gl
                    else:loss+=abs(gl)
                c.execute("UPDATE fx_revaluation_batches_v79 SET total_gain=?,total_loss=? WHERE id=?",(gain,loss,bid))
            elif a=="post":
                bid=int(request.form["batch"]);b=c.execute("SELECT * FROM fx_revaluation_batches_v79 WHERE id=?",(bid,)).fetchone()
                if not b or b["status"]!="DRAFT":raise ValueError("دفعة إعادة التقييم غير متاحة للترحيل")
                st=c.execute("SELECT * FROM fx_settings_v79 WHERE id=1").fetchone()
                for ln in c.execute("SELECT * FROM fx_revaluation_lines_v79 WHERE batch_id=?",(bid,)).fetchall():
                    if abs(float(ln["gain_loss_sar"]))<.005:continue
                    if ln["account_type"]=="BANK":
                        acc=c.execute("SELECT gl_account_code FROM bank_accounts_v73 WHERE id=?",(ln["account_id"],)).fetchone()
                        asset=gl_account_id_v79(c,(acc["gl_account_code"] if acc else "") or "1100")
                    else: asset=gl_account_id_v79(c,"1110")
                    gl=float(ln["gain_loss_sar"])
                    other=gl_account_id_v79(c,st["unrealized_gain_gl"] if gl>0 else st["unrealized_loss_gl"])
                    lines=[(asset,gl,0,"إعادة تقييم عملة"),(other,0,gl,"ربح غير محقق")] if gl>0 else [(other,abs(gl),0,"خسارة غير محققة"),(asset,0,abs(gl),"إعادة تقييم عملة")]
                    jid=create_fx_je_v79(c,b["revaluation_date"],"إعادة تقييم "+ln["currency_code"],lines)
                    c.execute("UPDATE fx_revaluation_lines_v79 SET journal_entry_id=? WHERE id=?",(jid,ln["id"]))
                c.execute("UPDATE fx_revaluation_batches_v79 SET status='POSTED',posted_by=?,posted_at=CURRENT_TIMESTAMP WHERE id=?",(session.get("user",""),bid))
            elif a=="reverse":
                bid=int(request.form["batch"]);b=c.execute("SELECT * FROM fx_revaluation_batches_v79 WHERE id=?",(bid,)).fetchone()
                if not b or b["status"]!="POSTED":raise ValueError("يمكن عكس الدفعات المرحلة فقط")
                rd=(datetime.date.fromisoformat(b["revaluation_date"])+datetime.timedelta(days=1)).isoformat()
                for ln in c.execute("SELECT * FROM fx_revaluation_lines_v79 WHERE batch_id=?",(bid,)).fetchall():
                    if not ln["journal_entry_id"]:continue
                    orig=c.execute("SELECT * FROM journal_lines_v36 WHERE entry_id=?",(ln["journal_entry_id"],)).fetchall()
                    lines=[(x["account_id"],float(x["credit"]),float(x["debit"]),"عكس إعادة تقييم") for x in orig]
                    rjid=create_fx_je_v79(c,rd,"عكس إعادة تقييم "+ln["currency_code"],lines)
                    c.execute("UPDATE fx_revaluation_lines_v79 SET reversal_journal_entry_id=? WHERE id=?",(rjid,ln["id"]))
                c.execute("UPDATE fx_revaluation_batches_v79 SET status='REVERSED',reversed_by=?,reversed_at=CURRENT_TIMESTAMP WHERE id=?",(session.get("user",""),bid))
            c.commit();flash("تم تنفيذ العملية")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/fx-revaluation-v79")
    batches=c.execute("SELECT * FROM fx_revaluation_batches_v79 ORDER BY id DESC").fetchall();c.close()
    rr="".join(f"""<tr><td>{x['batch_no']}</td><td>{x['revaluation_date']}</td><td>{x['total_gain']:,.2f}</td><td>{x['total_loss']:,.2f}</td><td>{x['status']}</td><td><form method=post><input type=hidden name=batch value={x['id']}><button name=action value=post>ترحيل</button><button name=action value=reverse>عكس</button></form></td></tr>""" for x in batches)
    return page(f"""<h1>إعادة تقييم العملات v79</h1><form method=post class=panel><input type=hidden name=action value=calculate><input type=date name=date required value="{datetime.date.today()}"><button>حساب إعادة التقييم</button></form><table><tr><th>الدفعة</th><th>التاريخ</th><th>أرباح غير محققة</th><th>خسائر غير محققة</th><th>الحالة</th><th>الإجراء</th></tr>{rr}</table>""")

@app.route("/fx-realized-v79",methods=["GET","POST"])
def fx_realized_v79():
    if session.get("role") not in ("admin","manager","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            cur=request.form["currency"];amt=float(request.form["amount"]);orig=float(request.form["original_rate"]);settle=float(request.form["settlement_rate"])
            gl=round(amt*(settle-orig),2);st=c.execute("SELECT * FROM fx_settings_v79 WHERE id=1").fetchone()
            gainloss=gl_account_id_v79(c,st["realized_gain_gl"] if gl>=0 else st["realized_loss_gl"])
            clearing=gl_account_id_v79(c,request.form["counter_gl"])
            lines=[(clearing,gl,0,"فرق عملة محقق"),(gainloss,0,gl,"ربح عملة محقق")] if gl>=0 else [(gainloss,abs(gl),0,"خسارة عملة محققة"),(clearing,0,abs(gl),"فرق عملة محقق")]
            jid=create_fx_je_v79(c,request.form["date"],"فرق عملة محقق "+cur,lines)
            c.execute("""INSERT INTO fx_realized_v79(txn_date,source_type,currency_code,foreign_amount,original_rate,settlement_rate,gain_loss_sar,journal_entry_id,created_by)
            VALUES(?,?,?,?,?,?,?,?,?)""",(request.form["date"],"MANUAL",cur,amt,orig,settle,gl,jid,session.get("user","")))
            c.commit();flash("تم حساب وترحيل فرق العملة المحقق")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/fx-realized-v79")
    curr=c.execute("SELECT * FROM currencies_v78 WHERE active=1 AND code<>'SAR'").fetchall();rows=c.execute("SELECT * FROM fx_realized_v79 ORDER BY id DESC").fetchall();c.close()
    co="".join(f"<option value='{x['code']}'>{x['code']} — {x['name']}</option>" for x in curr)
    rr="".join(f"<tr><td>{x['txn_date']}</td><td>{x['currency_code']}</td><td>{x['foreign_amount']:,.2f}</td><td>{x['original_rate']:.6f}</td><td>{x['settlement_rate']:.6f}</td><td>{x['gain_loss_sar']:,.2f}</td><td>{x['journal_entry_id'] or ''}</td></tr>" for x in rows)
    return page(f"""<h1>فروق العملة المحققة v79</h1><form method=post class=panel><input type=date name=date required value="{datetime.date.today()}"><select name=currency>{co}</select><input name=amount type=number step=.01 required placeholder="المبلغ بالعملة"><input name=original_rate type=number step=.000001 required placeholder="السعر الأصلي"><input name=settlement_rate type=number step=.000001 required placeholder="سعر التسوية"><input name=counter_gl required placeholder="حساب المقابل GL"><button>حساب وترحيل</button></form><table><tr><th>التاريخ</th><th>العملة</th><th>المبلغ</th><th>السعر الأصلي</th><th>سعر التسوية</th><th>ربح/خسارة SAR</th><th>القيد</th></tr>{rr}</table>""")


def actual_by_account_month_v80(c,year):
    out={}
    tables={x["name"] for x in c.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
    if not {"journal_entries_v36","journal_lines_v36","chart_accounts_v36"}.issubset(tables):return out
    rows=c.execute("""SELECT a.code account_code,CAST(strftime('%m',e.entry_date) AS INTEGER) m,
      SUM(COALESCE(l.debit,0)-COALESCE(l.credit,0)) amount
      FROM journal_entries_v36 e JOIN journal_lines_v36 l ON l.entry_id=e.id
      JOIN chart_accounts_v36 a ON a.id=l.account_id
      WHERE CAST(strftime('%Y',e.entry_date) AS INTEGER)=? AND e.status='POSTED'
      GROUP BY a.code,m""",(year,)).fetchall()
    for x in rows:out[(x["account_code"],int(x["m"]))]=float(x["amount"] or 0)
    return out

@app.route("/budgets-v80",methods=["GET","POST"])
def budgets_v80():
    if session.get("role") not in ("admin","manager","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="new":
                no="BUD-"+str(request.form["year"])+"-"+datetime.datetime.now().strftime("%H%M%S%f")
                bid=c.execute("""INSERT INTO budgets_v80(budget_no,name,fiscal_year,company_id,scenario,notes,created_by)
                VALUES(?,?,?,?,?,?,?)""",(no,request.form["name"],int(request.form["year"]),int(request.form["company"]),request.form["scenario"],request.form.get("notes",""),session.get("user",""))).lastrowid
                c.execute("INSERT INTO budget_audit_v80(budget_id,action,username) VALUES(?,?,?)",(bid,"CREATED",session.get("user","")))
            elif a=="line":
                bid=int(request.form["budget"]);b=c.execute("SELECT * FROM budgets_v80 WHERE id=?",(bid,)).fetchone()
                if not b or b["status"] not in ("DRAFT","REJECTED"):raise ValueError("الموازنة غير قابلة للتعديل")
                c.execute("""INSERT INTO budget_lines_v80(budget_id,account_code,cost_center,department,month,amount,forecast_amount,notes)
                VALUES(?,?,?,?,?,?,?,?)""",(bid,request.form["account"],request.form.get("cost_center",""),request.form.get("department",""),int(request.form["month"]),float(request.form["amount"]),float(request.form.get("forecast") or request.form["amount"]),request.form.get("notes","")))
            elif a=="workflow":
                bid=int(request.form["budget"]);act=request.form["workflow"];b=c.execute("SELECT * FROM budgets_v80 WHERE id=?",(bid,)).fetchone()
                if not b:raise ValueError("الموازنة غير موجودة")
                if act=="submit":
                    if b["status"] not in ("DRAFT","REJECTED"):raise ValueError("الحالة لا تسمح بالإرسال")
                    c.execute("UPDATE budgets_v80 SET status='PENDING_APPROVAL',submitted_by=?,submitted_at=CURRENT_TIMESTAMP WHERE id=?",(session.get("user",""),bid))
                elif act=="approve":
                    if session.get("role") not in ("admin","manager"):raise ValueError("الاعتماد للمدير فقط")
                    if b["status"]!="PENDING_APPROVAL":raise ValueError("الموازنة ليست بانتظار الاعتماد")
                    c.execute("UPDATE budgets_v80 SET status='APPROVED',approved_by=?,approved_at=CURRENT_TIMESTAMP WHERE id=?",(session.get("user",""),bid))
                elif act=="reject":
                    if session.get("role") not in ("admin","manager"):raise ValueError("الرفض للمدير فقط")
                    c.execute("UPDATE budgets_v80 SET status='REJECTED' WHERE id=?",(bid,))
                c.execute("INSERT INTO budget_audit_v80(budget_id,action,username,notes) VALUES(?,?,?,?)",(bid,act.upper(),session.get("user",""),request.form.get("notes","")))
            c.commit();flash("تم تنفيذ العملية")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/budgets-v80")
    budgets=c.execute("SELECT * FROM budgets_v80 ORDER BY fiscal_year DESC,id DESC").fetchall()
    companies=c.execute("SELECT * FROM companies_v54 WHERE active=1").fetchall()
    scenarios=c.execute("SELECT * FROM budget_scenarios_v80 WHERE active=1").fetchall()
    accounts=c.execute("SELECT code,name FROM chart_accounts_v36 ORDER BY code").fetchall() if c.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='chart_accounts_v36'").fetchone() else []
    c.close()
    bo="".join(f"<option value='{x['id']}'>{x['budget_no']} — {html.escape(x['name'])}</option>" for x in budgets)
    co="".join(f"<option value='{x['id']}'>{x['code']}</option>" for x in companies)
    so="".join(f"<option value='{x['name']}'>{x['name']}</option>" for x in scenarios)
    ao="".join(f"<option value='{x['code']}'>{x['code']} — {html.escape(x['name'])}</option>" for x in accounts)
    rr="".join(f"""<tr><td>{x['budget_no']}</td><td>{html.escape(x['name'])}</td><td>{x['fiscal_year']}</td><td>{x['scenario']}</td><td>{x['status']}</td><td><form method=post><input type=hidden name=action value=workflow><input type=hidden name=budget value={x['id']}><button name=workflow value=submit>إرسال</button><button name=workflow value=approve>اعتماد</button><button name=workflow value=reject>رفض</button><input name=notes placeholder="ملاحظة"></form></td><td><form method=post action='/budget-copy-v81/{x["id"]}'><input name=reason placeholder='سبب Revision'><button>إنشاء Revision</button></form></td></tr>""" for x in budgets)
    return page(f"""<h1>الموازنات والتخطيط المالي v80</h1>
    <form method=post class=panel><input type=hidden name=action value=new><input name=name required placeholder="اسم الموازنة"><input name=year type=number required value="{datetime.date.today().year}"><select name=company>{co}</select><select name=scenario>{so}</select><input name=notes placeholder="ملاحظات"><button>إنشاء موازنة</button></form>
    <form method=post class=panel><input type=hidden name=action value=line><select name=budget>{bo}</select><select name=account>{ao}</select><input name=cost_center placeholder="مركز التكلفة"><input name=department placeholder="القسم"><input name=month type=number min=1 max=12 required><input name=amount type=number step=.01 required placeholder="Budget"><input name=forecast type=number step=.01 placeholder="Forecast"><input name=notes placeholder="ملاحظات"><button>إضافة بند شهري</button></form>
    <table><tr><th>الرقم</th><th>الموازنة</th><th>السنة</th><th>السيناريو</th><th>الحالة</th><th>الإجراء</th></tr>{rr}</table>""")

@app.route("/budget-analysis-v80")
def budget_analysis_v80():
    if session.get("role") not in ("admin","manager","accountant","auditor"):return ("غير مصرح",403)
    c=con()
    bid=request.args.get("budget",type=int)
    budgets=c.execute("SELECT * FROM budgets_v80 ORDER BY fiscal_year DESC,id DESC").fetchall()
    if not bid and budgets:bid=budgets[0]["id"]
    b=c.execute("SELECT * FROM budgets_v80 WHERE id=?",(bid,)).fetchone() if bid else None
    rows=[];totb=tota=totf=0
    if b:
        actual=actual_by_account_month_v80(c,b["fiscal_year"])
        lines=c.execute("""SELECT account_code,cost_center,department,month,SUM(amount) budget,SUM(forecast_amount) forecast
        FROM budget_lines_v80 WHERE budget_id=? GROUP BY account_code,cost_center,department,month ORDER BY account_code,month""",(bid,)).fetchall()
        for x in lines:
            bv=float(x["budget"] or 0);fv=float(x["forecast"] or 0);av=float(actual.get((x["account_code"],int(x["month"])),0))
            variance=av-bv; pct=(variance/abs(bv)*100) if bv else 0
            rows.append((x,bv,av,variance,pct,fv));totb+=bv;tota+=av;totf+=fv
    c.close()
    opts="".join(f"<option value='{x['id']}' {'selected' if x['id']==bid else ''}>{x['budget_no']} — {html.escape(x['name'])}</option>" for x in budgets)
    rr="".join(f"<tr><td>{x['account_code']}</td><td>{html.escape(x['cost_center'] or '')}</td><td>{html.escape(x['department'] or '')}</td><td>{x['month']}</td><td>{bv:,.2f}</td><td>{av:,.2f}</td><td>{v:,.2f}</td><td>{pct:,.1f}%</td><td>{fv:,.2f}</td></tr>" for x,bv,av,v,pct,fv in rows)
    return page(f"""<h1>Budget vs Actual v80</h1><form method=get class=panel><select name=budget>{opts}</select><button>عرض</button></form>
    <div class=panel><b>إجمالي Budget:</b> {totb:,.2f} &nbsp; | &nbsp; <b>Actual:</b> {tota:,.2f} &nbsp; | &nbsp; <b>Variance:</b> {tota-totb:,.2f} &nbsp; | &nbsp; <b>Forecast:</b> {totf:,.2f}</div>
    <table><tr><th>الحساب</th><th>مركز التكلفة</th><th>القسم</th><th>الشهر</th><th>Budget</th><th>Actual</th><th>Variance</th><th>%</th><th>Forecast</th></tr>{rr}</table>""")

