            c.execute("INSERT INTO inventory_movements_v84(item_code,movement_date,movement_type,qty,unit_cost,source_type,source_id,reference,created_by) VALUES(?,?,?,?,?,?,?,?,?)",(pl["item_code"],request.form["date"],"OUT",qty,pl["unit_price"],"PURCHASE_RETURN",rid,no,session.get("user","")))
