            c.execute("INSERT INTO procurement_payments_v84(invoice_id,payment_date,amount,source_type,source_id,reference,bank_transaction_id,cash_transaction_id,created_by) VALUES(?,?,?,?,?,?,?,?,?)",(iid,request.form["date"],amt,typ,sid,ref,bankid,cashid,session.get("user","")))
