@app.route("/vendor-aging-v85")
def vendor_aging_v85():
    if session.get("role") not in ("admin","manager","accountant","auditor"):return ("غير مصرح",403)
    c=con();asof=request.args.get("asof") or datetime.date.today().isoformat();d=datetime.date.fromisoformat(asof)
    suppliers=c.execute("""SELECT supplier_id,SUM(credit-debit) balance FROM ap_ledger_v85 GROUP BY supplier_id HAVING ABS(SUM(credit-debit))>.005""").fetchall()
    data=[]
    for sp in suppliers:
        invs=c.execute("SELECT * FROM ap_ledger_v85 WHERE supplier_id=? AND txn_type='INVOICE' ORDER BY due_date,txn_date",(sp["supplier_id"],)).fetchall()
        payments=float(c.execute("SELECT coalesce(sum(debit),0) x FROM ap_ledger_v85 WHERE supplier_id=? AND txn_type IN ('PAYMENT','CREDIT_NOTE')",(sp["supplier_id"],)).fetchone()["x"])
        buckets=[0,0,0,0,0];remaining_pay=payments
        for x in invs:
            openamt=float(x["credit"])
            used=min(openamt,remaining_pay);openamt-=used;remaining_pay-=used
            if openamt<=.005:continue
            due=datetime.date.fromisoformat(x["due_date"] or x["txn_date"]);days=(d-due).days
            idx=0 if days<=0 else 1 if days<=30 else 2 if days<=60 else 3 if days<=90 else 4
            buckets[idx]+=openamt
        data.append((sp["supplier_id"],buckets))
    c.close()
    rr="".join(f"<tr><td>{sid}</td><td>{sum(b):,.2f}</td><td>{b[0]:,.2f}</td><td>{b[1]:,.2f}</td><td>{b[2]:,.2f}</td><td>{b[3]:,.2f}</td><td>{b[4]:,.2f}</td></tr>" for sid,b in data)
    return page(f"""<h1>Vendor Aging v85</h1><form method=get class=panel><input type=date name=asof value="{asof}"><button>عرض</button></form><table><tr><th>Supplier ID</th><th>الرصيد</th><th>غير مستحق</th><th>1-30</th><th>31-60</th><th>61-90</th><th>+90</th></tr>{rr}</table>""")

@app.route("/grni-v85")
def grni_v85():
    if session.get("role") not in ("admin","manager","accountant","auditor"):return ("غير مصرح",403)
    c=con()
    rows=c.execute("""SELECT po_id,grn_id,SUM(credit) received,SUM(debit) invoiced,SUM(credit-debit) open_grni
      FROM grni_ledger_v85 GROUP BY po_id,grn_id HAVING ABS(SUM(credit-debit))>.005 ORDER BY po_id,grn_id""").fetchall()
    total=sum(float(x["open_grni"]) for x in rows);c.close()
    rr="".join(f"<tr><td>{x['po_id']}</td><td>{x['grn_id']}</td><td>{x['received']:,.2f}</td><td>{x['invoiced']:,.2f}</td><td>{x['open_grni']:,.2f}</td></tr>" for x in rows)
    return page(f"""<h1>GRNI Reconciliation v85</h1><div class=panel><b>إجمالي GRNI المفتوح:</b> {total:,.2f}</div><table><tr><th>PO ID</th><th>GRN ID</th><th>Received</th><th>Invoiced</th><th>Open GRNI</th></tr>{rr}</table>""")


def supplier_open_v86(c,sid):
    credit=float(c.execute("SELECT coalesce(sum(credit),0) x FROM ap_ledger_v85 WHERE supplier_id=?",(sid,)).fetchone()["x"])
    debit=float(c.execute("SELECT coalesce(sum(debit),0) x FROM ap_ledger_v85 WHERE supplier_id=?",(sid,)).fetchone()["x"])
    return credit-debit

def invoice_open_v86(c,ledger_id):
    x=c.execute("SELECT * FROM ap_ledger_v85 WHERE id=? AND txn_type='INVOICE'",(ledger_id,)).fetchone()
    if not x:return 0
    alloc=float(c.execute("SELECT coalesce(sum(amount),0) x FROM ap_allocations_v86 WHERE invoice_ledger_id=?",(ledger_id,)).fetchone()["x"])
    return max(0,float(x["credit"])-alloc)

@app.route("/supplier-ap-v86",methods=["GET","POST"])
def supplier_ap_v86():
    if session.get("role") not in ("admin","manager","accountant","treasury"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="profile":
                sid=int(request.form["supplier"])
                c.execute("""INSERT INTO supplier_profiles_v86(supplier_id,credit_limit,payment_terms_days,early_discount_pct,early_discount_days,preferred_payment_method,hold_payments,notes)
                VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(supplier_id) DO UPDATE SET credit_limit=excluded.credit_limit,payment_terms_days=excluded.payment_terms_days,early_discount_pct=excluded.early_discount_pct,early_discount_days=excluded.early_discount_days,preferred_payment_method=excluded.preferred_payment_method,hold_payments=excluded.hold_payments,notes=excluded.notes""",
                (sid,float(request.form["limit"]),int(request.form["terms"]),float(request.form["disc"]),int(request.form["disc_days"]),request.form.get("method","BANK"),1 if request.form.get("hold") else 0,request.form.get("notes","")))
            elif a=="allocate":
                payid=int(request.form["payment_ledger"]);invid=int(request.form["invoice_ledger"]);amt=float(request.form["amount"])
                p=c.execute("SELECT * FROM ap_ledger_v85 WHERE id=?",(payid,)).fetchone();inv=c.execute("SELECT * FROM ap_ledger_v85 WHERE id=?",(invid,)).fetchone()
                if not p or not inv or p["supplier_id"]!=inv["supplier_id"]:raise ValueError("الدفع والفاتورة ليسا لنفس المورد")
                pay_alloc=float(c.execute("SELECT coalesce(sum(amount),0) x FROM ap_allocations_v86 WHERE payment_ledger_id=?",(payid,)).fetchone()["x"])
                if amt<=0 or amt>float(p["debit"])-pay_alloc+.001 or amt>invoice_open_v86(c,invid)+.001:raise ValueError("مبلغ التسوية يتجاوز الرصيد المفتوح")
                c.execute("INSERT INTO ap_allocations_v86(supplier_id,payment_ledger_id,invoice_ledger_id,amount,allocated_by) VALUES(?,?,?,?,?)",(p["supplier_id"],payid,invid,amt,session.get("user","")))
            elif a=="advance":
                sid=int(request.form["supplier"]);amt=float(request.form["amount"]);st=c.execute("SELECT * FROM procurement_accounting_settings_v85 WHERE id=1").fetchone()
                if amt<=0:raise ValueError("المبلغ غير صحيح")
                cashgl=st["bank_gl"] if request.form["source_type"]=="BANK" else st["cash_gl"]
                jid=post_proc_je_v85(c,request.form["date"],"Supplier Advance",[(st["ap_gl"],amt,0,"دفعة مقدمة للمورد"),(cashgl,0,amt,"بنك/صندوق")])
                c.execute("INSERT INTO supplier_advances_v86(supplier_id,advance_date,amount,remaining_amount,source_type,source_id,reference,journal_entry_id,created_by) VALUES(?,?,?,?,?,?,?,?,?)",(sid,request.form["date"],amt,amt,request.form["source_type"],int(request.form["source_id"]),request.form.get("reference",""),jid,session.get("user","")))
                c.execute("INSERT INTO ap_ledger_v85(supplier_id,txn_date,txn_type,source_id,reference,debit,journal_entry_id,status) VALUES(?,?,?,?,?,?,?,'POSTED')",(sid,request.form["date"],"ADVANCE",0,request.form.get("reference",""),amt,jid))
            elif a=="debit_note":
                sid=int(request.form["supplier"]);amt=float(request.form["amount"]);st=c.execute("SELECT * FROM procurement_accounting_settings_v85 WHERE id=1").fetchone()
                no="DN-"+datetime.datetime.now().strftime("%Y%m%d%H%M%S%f")
                jid=post_proc_je_v85(c,request.form["date"],"Supplier Debit Note "+no,[(st["ap_gl"],amt,0,"إشعار خصم مورد"),(st["purchase_return_gl"],0,amt,"خصم/تسوية مورد")])
                c.execute("INSERT INTO ap_debit_notes_v86(note_no,supplier_id,note_date,amount,reason,journal_entry_id,created_by) VALUES(?,?,?,?,?,?,?)",(no,sid,request.form["date"],amt,request.form.get("reason",""),jid,session.get("user","")))
                c.execute("INSERT INTO ap_ledger_v85(supplier_id,txn_date,txn_type,source_id,reference,debit,journal_entry_id,status) VALUES(?,?,?,?,?,?,?,'POSTED')",(sid,request.form["date"],"DEBIT_NOTE",0,no,amt,jid))
            c.commit();flash("تم تنفيذ العملية")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/supplier-ap-v86")
    sids=[x["supplier_id"] for x in c.execute("SELECT DISTINCT supplier_id FROM ap_ledger_v85 ORDER BY supplier_id").fetchall()]
    profiles={x["supplier_id"]:x for x in c.execute("SELECT * FROM supplier_profiles_v86").fetchall()}
    invoices=c.execute("SELECT * FROM ap_ledger_v85 WHERE txn_type='INVOICE' ORDER BY txn_date DESC").fetchall()
    payments=c.execute("SELECT * FROM ap_ledger_v85 WHERE txn_type IN ('PAYMENT','ADVANCE') ORDER BY txn_date DESC").fetchall();c.close()
    so="".join(f"<option value='{x}'>{x}</option>" for x in sids)
    io="".join(f"<option value='{x['id']}'>Supplier {x['supplier_id']} / {x['reference']} / {x['credit']:,.2f}</option>" for x in invoices)
    po="".join(f"<option value='{x['id']}'>Supplier {x['supplier_id']} / {x['reference']} / {x['debit']:,.2f}</option>" for x in payments)
    rr="".join(f"<tr><td>{sid}</td><td>{supplier_open_v86(con(),sid):,.2f}</td><td>{profiles[sid]['credit_limit'] if sid in profiles else 0:,.2f}</td><td>{profiles[sid]['payment_terms_days'] if sid in profiles else 30}</td><td>{'موقوف' if sid in profiles and profiles[sid]['hold_payments'] else 'نشط'}</td></tr>" for sid in sids)
    return page(f"""<h1>إدارة الموردين والحسابات الدائنة v86</h1>
    <form method=post class=panel><input type=hidden name=action value=profile><select name=supplier>{so}</select><input name=limit type=number step=.01 value=0 placeholder="حد الائتمان"><input name=terms type=number value=30 placeholder="شروط الدفع بالأيام"><input name=disc type=number step=.01 value=0 placeholder="خصم السداد المبكر %"><input name=disc_days type=number value=0 placeholder="أيام الخصم"><input name=method value="BANK" placeholder="طريقة الدفع"><label><input type=checkbox name=hold> إيقاف المدفوعات</label><input name=notes placeholder="ملاحظات"><button>حفظ ملف المورد</button></form>
    <form method=post class=panel><input type=hidden name=action value=allocate><select name=payment_ledger>{po}</select><select name=invoice_ledger>{io}</select><input name=amount type=number step=.01 required placeholder="مبلغ التسوية"><button>تسوية الدفع مع الفاتورة</button></form>
    <form method=post class=panel><input type=hidden name=action value=advance><select name=supplier>{so}</select><input type=date name=date value="{datetime.date.today()}" required><select name=source_type><option>BANK</option><option>CASH</option></select><input name=source_id type=number required placeholder="Bank/Cash ID"><input name=amount type=number step=.01 required placeholder="دفعة مقدمة"><input name=reference placeholder="المرجع"><button>تسجيل دفعة مقدمة</button></form>
    <form method=post class=panel><input type=hidden name=action value=debit_note><select name=supplier>{so}</select><input type=date name=date value="{datetime.date.today()}" required><input name=amount type=number step=.01 required placeholder="قيمة إشعار الخصم"><input name=reason placeholder="السبب"><button>إنشاء Debit Note</button></form>
    <table><tr><th>Supplier</th><th>الرصيد</th><th>Credit Limit</th><th>Terms</th><th>الدفع</th></tr>{rr}</table>""")

@app.route("/supplier-statement-v86")
def supplier_statement_v86():
    if session.get("role") not in ("admin","manager","accountant","auditor","treasury"):return ("غير مصرح",403)
    c=con();sid=request.args.get("supplier",type=int)
    sids=[x["supplier_id"] for x in c.execute("SELECT DISTINCT supplier_id FROM ap_ledger_v85 ORDER BY supplier_id").fetchall()]
    if sid is None and sids:sid=sids[0]
    rows=c.execute("SELECT * FROM ap_ledger_v85 WHERE supplier_id=? ORDER BY txn_date,id",(sid,)).fetchall() if sid is not None else []
    bal=0;out=""
    for x in rows:
        bal+=float(x["credit"])-float(x["debit"])
        out+=f"<tr><td>{x['txn_date']}</td><td>{x['txn_type']}</td><td>{html.escape(x['reference'] or '')}</td><td>{x['debit']:,.2f}</td><td>{x['credit']:,.2f}</td><td>{bal:,.2f}</td><td>{x['due_date'] or ''}</td></tr>"
    c.close();opts="".join(f"<option value='{x}' {'selected' if x==sid else ''}>{x}</option>" for x in sids)
    return page(f"""<h1>كشف حساب المورد v86</h1><form method=get class=panel><select name=supplier>{opts}</select><button>عرض</button></form><table><tr><th>التاريخ</th><th>الحركة</th><th>المرجع</th><th>مدين</th><th>دائن</th><th>الرصيد</th><th>الاستحقاق</th></tr>{out}</table>""")

@app.route("/payment-runs-v86",methods=["GET","POST"])
def payment_runs_v86():
    if session.get("role") not in ("admin","manager","accountant","treasury"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="generate":
                cutoff=datetime.date.fromisoformat(request.form["cutoff"]);no="PAYRUN-"+datetime.datetime.now().strftime("%Y%m%d%H%M%S%f")
                rid=c.execute("INSERT INTO payment_runs_v86(run_no,run_date,created_by) VALUES(?,?,?)",(no,request.form["date"],session.get("user",""))).lastrowid
                invs=c.execute("SELECT * FROM ap_ledger_v85 WHERE txn_type='INVOICE' AND due_date<=? ORDER BY due_date",(cutoff.isoformat(),)).fetchall();total=0
                for inv in invs:
                    prof=c.execute("SELECT * FROM supplier_profiles_v86 WHERE supplier_id=?",(inv["supplier_id"],)).fetchone()
                    if prof and prof["hold_payments"]:continue
                    openamt=invoice_open_v86(c,inv["id"])
                    if openamt<=.005:continue
                    disc=0
                    if prof and prof["early_discount_pct"] and prof["early_discount_days"]:
                        invd=datetime.date.fromisoformat(inv["txn_date"])
                        if datetime.date.fromisoformat(request.form["date"]) <= invd+datetime.timedelta(days=int(prof["early_discount_days"])):
                            disc=openamt*float(prof["early_discount_pct"])/100
                    pay=openamt-disc
                    c.execute("INSERT INTO payment_run_lines_v86(run_id,supplier_id,invoice_ledger_id,due_date,gross_amount,discount_amount,pay_amount) VALUES(?,?,?,?,?,?,?)",(rid,inv["supplier_id"],inv["id"],inv["due_date"],openamt,disc,pay));total+=pay
                c.execute("UPDATE payment_runs_v86 SET total_amount=? WHERE id=?",(total,rid))
            elif a=="approve":
                if session.get("role") not in ("admin","manager"):raise ValueError("اعتماد دفعة السداد للمدير فقط")
                rid=int(request.form["run"]);c.execute("UPDATE payment_runs_v86 SET status='APPROVED',approved_by=?,approved_at=CURRENT_TIMESTAMP WHERE id=? AND status='DRAFT'",(session.get("user",""),rid))
            c.commit();flash("تم تنفيذ العملية")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/payment-runs-v86")
    runs=c.execute("SELECT * FROM payment_runs_v86 ORDER BY id DESC").fetchall()
    lines=c.execute("""SELECT l.*,r.run_no,a.reference FROM payment_run_lines_v86 l JOIN payment_runs_v86 r ON r.id=l.run_id LEFT JOIN ap_ledger_v85 a ON a.id=l.invoice_ledger_id ORDER BY l.id DESC LIMIT 500""").fetchall();c.close()
    rr="".join(f"<tr><td>{x['run_no']}</td><td>{x['run_date']}</td><td>{x['total_amount']:,.2f}</td><td>{x['status']}</td><td><form method=post><input type=hidden name=run value={x['id']}><button name=action value=approve>اعتماد</button></form></td></tr>" for x in runs)
    ll="".join(f"<tr><td>{x['run_no']}</td><td>{x['supplier_id']}</td><td>{html.escape(x['reference'] or '')}</td><td>{x['due_date']}</td><td>{x['gross_amount']:,.2f}</td><td>{x['discount_amount']:,.2f}</td><td>{x['pay_amount']:,.2f}</td></tr>" for x in lines)
    return page(f"""<h1>جدولة واقتراح مدفوعات الموردين v86</h1><form method=post class=panel><input type=hidden name=action value=generate><label>تاريخ Payment Run</label><input type=date name=date value="{datetime.date.today()}" required><label>الفواتير المستحقة حتى</label><input type=date name=cutoff value="{datetime.date.today()}" required><button>اقتراح الفواتير المستحقة</button></form><table><tr><th>Run</th><th>التاريخ</th><th>الإجمالي</th><th>الحالة</th><th></th></tr>{rr}</table><h2>الفواتير المقترحة</h2><table><tr><th>Run</th><th>Supplier</th><th>Invoice</th><th>Due</th><th>Gross</th><th>Discount</th><th>Pay</th></tr>{ll}</table>""")


@app.route("/supplier-tax-v87",methods=["GET","POST"])
def supplier_tax_v87():
    if session.get("role") not in ("admin","manager","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        sid=int(request.form["supplier"])
        c.execute("""INSERT INTO supplier_tax_profiles_v87(supplier_id,vat_no,vat_pct,withholding_pct,withholding_gl,vat_gl,tax_exempt)
        VALUES(?,?,?,?,?,?,?) ON CONFLICT(supplier_id) DO UPDATE SET vat_no=excluded.vat_no,vat_pct=excluded.vat_pct,
        withholding_pct=excluded.withholding_pct,withholding_gl=excluded.withholding_gl,vat_gl=excluded.vat_gl,tax_exempt=excluded.tax_exempt""",
        (sid,request.form.get("vat_no",""),float(request.form.get("vat_pct") or 0),float(request.form.get("wht_pct") or 0),
         request.form.get("wht_gl","2130"),request.form.get("vat_gl","1150"),1 if request.form.get("exempt") else 0))
        c.commit();c.close();flash("تم حفظ ملف ضريبة المورد");return redirect("/supplier-tax-v87")
    sids=[x["supplier_id"] for x in c.execute("SELECT DISTINCT supplier_id FROM ap_ledger_v85 ORDER BY supplier_id").fetchall()]
    rows=c.execute("SELECT * FROM supplier_tax_profiles_v87 ORDER BY supplier_id").fetchall();c.close()
    so="".join(f"<option value='{x}'>{x}</option>" for x in sids)
    rr="".join(f"<tr><td>{x['supplier_id']}</td><td>{html.escape(x['vat_no'] or '')}</td><td>{x['vat_pct']}%</td><td>{x['withholding_pct']}%</td><td>{x['withholding_gl']}</td><td>{'معفى' if x['tax_exempt'] else 'خاضع'}</td></tr>" for x in rows)
    return page(f"""<h1>ضرائب الموردين VAT / Withholding v87</h1><form method=post class=panel><select name=supplier>{so}</select><input name=vat_no placeholder="VAT Number"><input name=vat_pct type=number step=.01 value=15 placeholder="VAT %"><input name=wht_pct type=number step=.01 value=0 placeholder="Withholding %"><input name=wht_gl value="2130" placeholder="WHT GL"><input name=vat_gl value="1150" placeholder="VAT GL"><label><input type=checkbox name=exempt> معفى ضريبياً</label><button>حفظ</button></form><table><tr><th>Supplier</th><th>VAT No</th><th>VAT</th><th>WHT</th><th>WHT GL</th><th>الحالة</th></tr>{rr}</table>""")

@app.route("/payment-execution-v87",methods=["GET","POST"])
def payment_execution_v87():
    if session.get("role") not in ("admin","manager","accountant","treasury"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            rid=int(request.form["run"]);run=c.execute("SELECT * FROM payment_runs_v86 WHERE id=?",(rid,)).fetchone()
            if not run or run["status"]!="APPROVED":raise ValueError("Payment Run يجب أن يكون معتمداً")
            if c.execute("SELECT 1 FROM payment_run_executions_v87 WHERE run_id=?",(rid,)).fetchone():raise ValueError("تم تنفيذ Payment Run مسبقاً")
            typ=request.form["source_type"];sid=int(request.form["source_id"]);date=request.form["date"]
            eno="EXEC-"+datetime.datetime.now().strftime("%Y%m%d%H%M%S%f")
            eid=c.execute("INSERT INTO payment_run_executions_v87(run_id,execution_no,execution_date,source_type,source_id,executed_by) VALUES(?,?,?,?,?,?)",(rid,eno,date,typ,sid,session.get("user",""))).lastrowid
            lines=c.execute("SELECT * FROM payment_run_lines_v86 WHERE run_id=? AND status='SELECTED'",(rid,)).fetchall()
            gross=disc=wht=net=0
            st=c.execute("SELECT * FROM procurement_accounting_settings_v85 WHERE id=1").fetchone()
            for ln in lines:
                prof=c.execute("SELECT * FROM supplier_tax_profiles_v87 WHERE supplier_id=?",(ln["supplier_id"],)).fetchone()
                wh=0 if not prof or prof["tax_exempt"] else float(ln["pay_amount"])*float(prof["withholding_pct"])/100
                pay=max(0,float(ln["pay_amount"])-wh)
                cashgl=st["bank_gl"] if typ=="BANK" else st["cash_gl"]
                entries=[(st["ap_gl"],float(ln["gross_amount"]),0,"تسوية فاتورة مورد")]
                if float(ln["discount_amount"])>0: entries.append((st["purchase_return_gl"],0,float(ln["discount_amount"]),"خصم سداد مبكر"))
                if wh>0: entries.append((prof["withholding_gl"],0,wh,"ضريبة استقطاع"))
                entries.append((cashgl,0,pay,"دفع صافي للمورد"))
                jid=post_proc_je_v85(c,date,"Payment Run "+eno,entries)
                ref=eno+"-S"+str(ln["supplier_id"])+"-L"+str(ln["id"])
                plid=c.execute("INSERT INTO ap_ledger_v85(supplier_id,txn_date,txn_type,source_id,reference,debit,journal_entry_id,status) VALUES(?,?,?,?,?,?,?,'POSTED')",(ln["supplier_id"],date,"PAYMENT_RUN",eid,ref,float(ln["gross_amount"]),jid)).lastrowid
                c.execute("INSERT INTO ap_allocations_v86(supplier_id,payment_ledger_id,invoice_ledger_id,amount,allocated_by) VALUES(?,?,?,?,?)",(ln["supplier_id"],plid,ln["invoice_ledger_id"],float(ln["gross_amount"]),session.get("user","")))
                xlid=c.execute("""INSERT INTO payment_run_execution_lines_v87(execution_id,run_line_id,supplier_id,invoice_ledger_id,gross_amount,discount_amount,withholding_amount,net_amount,payment_ledger_id,journal_entry_id,reference)
                VALUES(?,?,?,?,?,?,?,?,?,?,?)""",(eid,ln["id"],ln["supplier_id"],ln["invoice_ledger_id"],ln["gross_amount"],ln["discount_amount"],wh,pay,plid,jid,ref)).lastrowid
                c.execute("INSERT INTO remittance_advice_v87(execution_line_id,advice_no,generated_by) VALUES(?,?,?)",(xlid,"RA-"+ref,session.get("user","")))
                c.execute("UPDATE payment_run_lines_v86 SET status='PAID' WHERE id=?",(ln["id"],))
                gross+=float(ln["gross_amount"]);disc+=float(ln["discount_amount"]);wht+=wh;net+=pay
            c.execute("UPDATE payment_run_executions_v87 SET gross_amount=?,discount_amount=?,withholding_amount=?,net_amount=?,bank_file_name=? WHERE id=?",(gross,disc,wht,net,eno+".csv",eid))
            c.execute("UPDATE payment_runs_v86 SET status='EXECUTED' WHERE id=?",(rid,))
            c.commit();flash("تم تنفيذ Payment Run وإنشاء القيود")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/payment-execution-v87")
    runs=c.execute("SELECT * FROM payment_runs_v86 WHERE status='APPROVED' ORDER BY id DESC").fetchall()
    execs=c.execute("SELECT * FROM payment_run_executions_v87 ORDER BY id DESC").fetchall();c.close()
    ro="".join(f"<option value='{x['id']}'>{x['run_no']} — {x['total_amount']:,.2f}</option>" for x in runs)
    rr="".join(f"<tr><td>{x['execution_no']}</td><td>{x['execution_date']}</td><td>{x['gross_amount']:,.2f}</td><td>{x['discount_amount']:,.2f}</td><td>{x['withholding_amount']:,.2f}</td><td>{x['net_amount']:,.2f}</td><td><a href='/payment-bank-file-v87/{x['id']}'>CSV</a> | <a href='/iso20022-v88/{x['id']}'>ISO 20022</a> | <a href='/remittance-v87/{x['id']}'>Remittance</a></td></tr>" for x in execs)
    return page(f"""<h1>تنفيذ Payment Run الجماعي v87</h1><form method=post class=panel><select name=run>{ro}</select><input type=date name=date value="{datetime.date.today()}" required><select name=source_type><option>BANK</option><option>CASH</option></select><input name=source_id type=number required placeholder="Bank/Cash ID"><button>تنفيذ Payment Run</button></form><table><tr><th>Execution</th><th>التاريخ</th><th>Gross</th><th>Discount</th><th>WHT</th><th>Net</th><th>ملفات</th></tr>{rr}</table>""")

@app.route("/payment-bank-file-v87/<int:eid>")
def payment_bank_file_v87(eid):
    if session.get("role") not in ("admin","manager","accountant","treasury"):return ("غير مصرح",403)
    import csv,io
    c=con();e=c.execute("SELECT * FROM payment_run_executions_v87 WHERE id=?",(eid,)).fetchone()
    rows=c.execute("SELECT * FROM payment_run_execution_lines_v87 WHERE execution_id=? ORDER BY id",(eid,)).fetchall();c.close()
    if not e:return ("غير موجود",404)
    out=io.StringIO();w=csv.writer(out);w.writerow(["Execution","Supplier","InvoiceLedgerID","Gross","Discount","Withholding","Net","Reference"])
    for x in rows:w.writerow([e["execution_no"],x["supplier_id"],x["invoice_ledger_id"],x["gross_amount"],x["discount_amount"],x["withholding_amount"],x["net_amount"],x["reference"]])
    return Response("\ufeff"+out.getvalue(),mimetype="text/csv",headers={"Content-Disposition":f"attachment; filename={e['execution_no']}.csv"})

@app.route("/remittance-v87/<int:eid>")
def remittance_v87(eid):
    if session.get("role") not in ("admin","manager","accountant","treasury","auditor"):return ("غير مصرح",403)
    c=con();e=c.execute("SELECT * FROM payment_run_executions_v87 WHERE id=?",(eid,)).fetchone()
    rows=c.execute("""SELECT l.*,r.advice_no,a.reference invoice_ref FROM payment_run_execution_lines_v87 l
    LEFT JOIN remittance_advice_v87 r ON r.execution_line_id=l.id LEFT JOIN ap_ledger_v85 a ON a.id=l.invoice_ledger_id
    WHERE l.execution_id=? ORDER BY l.supplier_id""",(eid,)).fetchall();c.close()
    rr="".join(f"<tr><td>{x['advice_no']}</td><td>{x['supplier_id']}</td><td>{html.escape(x['invoice_ref'] or '')}</td><td>{x['gross_amount']:,.2f}</td><td>{x['discount_amount']:,.2f}</td><td>{x['withholding_amount']:,.2f}</td><td>{x['net_amount']:,.2f}</td><td>{x['reference']}</td></tr>" for x in rows)
    return page(f"""<h1>Remittance Advice — {e['execution_no'] if e else ''}</h1><table><tr><th>Advice</th><th>Supplier</th><th>Invoice</th><th>Gross</th><th>Discount</th><th>WHT</th><th>Net Paid</th><th>Reference</th></tr>{rr}</table>""")

@app.route("/bank-reconciliation-v87",methods=["GET","POST"])
def bank_reconciliation_v87():
    if session.get("role") not in ("admin","manager","accountant","treasury","auditor"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            lid=int(request.form["line"]);line=c.execute("SELECT * FROM payment_run_execution_lines_v87 WHERE id=?",(lid,)).fetchone()
            if not line:raise ValueError("سطر الدفع غير موجود")
            amt=float(request.form["amount"]);tol=float(request.form.get("tolerance") or .01)
            status="MATCHED" if abs(amt-float(line["net_amount"]))<=tol else "MISMATCH"
            c.execute("""INSERT INTO bank_reconciliation_v87(execution_line_id,bank_reference,bank_date,bank_amount,status,matched_by,matched_at,notes)
            VALUES(?,?,?,?,?,?,CURRENT_TIMESTAMP,?)""",(lid,request.form["bank_ref"],request.form["date"],amt,status,session.get("user",""),request.form.get("notes","")))
            c.commit();flash("تمت المطابقة: "+status)
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/bank-reconciliation-v87")
    lines=c.execute("""SELECT l.*,e.execution_no FROM payment_run_execution_lines_v87 l JOIN payment_run_executions_v87 e ON e.id=l.execution_id ORDER BY l.id DESC""").fetchall()
