@app.route("/banking-v88",methods=["GET","POST"])
def banking_v88():
    if session.get("role") not in ("admin","manager","accountant","treasury"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="supplier_bank":
                sid=int(request.form["supplier"])
                iban="".join(request.form["iban"].split()).upper()
                if len(iban)<15:raise ValueError("IBAN غير صحيح")
                c.execute("""INSERT INTO supplier_bank_profiles_v88(supplier_id,beneficiary_name,iban,swift_bic,bank_name,country_code,currency,active)
                VALUES(?,?,?,?,?,?,?,1) ON CONFLICT(supplier_id) DO UPDATE SET beneficiary_name=excluded.beneficiary_name,iban=excluded.iban,
                swift_bic=excluded.swift_bic,bank_name=excluded.bank_name,country_code=excluded.country_code,currency=excluded.currency,active=1""",
                (sid,request.form["name"],iban,request.form.get("swift","").upper(),request.form.get("bank",""),request.form.get("country","SA").upper(),request.form.get("currency","SAR").upper()))
            elif a=="approval":
                rid=int(request.form["run"]);run=c.execute("SELECT * FROM payment_runs_v86 WHERE id=?",(rid,)).fetchone()
                if not run:raise ValueError("Payment Run غير موجود")
                levels=c.execute("SELECT * FROM payment_approval_levels_v88 WHERE active=1 AND ? BETWEEN min_amount AND max_amount ORDER BY level_no",(run["total_amount"],)).fetchall()
                for lv in levels:
                    c.execute("INSERT OR IGNORE INTO payment_batch_approvals_v88(run_id,level_no) VALUES(?,?)",(rid,lv["level_no"]))
                pending=c.execute("""SELECT a.*,l.required_role FROM payment_batch_approvals_v88 a JOIN payment_approval_levels_v88 l ON l.level_no=a.level_no
                    WHERE a.run_id=? AND a.status='PENDING' ORDER BY a.level_no LIMIT 1""",(rid,)).fetchone()
                if not pending:raise ValueError("لا توجد موافقة معلقة")
                role=session.get("role")
                if role not in ("admin",pending["required_role"]):raise ValueError("ليس لديك صلاحية مستوى الاعتماد الحالي")
                c.execute("UPDATE payment_batch_approvals_v88 SET status='APPROVED',approved_by=?,approved_at=CURRENT_TIMESTAMP,notes=? WHERE id=?",(session.get("user",""),request.form.get("notes",""),pending["id"]))
                left=c.execute("SELECT count(*) n FROM payment_batch_approvals_v88 WHERE run_id=? AND status='PENDING'",(rid,)).fetchone()["n"]
                if left==0:c.execute("UPDATE payment_runs_v86 SET status='APPROVED' WHERE id=?",(rid,))
            c.commit();flash("تم تنفيذ العملية")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/banking-v88")
    sids=[x["supplier_id"] for x in c.execute("SELECT DISTINCT supplier_id FROM ap_ledger_v85 ORDER BY supplier_id").fetchall()]
    profiles=c.execute("SELECT * FROM supplier_bank_profiles_v88 ORDER BY supplier_id").fetchall()
    runs=c.execute("SELECT * FROM payment_runs_v86 WHERE status IN ('DRAFT','APPROVED') ORDER BY id DESC").fetchall()
    approvals=c.execute("""SELECT a.*,r.run_no,l.level_name,l.required_role FROM payment_batch_approvals_v88 a JOIN payment_runs_v86 r ON r.id=a.run_id JOIN payment_approval_levels_v88 l ON l.level_no=a.level_no ORDER BY a.id DESC""").fetchall();c.close()
    so="".join(f"<option value='{x}'>{x}</option>" for x in sids);ro="".join(f"<option value='{x['id']}'>{x['run_no']} — {x['total_amount']:,.2f} — {x['status']}</option>" for x in runs)
    pr="".join(f"<tr><td>{x['supplier_id']}</td><td>{html.escape(x['beneficiary_name'])}</td><td>{html.escape(x['iban'])}</td><td>{html.escape(x['swift_bic'] or '')}</td><td>{html.escape(x['bank_name'] or '')}</td></tr>" for x in profiles)
    ar="".join(f"<tr><td>{x['run_no']}</td><td>{x['level_name']}</td><td>{x['required_role']}</td><td>{x['status']}</td><td>{x['approved_by'] or ''}</td></tr>" for x in approvals)
    return page(f"""<h1>المدفوعات البنكية الاحترافية v88</h1>
    <form method=post class=panel><input type=hidden name=action value=supplier_bank><select name=supplier>{so}</select><input name=name required placeholder="Beneficiary Name"><input name=iban required placeholder="IBAN"><input name=swift placeholder="SWIFT/BIC"><input name=bank placeholder="Bank Name"><input name=country value="SA"><input name=currency value="SAR"><button>حفظ بيانات البنك</button></form>
    <form method=post class=panel><input type=hidden name=action value=approval><select name=run>{ro}</select><input name=notes placeholder="ملاحظة الاعتماد"><button>اعتماد المستوى التالي</button></form>
    <h2>حسابات الموردين البنكية</h2><table><tr><th>Supplier</th><th>Beneficiary</th><th>IBAN</th><th>SWIFT</th><th>Bank</th></tr>{pr}</table>
    <h2>سجل الاعتمادات</h2><table><tr><th>Run</th><th>Level</th><th>Role</th><th>Status</th><th>Approved By</th></tr>{ar}</table>""")

@app.route("/iso20022-v88/<int:eid>")
def iso20022_v88(eid):
    if session.get("role") not in ("admin","manager","accountant","treasury"):return ("غير مصرح",403)
    import xml.etree.ElementTree as ET
    c=con();e=c.execute("SELECT * FROM payment_run_executions_v87 WHERE id=?",(eid,)).fetchone()
    lines=c.execute("SELECT * FROM payment_run_execution_lines_v87 WHERE execution_id=? ORDER BY id",(eid,)).fetchall()
    if not e:c.close();return ("غير موجود",404)
    rootx=ET.Element("Document");cst=ET.SubElement(rootx,"CstmrCdtTrfInitn");hdr=ET.SubElement(cst,"GrpHdr")
    ET.SubElement(hdr,"MsgId").text=e["execution_no"];ET.SubElement(hdr,"CreDtTm").text=datetime.datetime.now().isoformat()
    ET.SubElement(hdr,"NbOfTxs").text=str(len(lines));ET.SubElement(hdr,"CtrlSum").text=f"{e['net_amount']:.2f}"
    pmt=ET.SubElement(cst,"PmtInf");ET.SubElement(pmt,"PmtInfId").text=e["execution_no"];ET.SubElement(pmt,"PmtMtd").text="TRF"
    for x in lines:
        bp=c.execute("SELECT * FROM supplier_bank_profiles_v88 WHERE supplier_id=?",(x["supplier_id"],)).fetchone()
        tx=ET.SubElement(pmt,"CdtTrfTxInf");pid=ET.SubElement(tx,"PmtId");ET.SubElement(pid,"EndToEndId").text=x["reference"]
        amt=ET.SubElement(tx,"Amt");ia=ET.SubElement(amt,"InstdAmt",Ccy=(bp["currency"] if bp else "SAR"));ia.text=f"{x['net_amount']:.2f}"
        cd=ET.SubElement(tx,"Cdtr");ET.SubElement(cd,"Nm").text=(bp["beneficiary_name"] if bp else "Supplier "+str(x["supplier_id"]))
        ca=ET.SubElement(tx,"CdtrAcct");iid=ET.SubElement(ca,"Id");ET.SubElement(iid,"IBAN").text=(bp["iban"] if bp else "")
        ag=ET.SubElement(tx,"CdtrAgt");fi=ET.SubElement(ag,"FinInstnId");ET.SubElement(fi,"BIC").text=(bp["swift_bic"] if bp else "")
    c.close();xml=ET.tostring(rootx,encoding="utf-8",xml_declaration=True)
    return Response(xml,mimetype="application/xml",headers={"Content-Disposition":f"attachment; filename={e['execution_no']}_pain001.xml"})

@app.route("/statement-import-v88",methods=["GET","POST"])
def statement_import_v88():
    if session.get("role") not in ("admin","manager","accountant","treasury"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            import csv,io
            f=request.files.get("file")
            if not f:raise ValueError("اختر ملف CSV")
            text=f.read().decode("utf-8-sig")
            rows=list(csv.DictReader(io.StringIO(text)));iid=c.execute("INSERT INTO bank_statement_imports_v88(file_name,bank_account_id,statement_date,imported_rows,imported_by) VALUES(?,?,?,?,?)",(f.filename,int(request.form["bank"]),request.form["date"],len(rows),session.get("user",""))).lastrowid
            for r in rows:
                ref=str(r.get("reference","")).strip();desc=str(r.get("description","")).strip();amt=float(str(r.get("amount","0")).replace(",",""));date=r.get("date") or request.form["date"]
                candidates=c.execute("SELECT * FROM payment_run_execution_lines_v87 WHERE ABS(net_amount-?)<=? ORDER BY id DESC",(abs(amt),float(request.form.get("tolerance") or .01))).fetchall()
                best=None;score=0
                for x in candidates:
                    sc=60
                    if x["reference"] and x["reference"].lower() in (ref+" "+desc).lower():sc=100
                    elif str(x["supplier_id"]) in (ref+" "+desc):sc=80
                    if sc>score:best=x;score=sc
                status="AUTO_MATCHED" if best and score>=80 else "SUGGESTED" if best else "UNMATCHED"
                lid=c.execute("""INSERT INTO bank_statement_lines_v88(import_id,txn_date,value_date,reference,description,amount,currency,status,matched_execution_line_id,match_score)
                VALUES(?,?,?,?,?,?,?,?,?,?)""",(iid,date,r.get("value_date") or date,ref,desc,amt,r.get("currency") or "SAR",status,best["id"] if best else None,score)).lastrowid
                if status!="AUTO_MATCHED":
                    c.execute("INSERT INTO bank_payment_exceptions_v88(statement_line_id,exception_type,details) VALUES(?,?,?)",(lid,status,"يتطلب مراجعة المطابقة البنكية"))
            c.commit();flash(f"تم استيراد {len(rows)} حركة وتشغيل Auto-Matching")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/statement-import-v88")
    banks=c.execute("SELECT * FROM bank_accounts_v73 WHERE active=1").fetchall()
    rows=c.execute("SELECT * FROM bank_statement_lines_v88 ORDER BY id DESC LIMIT 500").fetchall();c.close()
    bo="".join(f"<option value='{x['id']}'>{x['bank_name']} / {x['account_name']}</option>" for x in banks)
    rr="".join(f"<tr><td>{x['txn_date']}</td><td>{html.escape(x['reference'] or '')}</td><td>{html.escape(x['description'] or '')}</td><td>{x['amount']:,.2f}</td><td>{x['status']}</td><td>{x['match_score']:.0f}%</td></tr>" for x in rows)
    return page(f"""<h1>استيراد كشف البنك وAuto-Matching v88</h1><div class=panel>CSV columns: date,value_date,reference,description,amount,currency</div><form method=post enctype=multipart/form-data class=panel><select name=bank>{bo}</select><input type=date name=date value="{datetime.date.today()}" required><input type=file name=file accept=".csv" required><input name=tolerance type=number step=.01 value=.01><button>استيراد وتشغيل المطابقة</button></form><table><tr><th>Date</th><th>Reference</th><th>Description</th><th>Amount</th><th>Status</th><th>Score</th></tr>{rr}</table>""")

