    st=c.execute("SELECT * FROM liquidity_settings_v89 WHERE id=1").fetchone();sc=c.execute("SELECT * FROM liquidity_scenarios_v89 WHERE active=1 ORDER BY id").fetchall();flows=c.execute("SELECT * FROM liquidity_manual_flows_v89 ORDER BY flow_date DESC,id DESC LIMIT 200").fetchall();c.close()
