    fr="".join(f"<tr><td>{x['flow_date']}</td><td>{x['flow_type']}</td><td>{html.escape(x['category'])}</td><td>{x['amount']:,.2f}</td><td>{x['probability']:.0f}%</td><td>{x['scenario']}</td></tr>" for x in flows)
