                prior=float(c.execute("SELECT coalesce(sum(total_cost),0) x FROM mrp_fg_receipts_v95 WHERE mo_id=?",(mid,)).fetchone()["x"]);available=max(0,mat+labor-prior);unit=available/qty if qty else 0
