@app.route("/manufacturing-cost-v95")
def manufacturing_cost_v95():
    if session.get("role") not in ("admin","manager","production","accountant","auditor"):return ("غير مصرح",403)
    c=con();mos=c.execute("SELECT * FROM mrp_production_orders_v95 ORDER BY id DESC").fetchall();rows=[]
    for m in mos:
        mat=float(c.execute("SELECT coalesce(sum(total_cost),0) x FROM mrp_material_issues_v95 WHERE mo_id=?",(m["id"],)).fetchone()["x"])
        labor=float(c.execute("SELECT coalesce(sum(o.actual_hours*w.hourly_rate),0) x FROM mrp_operations_v95 o JOIN mrp_work_centers_v95 w ON w.id=o.work_center_id WHERE o.mo_id=?",(m["id"],)).fetchone()["x"])
        stdmat=float(c.execute("SELECT coalesce(sum(required_qty*standard_unit_cost),0) x FROM mrp_material_requirements_v95 WHERE mo_id=?",(m["id"],)).fetchone()["x"])
        plannedlabor=float(c.execute("SELECT coalesce(sum(o.planned_hours*w.hourly_rate),0) x FROM mrp_operations_v95 o JOIN mrp_work_centers_v95 w ON w.id=o.work_center_id WHERE o.mo_id=?",(m["id"],)).fetchone()["x"])
        rows.append((m,mat,labor,stdmat+plannedlabor,(mat+labor)-(stdmat+plannedlabor)))
    c.close();rr="".join(f"<tr><td>{m['mo_no']}</td><td>{m['finished_item']}</td><td>{mat:,.2f}</td><td>{labor:,.2f}</td><td>{mat+labor:,.2f}</td><td>{std:,.2f}</td><td>{var:,.2f}</td><td>{(mat+labor)/m['completed_qty'] if m['completed_qty'] else 0:,.2f}</td></tr>" for m,mat,labor,std,var in rows)
    return page(f"""<h1>Manufacturing Cost & Variance v95</h1><table><tr><th>MO</th><th>Item</th><th>Material</th><th>Labor</th><th>Actual</th><th>Standard</th><th>Variance</th><th>Actual/Unit</th></tr>{rr}</table>""")

@app.route("/capacity-v95")
def capacity_v95():
    if session.get("role") not in ("admin","manager","production","auditor"):return ("غير مصرح",403)
    c=con();wcs=c.execute("SELECT * FROM mrp_work_centers_v95 WHERE active=1 ORDER BY code").fetchall();rows=[]
    for w in wcs:
        req=float(c.execute("""SELECT coalesce(sum(o.planned_hours-o.actual_hours),0) x FROM mrp_operations_v95 o JOIN mrp_production_orders_v95 m ON m.id=o.mo_id WHERE o.work_center_id=? AND m.status NOT IN ('COMPLETED','CANCELLED')""",(w["id"],)).fetchone()["x"])
        avail=float(w["capacity_hours_day"])*float(w["efficiency_pct"])/100
        rows.append((w,avail,req,req/avail if avail else 0))
    c.close();rr="".join(f"<tr><td>{x['code']}</td><td>{html.escape(x['name'])}</td><td>{a:.2f}</td><td>{r:.2f}</td><td>{load*100:.1f}%</td><td>{'OVERLOAD' if load>1 else 'OK'}</td></tr>" for x,a,r,load in rows)
    return page(f"""<h1>Capacity Planning v95</h1><table><tr><th>Work Center</th><th>Name</th><th>Daily Effective Capacity</th><th>Open Required Hours</th><th>Load</th><th>Status</th></tr>{rr}</table>""")


