@app.route("/attendance-v97",methods=["GET","POST"])
def attendance_v97():
    if session.get("role") not in ("admin","manager","hr"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="attendance":
                eid=int(request.form["employee"]);date=request.form["date"];cin=request.form.get("check_in","");cout=request.form.get("check_out","")
                worked=float(request.form.get("worked") or 0);ot=float(request.form.get("overtime") or 0);late=int(request.form.get("late") or 0)
                c.execute("""INSERT INTO hr_attendance_v97(employee_id,attendance_date,check_in,check_out,worked_hours,overtime_hours,late_minutes,status)
                VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(employee_id,attendance_date) DO UPDATE SET check_in=excluded.check_in,check_out=excluded.check_out,worked_hours=excluded.worked_hours,overtime_hours=excluded.overtime_hours,late_minutes=excluded.late_minutes,status=excluded.status""",(eid,date,cin,cout,worked,ot,late,request.form["status"]))
            elif a=="leave":
                start=datetime.date.fromisoformat(request.form["start"]);end=datetime.date.fromisoformat(request.form["end"])
                days=(end-start).days+1
                if days<=0:raise ValueError("تواريخ الإجازة غير صحيحة")
                c.execute("INSERT INTO hr_leave_requests_v97(employee_id,leave_type_id,start_date,end_date,days,reason) VALUES(?,?,?,?,?,?)",(int(request.form["employee"]),int(request.form["leave_type"]),str(start),str(end),days,request.form.get("reason","")))
            elif a=="approve_leave":
                c.execute("UPDATE hr_leave_requests_v97 SET status='APPROVED',approved_by=? WHERE id=?",(session.get("user",""),int(request.form["leave"])))
            c.commit();flash("تم تحديث الحضور والإجازات")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/attendance-v97")
    emps=c.execute("SELECT * FROM hr_employees_v97 WHERE status='ACTIVE'").fetchall();lts=c.execute("SELECT * FROM hr_leave_types_v97").fetchall();att=c.execute("SELECT a.*,e.employee_no,e.name FROM hr_attendance_v97 a JOIN hr_employees_v97 e ON e.id=a.employee_id ORDER BY a.attendance_date DESC,a.id DESC LIMIT 500").fetchall();leaves=c.execute("SELECT l.*,e.employee_no,t.name leave_name FROM hr_leave_requests_v97 l JOIN hr_employees_v97 e ON e.id=l.employee_id JOIN hr_leave_types_v97 t ON t.id=l.leave_type_id ORDER BY l.id DESC").fetchall();c.close()
    eo="".join(f"<option value='{x['id']}'>{x['employee_no']} — {html.escape(x['name'])}</option>" for x in emps);lo="".join(f"<option value='{x['id']}'>{html.escape(x['name'])}</option>" for x in lts);lro="".join(f"<option value='{x['id']}'>{x['employee_no']} / {x['start_date']} / {x['status']}</option>" for x in leaves)
    ar="".join(f"<tr><td>{x['attendance_date']}</td><td>{x['employee_no']}</td><td>{html.escape(x['name'])}</td><td>{x['check_in'] or ''}</td><td>{x['check_out'] or ''}</td><td>{x['worked_hours']:.2f}</td><td>{x['overtime_hours']:.2f}</td><td>{x['late_minutes']}</td><td>{x['status']}</td></tr>" for x in att)
    lr="".join(f"<tr><td>{x['employee_no']}</td><td>{html.escape(x['leave_name'])}</td><td>{x['start_date']}</td><td>{x['end_date']}</td><td>{x['days']}</td><td>{x['status']}</td></tr>" for x in leaves)
    return page(f"""<h1>Attendance / Leave v97</h1><form method=post class=panel><input type=hidden name=action value=attendance><select name=employee>{eo}</select><input type=date name=date value="{datetime.date.today()}" required><input type=time name=check_in><input type=time name=check_out><input name=worked type=number step=.01 value=8 placeholder="Worked Hours"><input name=overtime type=number step=.01 value=0 placeholder="Overtime"><input name=late type=number value=0 placeholder="Late Minutes"><select name=status><option>PRESENT</option><option>ABSENT</option><option>REMOTE</option><option>LEAVE</option></select><button>حفظ الحضور</button></form><form method=post class=panel><input type=hidden name=action value=leave><select name=employee>{eo}</select><select name=leave_type>{lo}</select><input type=date name=start required><input type=date name=end required><input name=reason placeholder="Reason"><button>طلب إجازة</button></form><form method=post class=panel><select name=leave>{lro}</select><button name=action value=approve_leave>اعتماد الإجازة</button></form><h2>Attendance</h2><table><tr><th>Date</th><th>No</th><th>Name</th><th>In</th><th>Out</th><th>Worked</th><th>OT</th><th>Late</th><th>Status</th></tr>{ar}</table><h2>Leaves</h2><table><tr><th>Employee</th><th>Type</th><th>Start</th><th>End</th><th>Days</th><th>Status</th></tr>{lr}</table>""")

@app.route("/payroll-v97",methods=["GET","POST"])
def payroll_v97():
    if session.get("role") not in ("admin","manager","hr","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="period":
                c.execute("INSERT INTO hr_payroll_periods_v97(period_code,start_date,end_date,pay_date) VALUES(?,?,?,?)",(request.form["code"],request.form["start"],request.form["end"],request.form["pay"]))
            elif a=="adjustment":
                c.execute("INSERT INTO hr_employee_adjustments_v97(employee_id,period_id,adjustment_type,description,amount) VALUES(?,?,?,?,?)",(int(request.form["employee"]),int(request.form["period"]),request.form["type"],request.form.get("description",""),float(request.form["amount"])))
            elif a=="calculate":
                pid=int(request.form["period"]);p=c.execute("SELECT * FROM hr_payroll_periods_v97 WHERE id=?",(pid,)).fetchone();st=c.execute("SELECT * FROM hr_payroll_settings_v97 WHERE id=1").fetchone()
                for e in c.execute("SELECT * FROM hr_employees_v97 WHERE status='ACTIVE'").fetchall():
                    basic=float(e["basic_salary"]);housing=float(e["housing_allowance"]);transport=float(e["transport_allowance"]);other=float(e["other_allowance"])
                    ot_hours=float(c.execute("SELECT coalesce(sum(overtime_hours),0) x FROM hr_attendance_v97 WHERE employee_id=? AND attendance_date BETWEEN ? AND ?",(e["id"],p["start_date"],p["end_date"])).fetchone()["x"])
                    hourly=basic/30/8 if basic else 0;overtime=ot_hours*hourly*float(st["overtime_multiplier"])
                    absent=float(c.execute("SELECT count(*) n FROM hr_attendance_v97 WHERE employee_id=? AND attendance_date BETWEEN ? AND ? AND status='ABSENT'",(e["id"],p["start_date"],p["end_date"])).fetchone()["n"])
                    absence=absent*(basic/30)
                    adj=c.execute("SELECT adjustment_type,coalesce(sum(amount),0) x FROM hr_employee_adjustments_v97 WHERE employee_id=? AND period_id=? GROUP BY adjustment_type",(e["id"],pid)).fetchall()
                    allowance=sum(float(x["x"]) for x in adj if x["adjustment_type"]=="ALLOWANCE");ded=sum(float(x["x"]) for x in adj if x["adjustment_type"]=="DEDUCTION")
                    gross=basic+housing+transport+other+overtime+allowance;gosi_emp=basic*float(e["gosi_employee_pct"])/100;gosi_company=basic*float(e["gosi_employer_pct"])/100;net=gross-gosi_emp-absence-ded
                    c.execute("""INSERT INTO hr_payroll_lines_v97(period_id,employee_id,basic,housing,transport,other_allowance,overtime,gross,gosi_employee,absence_deduction,other_deduction,net_pay,gosi_employer)
                    VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?) ON CONFLICT(period_id,employee_id) DO UPDATE SET basic=excluded.basic,housing=excluded.housing,transport=excluded.transport,other_allowance=excluded.other_allowance,overtime=excluded.overtime,gross=excluded.gross,gosi_employee=excluded.gosi_employee,absence_deduction=excluded.absence_deduction,other_deduction=excluded.other_deduction,net_pay=excluded.net_pay,gosi_employer=excluded.gosi_employer""",(pid,e["id"],basic,housing,transport,other+allowance,overtime,gross,gosi_emp,absence,ded,net,gosi_company))
            elif a=="post":
                pid=int(request.form["period"]);p=c.execute("SELECT * FROM hr_payroll_periods_v97 WHERE id=?",(pid,)).fetchone()
                if p["status"]=="POSTED":raise ValueError("تم ترحيل الفترة مسبقاً")
                x=c.execute("SELECT coalesce(sum(gross),0) gross,coalesce(sum(gosi_employer),0) ge,coalesce(sum(net_pay),0) net,coalesce(sum(gosi_employee),0) gu FROM hr_payroll_lines_v97 WHERE period_id=?",(pid,)).fetchone();st=c.execute("SELECT * FROM hr_payroll_settings_v97 WHERE id=1").fetchone()
                entries=[(st["salary_expense_gl"],float(x["gross"]),0,"Payroll Expense"),(st["gosi_expense_gl"],float(x["ge"]),0,"Employer GOSI"),(st["payroll_payable_gl"],0,float(x["net"]),"Payroll Payable"),(st["gosi_payable_gl"],0,float(x["gu"])+float(x["ge"]),"GOSI Payable")]
                diff=sum(a-b for _,a,b,_ in entries)
                if abs(diff)>.01: entries.append((st["salary_expense_gl"],0,diff,"Payroll balancing") if diff>0 else (st["salary_expense_gl"],-diff,0,"Payroll balancing"))
                post_proc_je_v85(c,p["end_date"],"Payroll "+p["period_code"],entries);c.execute("UPDATE hr_payroll_periods_v97 SET status='POSTED' WHERE id=?",(pid,))
            c.commit();flash("تم تنفيذ عملية الرواتب")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/payroll-v97")
    periods=c.execute("SELECT * FROM hr_payroll_periods_v97 ORDER BY id DESC").fetchall();emps=c.execute("SELECT * FROM hr_employees_v97 WHERE status='ACTIVE'").fetchall();lines=c.execute("SELECT l.*,e.employee_no,e.name,p.period_code FROM hr_payroll_lines_v97 l JOIN hr_employees_v97 e ON e.id=l.employee_id JOIN hr_payroll_periods_v97 p ON p.id=l.period_id ORDER BY l.id DESC").fetchall();c.close()
    po="".join(f"<option value='{x['id']}'>{x['period_code']} — {x['status']}</option>" for x in periods);eo="".join(f"<option value='{x['id']}'>{x['employee_no']} — {html.escape(x['name'])}</option>" for x in emps)
    rr="".join(f"<tr><td>{x['period_code']}</td><td>{x['employee_no']}</td><td>{html.escape(x['name'])}</td><td>{x['gross']:,.2f}</td><td>{x['overtime']:,.2f}</td><td>{x['gosi_employee']:,.2f}</td><td>{x['absence_deduction']:,.2f}</td><td>{x['other_deduction']:,.2f}</td><td>{x['net_pay']:,.2f}</td></tr>" for x in lines)
    return page(f"""<h1>Payroll v97</h1><form method=post class=panel><input type=hidden name=action value=period><input name=code required placeholder="Period e.g. 2026-10"><input type=date name=start required><input type=date name=end required><input type=date name=pay required><button>إنشاء فترة رواتب</button></form><form method=post class=panel><input type=hidden name=action value=adjustment><select name=period>{po}</select><select name=employee>{eo}</select><select name=type><option>ALLOWANCE</option><option>DEDUCTION</option></select><input name=description placeholder="Description"><input name=amount type=number step=.01 required><button>إضافة بدل/خصم</button></form><form method=post class=panel><select name=period>{po}</select><button name=action value=calculate>احتساب Payroll</button><button name=action value=post>ترحيل إلى GL</button></form><table><tr><th>Period</th><th>Employee</th><th>Name</th><th>Gross</th><th>OT</th><th>GOSI Emp</th><th>Absence</th><th>Other Ded.</th><th>Net</th></tr>{rr}</table>""")

@app.route("/eosb-v97",methods=["GET","POST"])
def eosb_v97():
    if session.get("role") not in ("admin","manager","hr","accountant","auditor"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            eid=int(request.form["employee"]);d=datetime.date.fromisoformat(request.form["date"]);e=c.execute("SELECT * FROM hr_employees_v97 WHERE id=?",(eid,)).fetchone();hire=datetime.date.fromisoformat(e["hire_date"]);years=max(0,(d-hire).days/365.25);basis=float(e["basic_salary"])+float(e["housing_allowance"])
            benefit=basis*.5*min(years,5)+basis*max(years-5,0)
            c.execute("INSERT INTO hr_eosb_v97(employee_id,calculation_date,service_years,basis_salary,estimated_benefit,notes) VALUES(?,?,?,?,?,?)",(eid,str(d),years,basis,benefit,request.form.get("notes","")))
            c.commit();flash("تم احتساب تقدير نهاية الخدمة")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/eosb-v97")
    emps=c.execute("SELECT * FROM hr_employees_v97 WHERE status='ACTIVE'").fetchall();rows=c.execute("SELECT x.*,e.employee_no,e.name FROM hr_eosb_v97 x JOIN hr_employees_v97 e ON e.id=x.employee_id ORDER BY x.id DESC").fetchall();c.close()
    eo="".join(f"<option value='{x['id']}'>{x['employee_no']} — {html.escape(x['name'])}</option>" for x in emps);rr="".join(f"<tr><td>{x['employee_no']}</td><td>{html.escape(x['name'])}</td><td>{x['calculation_date']}</td><td>{x['service_years']:.2f}</td><td>{x['basis_salary']:,.2f}</td><td>{x['estimated_benefit']:,.2f}</td></tr>" for x in rows)
    return page(f"""<h1>End of Service Benefit v97</h1><p class=panel>هذا تقدير داخلي مبسط ويجب مراجعة سياسة الشركة والمتطلبات النظامية قبل الاعتماد النهائي.</p><form method=post class=panel><select name=employee>{eo}</select><input type=date name=date value="{datetime.date.today()}" required><input name=notes placeholder="Notes"><button>احتساب EOSB</button></form><table><tr><th>Employee</th><th>Name</th><th>Date</th><th>Years</th><th>Basis</th><th>Estimated Benefit</th></tr>{rr}</table>""")


@app.route('/projects-v98',methods=['GET','POST'])
def projects_v98():
    if session.get('role') not in ('admin','manager','project','sales','accountant','hr'): return ('غير مصرح',403)
    c=con()
    if request.method=='POST':
      try:
       a=request.form['action']
       if a=='project':
        no='PRJ-'+datetime.datetime.now().strftime('%Y%m%d%H%M%S%f'); c.execute('INSERT INTO projects_v98(project_no,name,customer_id,manager,start_date,end_date,budget_revenue,budget_cost,cost_center) VALUES(?,?,?,?,?,?,?,?,?)',(no,request.form['name'],int(request.form['customer']),request.form.get('manager',''),request.form['start'],request.form['end'],float(request.form.get('revenue') or 0),float(request.form.get('cost') or 0),request.form.get('cost_center','')))
       elif a=='task': c.execute('INSERT INTO project_tasks_v98(project_id,task_no,name,assigned_to,start_date,due_date,planned_hours) VALUES(?,?,?,?,?,?,?)',(int(request.form['project']),request.form['task_no'],request.form['name'],int(request.form['employee']) if request.form.get('employee') else None,request.form['start'],request.form['due'],float(request.form.get('hours') or 0)))
       elif a=='timesheet':
        eid=int(request.form['employee']); e=c.execute('SELECT * FROM hr_employees_v97 WHERE id=?',(eid,)).fetchone(); rate=float(e['basic_salary'])/240 if e and e['basic_salary'] else 0; c.execute('INSERT INTO project_timesheets_v98(project_id,task_id,employee_id,work_date,hours,hourly_cost,billable,notes) VALUES(?,?,?,?,?,?,?,?)',(int(request.form['project']),int(request.form['task']),eid,request.form['date'],float(request.form['hours']),rate,1,request.form.get('notes','')))
       elif a=='expense': c.execute('INSERT INTO project_expenses_v98(project_id,expense_date,category,description,amount,billable) VALUES(?,?,?,?,?,?)',(int(request.form['project']),request.form['date'],request.form['category'],request.form.get('description',''),float(request.form['amount']),int(request.form.get('billable',0))))
       elif a=='milestone': c.execute('INSERT INTO project_milestones_v98(project_id,milestone_no,description,due_date,billing_amount) VALUES(?,?,?,?,?)',(int(request.form['project']),request.form['milestone_no'],request.form['description'],request.form['due'],float(request.form['amount'])))
       c.commit(); flash('تم تحديث المشروع')
      except Exception as e: c.rollback(); flash(str(e))
      c.close(); return redirect('/projects-v98')
    ps=c.execute('SELECT * FROM projects_v98 ORDER BY id DESC').fetchall(); es=c.execute("SELECT * FROM hr_employees_v97 WHERE status='ACTIVE'").fetchall(); ts=c.execute('SELECT t.*,p.project_no FROM project_tasks_v98 t JOIN projects_v98 p ON p.id=t.project_id ORDER BY t.id DESC').fetchall(); cus=c.execute('SELECT * FROM ar_customers_v90 WHERE active=1').fetchall(); c.close()
    po=''.join(f"<option value='{x['id']}'>{x['project_no']} — {html.escape(x['name'])}</option>" for x in ps); eo=''.join(f"<option value='{x['id']}'>{x['employee_no']} — {html.escape(x['name'])}</option>" for x in es); to=''.join(f"<option value='{x['id']}'>{x['project_no']} / {html.escape(x['name'])}</option>" for x in ts); cu=''.join(f"<option value='{x['id']}'>{html.escape(x['name'])}</option>" for x in cus)
    rows=''
