def _safe_scalar_v99(c, sql, params=()):
    try:
        r=c.execute(sql,params).fetchone()
        if not r:return 0.0
        return float(r[0] or 0)
    except Exception:
        return 0.0

def _table_exists_v99(c,name):
    return c.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",(name,)).fetchone() is not None

def _kpis_v99(c):
    k={}
    # Finance from GL if available
    if _table_exists_v99(c,"gl_journal_lines_v85"):
        try:
            revenue=_safe_scalar_v99(c,"SELECT coalesce(sum(credit-debit),0) FROM gl_journal_lines_v85 WHERE account_code LIKE '4%'")
            expense=_safe_scalar_v99(c,"SELECT coalesce(sum(debit-credit),0) FROM gl_journal_lines_v85 WHERE account_code LIKE '5%'")
        except Exception: revenue=expense=0
    else: revenue=expense=0
    net=revenue-expense
    k["REVENUE"]=revenue;k["EXPENSE"]=expense;k["NET_PROFIT"]=net
    k["NET_MARGIN"]=(net/revenue*100) if revenue else 0

    # Inventory
    if _table_exists_v99(c,"stock_ledger_v93"):
        try:
            inv=_safe_scalar_v99(c,"SELECT coalesce(sum((qty_in-qty_out)*unit_cost),0) FROM stock_ledger_v93")
        except Exception: inv=0
    else: inv=0
    k["INVENTORY_VALUE"]=inv

    # AR/AP with graceful fallback
    ar=ap=0
    for tbl in ("ar_invoices_v90","ar_invoices_v91","ar_invoices"):
        if _table_exists_v99(c,tbl):
            try: ar=_safe_scalar_v99(c,f"SELECT coalesce(sum(total_amount-coalesce(paid_amount,0)),0) FROM {tbl}")
            except Exception: pass
            break
    for tbl in ("ap_supplier_invoices_v94","ap_invoices_v90","ap_invoices"):
        if _table_exists_v99(c,tbl):
            try: ap=_safe_scalar_v99(c,f"SELECT coalesce(sum(total_amount-coalesce(paid_amount,0)),0) FROM {tbl}")
            except Exception: pass
            break
    k["AR_OUTSTANDING"]=ar;k["AP_OUTSTANDING"]=ap

    # OEE
    if _table_exists_v99(c,"maintenance_production_stats_v96"):
        rows=c.execute("SELECT planned_hours,run_hours,total_units,good_units,ideal_cycle_minutes FROM maintenance_production_stats_v96").fetchall()
        vals=[]
        for x in rows:
            ph=float(x["planned_hours"] or 0);rh=float(x["run_hours"] or 0);tu=float(x["total_units"] or 0);gu=float(x["good_units"] or 0);cy=float(x["ideal_cycle_minutes"] or 0)
            a=rh/ph if ph else 0;p=(tu*cy/60)/rh if rh else 0;q=gu/tu if tu else 0
            vals.append(a*p*q*100)
        k["OEE"]=sum(vals)/len(vals) if vals else 0
    else:k["OEE"]=0

    # HR absence
    if _table_exists_v99(c,"hr_attendance_v97"):
        total=_safe_scalar_v99(c,"SELECT count(*) FROM hr_attendance_v97")
        absent=_safe_scalar_v99(c,"SELECT count(*) FROM hr_attendance_v97 WHERE status='ABSENT'")
        k["ABSENCE_RATE"]=absent/total*100 if total else 0
    else:k["ABSENCE_RATE"]=0

    # SLA breaches: unresolved beyond contract resolution SLA
    breach=0
    if _table_exists_v99(c,"helpdesk_tickets_v98") and _table_exists_v99(c,"service_contracts_v98"):
        try:
            rows=c.execute("""SELECT t.opened_at,t.resolved_at,c.sla_resolution_hours
            FROM helpdesk_tickets_v98 t JOIN service_contracts_v98 c ON c.id=t.contract_id""").fetchall()
            now=datetime.datetime.now()
            for x in rows:
                op=datetime.datetime.fromisoformat(x["opened_at"]); end=datetime.datetime.fromisoformat(x["resolved_at"]) if x["resolved_at"] else now
                if (end-op).total_seconds()/3600 > float(x["sla_resolution_hours"] or 0): breach+=1
        except Exception:pass
    k["SLA_BREACH"]=breach
    return k

@app.route("/executive-v99")
def executive_v99():
    if session.get("role") not in ("admin","manager","accountant","auditor"):return ("غير مصرح",403)
    c=con();k=_kpis_v99(c)
    projects=[]
    if _table_exists_v99(c,"projects_v98"):
        projects=c.execute("SELECT * FROM projects_v98 ORDER BY id DESC LIMIT 10").fetchall()
    c.close()
    cards=f"""<div class=panel><h2>Executive KPIs</h2>
    <p><b>Revenue:</b> {k['REVENUE']:,.2f} &nbsp; <b>Expenses:</b> {k['EXPENSE']:,.2f} &nbsp; <b>Net Profit:</b> {k['NET_PROFIT']:,.2f} &nbsp; <b>Net Margin:</b> {k['NET_MARGIN']:.1f}%</p>
    <p><b>Inventory:</b> {k['INVENTORY_VALUE']:,.2f} &nbsp; <b>AR:</b> {k['AR_OUTSTANDING']:,.2f} &nbsp; <b>AP:</b> {k['AP_OUTSTANDING']:,.2f}</p>
    <p><b>OEE:</b> {k['OEE']:.1f}% &nbsp; <b>Absence:</b> {k['ABSENCE_RATE']:.1f}% &nbsp; <b>SLA Breaches:</b> {k['SLA_BREACH']}</p></div>"""
    pr="".join(f"<tr><td>{x['project_no']}</td><td>{html.escape(x['name'])}</td><td>{x['budget_revenue']:,.2f}</td><td>{x['budget_cost']:,.2f}</td><td>{x['status']}</td></tr>" for x in projects)
    return page(f"<h1>Business Intelligence & Executive Control Tower v99</h1>{cards}<h2>Projects Snapshot</h2><table><tr><th>Project</th><th>Name</th><th>Revenue Budget</th><th>Cost Budget</th><th>Status</th></tr>{pr}</table>")

@app.route("/bi-alerts-v99",methods=["GET","POST"])
def bi_alerts_v99():
    if session.get("role") not in ("admin","manager","accountant","auditor"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="rule":
                c.execute("INSERT INTO bi_alert_rules_v99(rule_name,kpi_code,operator,threshold,severity) VALUES(?,?,?,?,?)",(request.form["name"],request.form["kpi"],request.form["operator"],float(request.form["threshold"]),request.form["severity"]))
            elif a=="evaluate":
                k=_kpis_v99(c)
                for r in c.execute("SELECT * FROM bi_alert_rules_v99 WHERE active=1").fetchall():
                    v=float(k.get(r["kpi_code"],0));t=float(r["threshold"]);op=r["operator"]
                    hit=(op==">" and v>t) or (op==">=" and v>=t) or (op=="<" and v<t) or (op=="<=" and v<=t) or (op=="==" and abs(v-t)<.0001)
                    if hit:
                        msg=f"{r['kpi_code']} = {v:.2f} {op} {t:.2f}"
                        c.execute("INSERT INTO bi_alert_log_v99(rule_id,kpi_code,actual_value,threshold,severity,message) VALUES(?,?,?,?,?,?)",(r["id"],r["kpi_code"],v,t,r["severity"],msg))
            elif a=="close":
                c.execute("UPDATE bi_alert_log_v99 SET status='CLOSED' WHERE id=?",(int(request.form["alert"]),))
            c.commit();flash("تم تحديث التنبيهات")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/bi-alerts-v99")
    rules=c.execute("SELECT * FROM bi_alert_rules_v99 ORDER BY id DESC").fetchall();alerts=c.execute("SELECT * FROM bi_alert_log_v99 ORDER BY id DESC LIMIT 200").fetchall();c.close()
    ao="".join(f"<option value='{x['id']}'>{x['id']} / {x['kpi_code']} / {x['status']}</option>" for x in alerts)
    rr="".join(f"<tr><td>{x['rule_name']}</td><td>{x['kpi_code']}</td><td>{x['operator']}</td><td>{x['threshold']}</td><td>{x['severity']}</td></tr>" for x in rules)
    ar="".join(f"<tr><td>{x['alert_time']}</td><td>{x['kpi_code']}</td><td>{x['actual_value']:.2f}</td><td>{x['threshold']:.2f}</td><td>{x['severity']}</td><td>{html.escape(x['message'])}</td><td>{x['status']}</td></tr>" for x in alerts)
    return page(f"""<h1>KPI Alerts v99</h1><form method=post class=panel><input type=hidden name=action value=rule><input name=name required placeholder="Rule Name"><select name=kpi><option>NET_MARGIN</option><option>INVENTORY_VALUE</option><option>AR_OUTSTANDING</option><option>AP_OUTSTANDING</option><option>OEE</option><option>ABSENCE_RATE</option><option>SLA_BREACH</option></select><select name=operator><option>&gt;</option><option>&gt;=</option><option>&lt;</option><option>&lt;=</option><option>==</option></select><input name=threshold type=number step=.01 required><select name=severity><option>INFO</option><option selected>WARNING</option><option>CRITICAL</option></select><button>إضافة Rule</button></form><form method=post class=panel><button name=action value=evaluate>Evaluate Now</button><select name=alert>{ao}</select><button name=action value=close>Close Alert</button></form><h2>Rules</h2><table><tr><th>Name</th><th>KPI</th><th>Op</th><th>Threshold</th><th>Severity</th></tr>{rr}</table><h2>Alert Log</h2><table><tr><th>Time</th><th>KPI</th><th>Actual</th><th>Threshold</th><th>Severity</th><th>Message</th><th>Status</th></tr>{ar}</table>""")

