@app.route("/api/v1/health")
def api_health_v101():
    import time
    start=time.time();key=request.headers.get("X-API-Key","");c=con();client=c.execute("SELECT * FROM api_clients_v101 WHERE api_key_hash=? AND active=1",(_hash_key_v101(key),)).fetchone() if key else None
    if not client:
        c.execute("INSERT INTO api_request_log_v101(client_id,method,endpoint,status_code,duration_ms,ip_address,details) VALUES(NULL,?,?,?,?,?,?)",(request.method,request.path,401,(time.time()-start)*1000,request.remote_addr or "","Invalid API key"));c.commit();c.close()
        return {"ok":False,"error":"unauthorized"},401
    c.execute("UPDATE api_clients_v101 SET last_used_at=CURRENT_TIMESTAMP WHERE id=?",(client["id"],))
    c.execute("INSERT INTO api_request_log_v101(client_id,method,endpoint,status_code,duration_ms,ip_address,details) VALUES(?,?,?,?,?,?,?)",(client["id"],request.method,request.path,200,(time.time()-start)*1000,request.remote_addr or "","Health check"));c.commit();c.close()
    return {"ok":True,"product":"Sati ERP","version":"v101","api":"v1"}

