@app.route("/document-workflow-v103",methods=["GET","POST"])
def document_workflow_v103():
    if session.get("role") not in ("admin","manager","auditor","accountant","hr"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="approval":
                did=int(request.form["document"]);v=c.execute("SELECT id FROM dms_versions_v103 WHERE document_id=? ORDER BY version_no DESC LIMIT 1",(did,)).fetchone()
                c.execute("INSERT INTO dms_approvals_v103(document_id,version_id,approver,step_no) VALUES(?,?,?,?)",(did,v["id"] if v else None,request.form["approver"],int(request.form.get("step") or 1)))
                c.execute("UPDATE dms_documents_v103 SET status='IN_REVIEW' WHERE id=?",(did,))
            elif a=="decision":
                aid=int(request.form["approval"]);decision=request.form["decision"]
                ap=c.execute("SELECT * FROM dms_approvals_v103 WHERE id=?",(aid,)).fetchone()
                c.execute("UPDATE dms_approvals_v103 SET status=?,comments=?,decision_at=CURRENT_TIMESTAMP WHERE id=?",(decision,request.form.get("comments",""),aid))
                if decision=="APPROVED":c.execute("UPDATE dms_documents_v103 SET status='APPROVED' WHERE id=?",(ap["document_id"],))
                elif decision=="REJECTED":c.execute("UPDATE dms_documents_v103 SET status='REJECTED' WHERE id=?",(ap["document_id"],))
                audit_v100(c,"DMS","DOCUMENT_"+decision,"DOCUMENT",ap["document_id"])
            elif a=="signature":
                did=int(request.form["document"]);v=c.execute("SELECT id FROM dms_versions_v103 WHERE document_id=? ORDER BY version_no DESC LIMIT 1",(did,)).fetchone()
                c.execute("INSERT INTO dms_signature_requests_v103(document_id,version_id,signer_name,signer_email,provider) VALUES(?,?,?,?,?)",(did,v["id"] if v else None,request.form["signer"],request.form["email"],request.form.get("provider","EXTERNAL")))
            elif a=="ocr":
                vid=int(request.form["version"])
                c.execute("INSERT INTO dms_ocr_metadata_v103(version_id,ocr_status,language) VALUES(?,?,?)",(vid,"QUEUED",request.form.get("language","ar")))
            c.commit();flash("تم تحديث سير المستند")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/document-workflow-v103")
    docs=c.execute("SELECT * FROM dms_documents_v103 ORDER BY id DESC").fetchall();vers=c.execute("SELECT v.*,d.document_no FROM dms_versions_v103 v JOIN dms_documents_v103 d ON d.id=v.document_id ORDER BY v.id DESC").fetchall();aps=c.execute("SELECT a.*,d.document_no,d.title FROM dms_approvals_v103 a JOIN dms_documents_v103 d ON d.id=a.document_id ORDER BY a.id DESC").fetchall();sigs=c.execute("SELECT s.*,d.document_no FROM dms_signature_requests_v103 s JOIN dms_documents_v103 d ON d.id=s.document_id ORDER BY s.id DESC").fetchall();c.close()
    do="".join(f"<option value='{x['id']}'>{x['document_no']} — {html.escape(x['title'])}</option>" for x in docs);vo="".join(f"<option value='{x['id']}'>{x['document_no']} / v{x['version_no']}</option>" for x in vers);ao="".join(f"<option value='{x['id']}'>{x['document_no']} / {x['approver']} / {x['status']}</option>" for x in aps)
    ar="".join(f"<tr><td>{x['document_no']}</td><td>{html.escape(x['title'])}</td><td>{x['approver']}</td><td>{x['step_no']}</td><td>{x['status']}</td><td>{x['decision_at'] or ''}</td></tr>" for x in aps)
    sr="".join(f"<tr><td>{x['document_no']}</td><td>{html.escape(x['signer_name'])}</td><td>{html.escape(x['signer_email'])}</td><td>{x['provider']}</td><td>{x['status']}</td></tr>" for x in sigs)
    return page(f"""<h1>Document Workflow v103</h1><form method=post class=panel><input type=hidden name=action value=approval><select name=document>{do}</select><input name=approver required placeholder="Approver"><input name=step type=number value=1><button>طلب اعتماد</button></form><form method=post class=panel><input type=hidden name=action value=decision><select name=approval>{ao}</select><select name=decision><option>APPROVED</option><option>REJECTED</option></select><input name=comments placeholder="Comments"><button>قرار الاعتماد</button></form><form method=post class=panel><input type=hidden name=action value=signature><select name=document>{do}</select><input name=signer required placeholder="Signer Name"><input name=email type=email required placeholder="Signer Email"><input name=provider value="EXTERNAL" placeholder="E-sign Provider"><button>إنشاء Signature Request</button></form><form method=post class=panel><input type=hidden name=action value=ocr><select name=version>{vo}</select><input name=language value="ar" placeholder="OCR Language"><button>Queue OCR</button></form><h2>Approvals</h2><table><tr><th>Document</th><th>Title</th><th>Approver</th><th>Step</th><th>Status</th><th>Decision</th></tr>{ar}</table><h2>E-Signature Requests</h2><table><tr><th>Document</th><th>Signer</th><th>Email</th><th>Provider</th><th>Status</th></tr>{sr}</table>""")

@app.route("/contracts-v103",methods=["GET","POST"])
def contracts_v103():
    if session.get("role") not in ("admin","manager","auditor","accountant","sales","project"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="contract":
                c.execute("INSERT INTO dms_contracts_v103(document_id,contract_no,party_name,contract_type,start_date,end_date,contract_value,renewal_type,notice_days) VALUES(?,?,?,?,?,?,?,?,?)",(int(request.form["document"]),request.form["contract_no"],request.form["party"],request.form["type"],request.form["start"],request.form["end"],float(request.form.get("value") or 0),request.form["renewal"],int(request.form.get("notice") or 30)))
            elif a=="alerts":
                today=datetime.date.today()
                rows=c.execute("SELECT * FROM dms_contracts_v103 WHERE status='ACTIVE'").fetchall()
                for x in rows:
                    end=datetime.date.fromisoformat(x["end_date"]);alert=end-datetime.timedelta(days=int(x["notice_days"] or 30))
                    if alert<=today<=end:
                        exists=c.execute("SELECT 1 FROM dms_expiry_alerts_v103 WHERE contract_id=? AND status='OPEN'",(x["id"],)).fetchone()
                        if not exists:c.execute("INSERT INTO dms_expiry_alerts_v103(document_id,contract_id,alert_date,alert_type) VALUES(?,?,?,?)",(x["document_id"],x["id"],str(today),"CONTRACT_EXPIRY"))
            c.commit();flash("تم تحديث العقود والتنبيهات")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/contracts-v103")
    docs=c.execute("SELECT * FROM dms_documents_v103 ORDER BY id DESC").fetchall();contracts=c.execute("SELECT x.*,d.document_no,d.title FROM dms_contracts_v103 x JOIN dms_documents_v103 d ON d.id=x.document_id ORDER BY x.id DESC").fetchall();alerts=c.execute("SELECT a.*,x.contract_no,x.party_name FROM dms_expiry_alerts_v103 a JOIN dms_contracts_v103 x ON x.id=a.contract_id ORDER BY a.id DESC").fetchall();c.close()
    do="".join(f"<option value='{x['id']}'>{x['document_no']} — {html.escape(x['title'])}</option>" for x in docs)
    rr="".join(f"<tr><td>{x['contract_no']}</td><td>{html.escape(x['party_name'])}</td><td>{x['contract_type']}</td><td>{x['start_date']}</td><td>{x['end_date']}</td><td>{x['contract_value']:,.2f}</td><td>{x['renewal_type']}</td><td>{x['status']}</td></tr>" for x in contracts)
    ar="".join(f"<tr><td>{x['alert_date']}</td><td>{x['contract_no']}</td><td>{html.escape(x['party_name'])}</td><td>{x['alert_type']}</td><td>{x['status']}</td></tr>" for x in alerts)
    return page(f"""<h1>Contracts Repository v103</h1><form method=post class=panel><input type=hidden name=action value=contract><select name=document>{do}</select><input name=contract_no required placeholder="Contract No"><input name=party required placeholder="Party"><input name=type required placeholder="Contract Type"><input type=date name=start required><input type=date name=end required><input name=value type=number step=.01 value=0 placeholder="Contract Value"><select name=renewal><option>MANUAL</option><option>AUTO</option><option>NONE</option></select><input name=notice type=number value=30 placeholder="Notice Days"><button>إضافة عقد</button></form><form method=post class=panel><button name=action value=alerts>Generate Expiry Alerts</button></form><table><tr><th>Contract</th><th>Party</th><th>Type</th><th>Start</th><th>End</th><th>Value</th><th>Renewal</th><th>Status</th></tr>{rr}</table><h2>Expiry Alerts</h2><table><tr><th>Date</th><th>Contract</th><th>Party</th><th>Type</th><th>Status</th></tr>{ar}</table>""")


