def _treasury_no_v105(prefix):
    return prefix+"-"+datetime.datetime.now().strftime("%Y%m%d%H%M%S%f")

def _bank_balance_v105(c,bank_id):
    a=c.execute("SELECT opening_balance FROM treasury_bank_accounts_v105 WHERE id=?",(bank_id,)).fetchone()
    opening=float(a["opening_balance"] or 0) if a else 0
    x=c.execute("SELECT coalesce(sum(credit-debit),0) x FROM treasury_transactions_v105 WHERE bank_account_id=?",(bank_id,)).fetchone()
    return opening+float(x["x"] or 0)

@app.route("/treasury-v105",methods=["GET","POST"])
def treasury_v105():
    if session.get("role") not in ("admin","manager","accountant"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="account":
                c.execute("INSERT INTO treasury_bank_accounts_v105(account_code,bank_name,account_name,iban,currency,gl_account,opening_balance) VALUES(?,?,?,?,?,?,?)",(request.form["code"],request.form["bank"],request.form["name"],request.form.get("iban",""),request.form.get("currency","SAR"),request.form.get("gl",""),float(request.form.get("opening") or 0)))
                audit_v100(c,"TREASURY","CREATE_BANK_ACCOUNT","BANK_ACCOUNT",request.form["code"])
            elif a=="transaction":
                debit=float(request.form.get("debit") or 0);credit=float(request.form.get("credit") or 0)
                if debit and credit:raise ValueError("استخدم Debit أو Credit فقط")
                c.execute("INSERT INTO treasury_transactions_v105(bank_account_id,txn_date,txn_type,reference,description,debit,credit,external_ref) VALUES(?,?,?,?,?,?,?,?)",(int(request.form["bank_account"]),request.form["date"],request.form["type"],request.form.get("reference",""),request.form.get("description",""),debit,credit,request.form.get("external_ref","")))
                audit_v100(c,"TREASURY","BANK_TRANSACTION","BANK_ACCOUNT",request.form["bank_account"])
            c.commit();flash("تم تحديث الخزينة")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/treasury-v105")
    accounts=c.execute("SELECT * FROM treasury_bank_accounts_v105 WHERE active=1 ORDER BY bank_name,account_name").fetchall();tx=c.execute("SELECT t.*,a.bank_name,a.account_name FROM treasury_transactions_v105 t JOIN treasury_bank_accounts_v105 a ON a.id=t.bank_account_id ORDER BY t.txn_date DESC,t.id DESC LIMIT 500").fetchall()
    cards=[]
    for a in accounts:cards.append(f"<tr><td>{a['account_code']}</td><td>{html.escape(a['bank_name'])}</td><td>{html.escape(a['account_name'])}</td><td>{html.escape(a['iban'] or '')}</td><td>{a['currency']}</td><td>{_bank_balance_v105(c,a['id']):,.2f}</td></tr>")
    c.close()
    bo="".join(f"<option value='{x['id']}'>{x['account_code']} — {html.escape(x['bank_name'])}</option>" for x in accounts)
    tr="".join(f"<tr><td>{x['txn_date']}</td><td>{html.escape(x['bank_name'])}</td><td>{x['txn_type']}</td><td>{html.escape(x['reference'] or '')}</td><td>{x['debit']:,.2f}</td><td>{x['credit']:,.2f}</td><td>{'YES' if x['reconciled'] else 'NO'}</td></tr>" for x in tx)
    return page(f"""<h1>Treasury & Banking v105</h1><form method=post class=panel><input type=hidden name=action value=account><input name=code required placeholder="Account Code"><input name=bank required placeholder="Bank Name"><input name=name required placeholder="Account Name"><input name=iban placeholder="IBAN"><input name=currency value="SAR"><input name=gl placeholder="GL Account"><input name=opening type=number step=.01 value=0 placeholder="Opening Balance"><button>إضافة حساب بنكي</button></form><form method=post class=panel><input type=hidden name=action value=transaction><select name=bank_account>{bo}</select><input type=date name=date value="{datetime.date.today()}" required><select name=type><option>DEPOSIT</option><option>WITHDRAWAL</option><option>TRANSFER</option><option>FEE</option><option>INTEREST</option><option>OTHER</option></select><input name=reference placeholder="Reference"><input name=description placeholder="Description"><input name=debit type=number step=.01 value=0 placeholder="Debit / Outflow"><input name=credit type=number step=.01 value=0 placeholder="Credit / Inflow"><input name=external_ref placeholder="Bank External Ref"><button>تسجيل حركة</button></form><h2>Cash Position</h2><table><tr><th>Code</th><th>Bank</th><th>Account</th><th>IBAN</th><th>Currency</th><th>Book Balance</th></tr>{''.join(cards)}</table><h2>Bank Transactions</h2><table><tr><th>Date</th><th>Bank</th><th>Type</th><th>Ref</th><th>Debit</th><th>Credit</th><th>Reconciled</th></tr>{tr}</table>""")

@app.route("/bank-reconciliation-v105",methods=["GET","POST"])
def bank_reconciliation_v105():
    if session.get("role") not in ("admin","manager","accountant","auditor"):return ("غير مصرح",403)
    c=con()
    if request.method=="POST":
        try:
            a=request.form["action"]
            if a=="reconcile":
                bid=int(request.form["bank_account"]);statement=float(request.form["statement_balance"]);book=_bank_balance_v105(c,bid);diff=statement-book
                tol=float(c.execute("SELECT reconciliation_tolerance FROM treasury_settings_v105 WHERE id=1").fetchone()["reconciliation_tolerance"])
                status="RECONCILED" if abs(diff)<=tol else "OPEN"
                c.execute("INSERT INTO treasury_reconciliation_v105(bank_account_id,statement_date,statement_balance,book_balance,difference,status,reconciled_at,created_by) VALUES(?,?,?,?,?,?,?,?)",(bid,request.form["date"],statement,book,diff,status,datetime.datetime.now().isoformat() if status=="RECONCILED" else None,session.get("user","")))
                if status=="RECONCILED":c.execute("UPDATE treasury_transactions_v105 SET reconciled=1 WHERE bank_account_id=? AND txn_date<=?",(bid,request.form["date"]))
                audit_v100(c,"TREASURY","RECONCILE","BANK_ACCOUNT",bid,"",status)
            c.commit();flash("تم تنفيذ المطابقة البنكية")
        except Exception as e:c.rollback();flash(str(e))
        c.close();return redirect("/bank-reconciliation-v105")
    accounts=c.execute("SELECT * FROM treasury_bank_accounts_v105 WHERE active=1").fetchall();rows=c.execute("SELECT r.*,a.bank_name,a.account_name FROM treasury_reconciliation_v105 r JOIN treasury_bank_accounts_v105 a ON a.id=r.bank_account_id ORDER BY r.id DESC").fetchall();c.close()
    bo="".join(f"<option value='{x['id']}'>{html.escape(x['bank_name'])} — {html.escape(x['account_name'])}</option>" for x in accounts)
    rr="".join(f"<tr><td>{x['statement_date']}</td><td>{html.escape(x['bank_name'])}</td><td>{x['statement_balance']:,.2f}</td><td>{x['book_balance']:,.2f}</td><td>{x['difference']:,.2f}</td><td>{x['status']}</td></tr>" for x in rows)
    return page(f"""<h1>Bank Reconciliation v105</h1><form method=post class=panel><input type=hidden name=action value=reconcile><select name=bank_account>{bo}</select><input type=date name=date value="{datetime.date.today()}" required><input name=statement_balance type=number step=.01 required placeholder="Bank Statement Balance"><button>مطابقة</button></form><table><tr><th>Date</th><th>Bank</th><th>Statement</th><th>Book</th><th>Difference</th><th>Status</th></tr>{rr}</table>""")

@app.route("/payments-v105",methods=["GET","POST"])
def payments_v105():
    if session.get("role") not in ("admin","manager","accountant"):return ("غير مصرح",403)
    c=con()
