                c.execute("INSERT INTO asset_categories_v106(code,name,useful_life_months,depreciation_method,asset_gl,accum_depr_gl,depr_expense_gl,disposal_gl) VALUES(?,?,?,?,?,?,?,?)",(request.form["code"],request.form["name"],int(request.form["life"]),request.form["method"],request.form.get("asset_gl",""),request.form.get("accum_gl",""),request.form.get("expense_gl",""),request.form.get("disposal_gl","")))
