    return page(f"""<h1>Fixed Asset Reports v106</h1><div class=panel><b>Total Cost:</b> {total_cost:,.2f} &nbsp; <b>Accumulated Depreciation:</b> {total_dep:,.2f} &nbsp; <b>Net Book Value:</b> {book:,.2f} &nbsp; <b>Active:</b> {active} &nbsp; <b>Disposed:</b> {disposed}</div><table><tr><th>Asset</th><th>Name</th><th>Category</th><th>Tag</th><th>Serial</th><th>Cost</th><th>Accum Dep</th><th>Book Value</th><th>Status</th></tr>{rr}</table>""")

